seatsio.ChartDesigner.prototype.retrieveDrawing = function () {
    var me = this
    if (this.openLatestDrawing) {
        return this.retrieveLatestDrawing()
    }

    if (this.openDraftDrawing) {
        return this.v2Client.retrieveDraftDrawing(this.chartKey)
            .then(function (drawing) {
                me.renderDrawing(drawing)
            })
    }
    return this.v2Client.retrievePublishedDrawing(this.chartKey)
        .then(function (drawing) {
            me.renderDrawing(drawing)
        })
}

seatsio.ChartDesigner.prototype.retrieveLatestDrawing = function () {
    let draftVersionExists = this.status === 'PUBLISHED_WITH_DRAFT'
    let drawingPromise = draftVersionExists ? this.v2Client.retrieveDraftDrawing(this.chartKey) : this.v2Client.retrievePublishedDrawing(this.chartKey)
    return drawingPromise.then(drawing => this.renderDrawing(drawing))
}

seatsio.ChartDesigner.prototype.renderDrawing = function (drawing) {
    this.renderUI()
    setTimeout(() => {
        this.fromJson(drawing)
        seatsio.initializeEventHandlers(this)
        this.chartLoaded = true
        this.renderUI()
        this.showMasterSubChart()
        let initialDrawing = this.serialize()
        this.history.changeState(initialDrawing)
        this.stateChangeDetector.start(initialDrawing)
        this.panner.start()
    }, 30)
}

seatsio.ChartDesigner.prototype.createStateChangeDetector = function () {
    var me = this

    function updateHistory (drawing) {
        me.history.changeState(drawing)
        me.renderUI()
    }

    function save (drawing) {
        return me.saver.save(drawing)
    }

    return new seatsio.StateChangeDetector(this, [updateHistory, save])
}

seatsio.ChartDesigner.prototype.saveNowIfNeeded = function () {
    return this.stateChangeDetector.actOnStateChangeWhenPreviousCycleDone()
}

seatsio.ChartDesigner.prototype.saveAndExit = function () {
    let me = this
    this.saveNowIfNeeded().then(me.onExitRequested)
}

seatsio.ChartDesigner.prototype.setStatus = function (newStatus) {
    if (this.status && this.status !== newStatus && newStatus === 'PUBLISHED_WITH_DRAFT') {
        this.openDraftDrawing = true
    }
    this.status = newStatus
    this.onStatusChanged(newStatus)
    this.renderUI()
}

seatsio.ChartDesigner.prototype.isPublished = function () {
    return this.status === 'PUBLISHED' || this.status === 'PUBLISHED_WITH_DRAFT'
}

seatsio.ChartDesigner.prototype.isReferenceChartScannerAvailable = function () {
    if (!this.v2Client.getWorkspaceSettings().canUseReferenceChartScanner) {
        return false
    }

    let showReferenceChartScannerInEmbeddedDesigner = this.v2Client.getWorkspaceSettings().showReferenceChartScannerInEmbeddedDesigner
    return this.isWebapp || showReferenceChartScannerInEmbeddedDesigner
}

seatsio.ChartDesigner.prototype.supportsSections = function () {
    return this.getVenueSettings().supportsSections
}

seatsio.ChartDesigner.prototype.onZoom = function () {
    this.activeSubChart().allObjects().forEach(object => object.applyZoom())
    this.subChartFloors.applyZoom()
    this.getState().reenter()
    this.refreshToolProperties()
}

seatsio.ChartDesigner.prototype.zoomIn = function () {
    this.zoomer.zoomIn(this.pointInCanvasCenteredInViewport())
}

seatsio.ChartDesigner.prototype.zoomOut = function () {
    this.zoomer.zoomOut(this.pointInCanvasCenteredInViewport())
}

seatsio.ChartDesigner.prototype.isSafeMode = function () {
    return !this.isReadOnly() && this.mode === seatsio.ConfigParser.Modes.SAFE
}

seatsio.ChartDesigner.prototype.isSafeModeAndPublished = function () {
    return this.isSafeMode() && this.isPublished()
}

seatsio.ChartDesigner.prototype.getSafeModeOption = function (actionName) {
    if (this.safeModeOptions) {
        return this.safeModeOptions[actionName]
    }
    return undefined
}

seatsio.ChartDesigner.prototype.isReadOnly = function () {
    return this.anonymous() || this.mode === seatsio.ConfigParser.Modes.READ_ONLY || (!this.openDraftDrawing && !this.openLatestDrawing && this.status === 'PUBLISHED_WITH_DRAFT')
}

seatsio.ChartDesigner.prototype.atMasterSubChart = function () {
    return this.sectionSubChart === null
}

seatsio.ChartDesigner.prototype.goToFloor = function (floorIndex) {
    if (this.subChartFloors.hasFloor(floorIndex)) {
        this.subChartFloors.setFloor(floorIndex)
        this.showMasterSubChart(this.subChartFloors.getCurrentMasterSubChart())
    }
}

seatsio.ChartDesigner.prototype.createFloor = function (goToAfterCreating = false) {
    this.subChartFloors.newSubChart()
    if (goToAfterCreating) this.goToFloor(this.subChartFloors.length() - 1)
    this.renderUI()
}

seatsio.ChartDesigner.prototype.deleteFloor = function (floorIndex) {
    if (this.subChartFloors.hasFloor(floorIndex)) {
        this.subChartFloors.deleteFloor(floorIndex)
        if (this.subChartFloors.length() === 0) {
            this.subChartFloors.currentFloor = -1
            this.createFloor(true)
        } else {
            this.goToFloor(Math.max(0, floorIndex - 1))
        }
    }
}

seatsio.ChartDesigner.prototype.setFloorDisplayName = function (floorIndex, name) {
    if (this.subChartFloors.hasFloor(floorIndex)) {
        this.subChartFloors.setFloorDisplayName(floorIndex, name)
    }
}

seatsio.ChartDesigner.prototype.setFloorName = function (floorIndex, name) {
    if (this.subChartFloors.hasFloor(floorIndex)) {
        this.subChartFloors.setFloorName(floorIndex, name)
    }
}

seatsio.ChartDesigner.prototype.setupCanvasEventHandlers = function () {
    var me = this
    const body = document.querySelector('body')
    const thereIsFocusedInput = () => $('input:focus, *[contenteditable="true"]:focus').length > 0

    this.canvas().bind('contextmenu', function () {
        return false
    })

    window.addEventListener('blur', () => {
        this.keyboard.releaseAllModifierKeys()
        this.renderUI()
    })

    window.addEventListener('wheel', () => {
        if (this.mouseHover) {
            body.style.overflow = 'auto'
        } else {
            body.style.overflow = 'hidden'
        }
    })

    window.addEventListener('mouseup', e => {
        this.panner.stopEdgePanning()
        if (this.debug) {
            // eslint-disable-next-line no-console
            console.log(this.prependState('onWindowMouseUp'))
        }
        if (this.leftMouseButton(e) && this.mouseDown) {
            this.mouseDown = false
            this.state.onCanvasMouseUp(e, this)
        } else {
            this.rightMouseButtonPressed = false
            this.renderUI()
        }
    }, { capture: true })

    this.canvas().mousedown(function (e) {
        // Preventing browser-based page scrolling, resulting in uncontrolled canvas panning.
        e.preventDefault()
        if (me.debug) {
            // eslint-disable-next-line no-console
            console.log(me.prependState('onCanvasMouseDown'))
        }
        if (me.leftMouseButton(e)) {
            me.mouseDown = true
            me.state.onCanvasMouseDown(e, me)
        } else {
            me.rightMouseButtonPressed = true
            me.state.onCanvasRightMouseButtonDown(e, me)
            me.renderUI()
        }
    })

    this.canvas().mousemove(e => {
        this.lastMouseMoveEvent = e
        this.state.onCanvasMouseMove(e, this)
        if (this.mouseDown) {
            this.panner.refreshEdgePanning(seatsio.Point.fromMouseEvent(e))
        }
    })

    this.canvas().mouseenter(_e => {
        this.mouseHover = true
    })

    this.canvas().mouseleave(function (e) {
        if (me.debug) {
            // eslint-disable-next-line no-console
            console.log(me.prependState('onCanvasMouseLeave'))
        }
        me.mouseHover = false
        me.state.onCanvasMouseLeave(e, me)
    })

    this.canvas().clickWhenNotDragged(function (e) {
        if (me.mustNextCanvasClickBeIgnored) {
            me.mustNextCanvasClickBeIgnored = false
            return
        }
        if (me.debug) {
            // eslint-disable-next-line no-console
            console.log(me.prependState('onCanvasClick'))
        }
        me.state.onCanvasClick(e, me)
    })

    this.canvas().on('gesturestart', e => {
        me.keyboard.onGestureStart(e)
    })

    this.canvas().on('gesturechange', e => {
        me.keyboard.onGestureChange(e)
    })

    this.canvas().on('gestureend', e => {
        me.keyboard.onGestureEnd(e)
    })

    this.canvas().on('wheel', e => {
        if (thereIsFocusedInput()) {
            return
        }
        me.keyboard.onWheel(e)
    })

    window.addEventListener('keydown', e => {
        if (me.keyboard.pageUpPressed(e) || me.keyboard.pageDownPressed(e) || me.keyboard.homePressed(e) || me.keyboard.endPressed(e)) {
            e.preventDefault()
            return
        }

        if (thereIsFocusedInput()) {
            return
        }
        me.keyboard.onKeyDown(e)
    })

    window.addEventListener('keyup', e => {
        if (thereIsFocusedInput()) {
            return
        }
        me.keyboard.onKeyUp(e)
    })
}

seatsio.ChartDesigner.prototype.container = function () {
    return $('#' + this.containerId)
}

seatsio.ChartDesigner.prototype.viewport = function () {
    let topLeft = new seatsio.Point(
        seatsio.PANEL_DIMENSIONS.leftPanelWidth,
        seatsio.PANEL_DIMENSIONS.topPanelHeight
    )
    let bottomRight = new seatsio.Point(
        window.innerWidth - seatsio.PANEL_DIMENSIONS.rightPanelWidth,
        window.innerHeight - seatsio.PANEL_DIMENSIONS.bottomPanelHeight
    )
    return seatsio.Bbox.fromTopLeftAndLowerRight(topLeft, bottomRight)
}

seatsio.ChartDesigner.prototype.drawRectangle = function (x1, y1, x2, y2) {
    var startX = Math.min(x1, x2)
    var startY = Math.min(y1, y2)
    var width = Math.abs(x1 - x2)
    var height = Math.abs(y1 - y2)
    return this.drawer.rect(startX, startY, width, height).applyZoom(this)
}

seatsio.ChartDesigner.prototype.getLinePath = function (startX, startY, endX, endY) {
    return 'M' + startX + ',' + startY + 'L' + endX + ',' + endY
}

seatsio.ChartDesigner.prototype.drawLineBetweenPoints = function (start, end) {
    return this.drawer.path(this.getLinePath(start.x, start.y, end.x, end.y)).applyZoom(this)
}

seatsio.ChartDesigner.prototype.drawLineFromPointToPoint = function (points) {
    let pathString = 'M' + points.map(point => point.x + ',' + point.y).join('L')
    return this.drawer.path(pathString).applyZoom(this)
}

seatsio.ChartDesigner.prototype.drawLine = function (startX, startY, endX, endY, strokeWidth, opacity) {
    if (typeof strokeWidth === 'undefined') {
        strokeWidth = 1
    }
    if (typeof opacity === 'undefined') {
        opacity = 0.25
    }
    return this.drawer.path(this.getLinePath(startX, startY, endX, endY),
        {
            'stroke-width': strokeWidth,
            'opacity': opacity
        })
        .applyZoom(this)
}

seatsio.ChartDesigner.prototype.setCursor = function (cursor) {
    if (this.cursor === cursor) return
    this.cursor = cursor
    this.canvas()
        .css('cursor', cursor)
        .attr('class', 'custom-cursor cursor-' + cursor)
}

seatsio.ChartDesigner.prototype.setCursorToDefault = function () {
    if (this.getState().cursor) {
        this.setCursor(this.getState().cursor)
    } else {
        this.canvas()
            .css('cursor', null)
            .attr('class', null)
        this.cursor = null
    }
}

seatsio.ChartDesigner.prototype.applyBaseColor = function (baseColor) {
    if (!baseColor) {
        return
    }
    less.modifyVars({
        '@baseColor': baseColor
    })
}

seatsio.ChartDesigner.prototype.setCursorToNone = function () {
    this.canvas().css('cursor', 'url(\'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAAAJcEhZcwAADsMAAA7DAcdvqGQAAAAZdEVYdFNvZnR3YXJlAFBhaW50Lk5FVCB2My41LjbQg61aAAAADUlEQVQYV2P4//8/IwAI/QL/+TZZdwAAAABJRU5ErkJggg==\'), none')
}

seatsio.ChartDesigner.prototype.showMasterSubChart = function (goToMasterSubChart = null) {
    this.changeViewProcedures(() => {
        if (this.sectionSubChart === null) {
            this.setDefaultState()
        } else if (!goToMasterSubChart) {
            this.setState(new seatsio.ObjectsSelectedState(this, [this.sectionSubChart.section]))
        }
        this.activeSubChart().undraw()
        if (this.atMasterSubChart() && goToMasterSubChart) {
            this.saveZoomAndPan()
        }
        this.sectionSubChart = null
        if (goToMasterSubChart) {
            this.masterSubChart = goToMasterSubChart
        }
        this.activeSubChart().draw()
        if (this.viewFromSeatsShown) {
            this.showViewFromSeats()
        }
        this.refreshBackgroundColor()
        if (this.savedZoomAndPan) {
            this.restoreZoomAndPan()
        } else {
            this.centerCanvasAndFillScreen()
        }
        this.subChartFloors.redrawAbstractFloors()
    })
    requestAnimationFrame(() => {
        this.updateStats()
        if (this.labelsShown) {
            this.showLabels()
        }
    })
    this.requestRenderUI()
}

seatsio.ChartDesigner.prototype.getCanvasColorScheme = function () {
    return this.canvasColorScheme === 'auto' ? this.colorScheme : this.canvasColorScheme
}

seatsio.ChartDesigner.prototype.isDarkCanvas = function () {
    return this.getCanvasColorScheme() !== 'light'
}

seatsio.ChartDesigner.prototype.refreshBackgroundColor = function () {
    let color = this.isDarkCanvas() ? 'black' : 'white'
    if (!this.atMasterSubChart()) {
        color = this.isDarkCanvas() ? 'hsl(200, 1%, 15%)' : 'hsl(200, 5%, 90%)'
    }
    this.canvas().css('background-color', color)
}

seatsio.ChartDesigner.prototype.showSectionSubChart = function (section) {
    this.changeViewProcedures(() => {
        if (section.zone) {
            this.zones.setCurrentZone(section.zone)
        }
        this.subChartFloors.removeAbstractFloors()
        this.saveZoomAndPan()
        this.exitState()
        this.activeSubChart().undraw()
        this.sectionSubChart = section.sectionSubChart
        this.setDefaultState()
        this.activeSubChart().refreshOutOfBounds()
        this.activeSubChart().draw()
        if (this.labelsShown) this.activeSubChart().showLabels()
        this.refreshBackgroundColor()
        this.centerCanvasAndFillScreen()
        if (this.activeSubChart().getReferenceChart().isSet()) {
            this.openReferenceChartWizardForSection()
        }
    })
    this.requestRenderUI()
    requestAnimationFrame(() => {
        this.updateStats()
    })
}

seatsio.ChartDesigner.prototype.openReferenceChartWizardForSection = function () {
    if (this.isReferenceChartScannerAvailable()) {
        if (this.activeSubChart().isEmpty()) {
            this.uiEvents.openReferenceChartScanningDialog()
        }
    }
}

seatsio.ChartDesigner.prototype.saveZoomAndPan = function () {
    this.savedZoomAndPan = {
        pan: this.panner.serialize(),
        zoom: this.zoomer.serialize()
    }
}

seatsio.ChartDesigner.prototype.restoreZoomAndPan = function () {
    this.panner.deserialize(this.savedZoomAndPan.pan)
    this.zoomer.deserialize(this.savedZoomAndPan.zoom)
    this.savedZoomAndPan = null
}

seatsio.ChartDesigner.prototype.setDefaultState = function () {
    this.setState(new seatsio.SelectionModeState(this))
}

seatsio.ChartDesigner.prototype.changeViewProcedures = function (block) {
    this.changingView = true
    block()
    this.changingView = false
}

seatsio.ChartDesigner.prototype.centerCanvasAndFillScreen = function () {
    this.fitActiveSubChartToViewport()
    this.centerCanvasInViewport()
}

seatsio.ChartDesigner.prototype.centerCanvasInViewport = function () {
    let panLevelToCenterCanvasInViewport = this.panLevelToCenterChartInViewport()
    this.panner.panTo(panLevelToCenterCanvasInViewport.x, panLevelToCenterCanvasInViewport.y)
}

seatsio.ChartDesigner.prototype.pointInCanvasCenteredInViewport = function () {
    let panDiffFromCanvasCenteredInViewport = this.panLevelToCenterCanvasInViewport().subtract(this.panner.panLevel())
    return this.canvasCenter.subtract(panDiffFromCanvasCenteredInViewport)
}

seatsio.ChartDesigner.prototype.panLevelToCenterCanvasInViewport = function () {
    return new seatsio.Point(this.canvasCenter.x - this.viewport().center().x, this.canvasCenter.y - this.viewport().center().y)
}

seatsio.ChartDesigner.prototype.panLevelToCenterChartInViewport = function () {
    let zoomedCanvasCenter = this.zoomedCanvasCenter()
    return new seatsio.Point(zoomedCanvasCenter.x - this.viewport().center().x, zoomedCanvasCenter.y - this.viewport().center().y)
}

seatsio.ChartDesigner.prototype.zoomedCanvasCenter = function () {
    return this.zoomer.applyToPoint(this.canvasCenter)
}

seatsio.ChartDesigner.prototype.doesPointSnapToHelperLines = function (point) {
    if (this.altWasPressed) {
        return false
    }
    const pointSnappedToHelperLines = this.helperLines.snapTo(point)
    return pointSnappedToHelperLines && point.distanceToPoint(pointSnappedToHelperLines)
}

seatsio.ChartDesigner.prototype.snapPointToHelperLines = function (point) {
    return this.doesPointSnapToHelperLines(point)
        ? this.helperLines.snapTo(point)
        : point
}

seatsio.ChartDesigner.prototype.snapPointToGrid = function (point) {
    return point.snapToGrid()
}

seatsio.ChartDesigner.prototype.snapPoint = function (point) {
    if (this.altWasPressed) {
        this.undrawHelperLines()
        return point
    }
    var pointSnappedToHelperLines = this.helperLines.snapTo(point)
    if (pointSnappedToHelperLines && point.distanceToPoint(pointSnappedToHelperLines)) {
        return pointSnappedToHelperLines
    }
    return point.snapToGrid()
}

seatsio.ChartDesigner.prototype.fitActiveSubChartToViewport = function () {
    let fitToWidthZoomLevel = this.viewport().width / this.activeSubChart().autoSizedWidth
    let fitToHeightZoomLevel = this.viewport().height / this.activeSubChart().autoSizedHeight
    let zoomLevel = Math.min(fitToHeightZoomLevel, fitToWidthZoomLevel, 1) * 0.9
    this.zoomer.resetAndZoom(this.canvasCenter, zoomLevel)
}

seatsio.ChartDesigner.prototype.prependState = function (s) {
    return this.state.name + '.' + s
}

seatsio.ChartDesigner.prototype.leftMouseButton = function (e) {
    return e.which === 1
}

seatsio.ChartDesigner.prototype.ignoreNextCanvasClick = function () {
    this.mustNextCanvasClickBeIgnored = true
}

seatsio.ChartDesigner.prototype.onDuplicate = function () {
    if (this.features.isDisabled(seatsio.Features.Type.CONTEXT_ACTIONS)) {
        return
    }
    if (this.debug) {
        // eslint-disable-next-line no-console
        console.log(this.prependState('onDuplicate'))
    }
    this.state.onDuplicate()
}

seatsio.ChartDesigner.prototype.onCut = function () {
    if (this.features.isDisabled(seatsio.Features.Type.CONTEXT_ACTIONS)) {
        return
    }
    if (this.debug) {
        // eslint-disable-next-line no-console
        console.log(this.prependState('onCut'))
    }
    this.state.onCut()
}

seatsio.ChartDesigner.prototype.onCopy = function () {
    if (this.features.isDisabled(seatsio.Features.Type.CONTEXT_ACTIONS)) {
        return
    }
    if (this.debug) {
        // eslint-disable-next-line no-console
        console.log(this.prependState('onCopy'))
    }
    this.state.onCopy()
}

seatsio.ChartDesigner.prototype.onPaste = function () {
    if (this.features.isDisabled(seatsio.Features.Type.CONTEXT_ACTIONS)) {
        return
    }
    if (this.debug) {
        // eslint-disable-next-line no-console
        console.log(this.prependState('onPaste'))
    }
    if (!this.clipboard.isEmpty()) {
        this.clipboard.paste()
    }
}

seatsio.ChartDesigner.prototype.onDelete = function () {
    if (this.features.isDisabled(seatsio.Features.Type.CONTEXT_ACTIONS)) {
        return
    }
    if (this.debug) {
        // eslint-disable-next-line no-console
        console.log(this.prependState('onDelete'))
    }
    this.state.onDelete()
}

seatsio.ChartDesigner.prototype.serialize = function () {
    return JSON.stringify(this.toJson())
}

seatsio.ChartDesigner.prototype.setSectionScaleFactor = function (factor) {
    if (this.sectionScaleFactor !== factor) {
        this.sectionScaleFactor = factor
        this.sectionSubChart.sectionScaleChanged(this.sectionScaleFactor)
        this.activeSubChart().refreshOutOfBounds(true)
        this.updateObjectsOutOfBounds()
        this.renderUI()
    }
}

seatsio.ChartDesigner.prototype.showSectionContentsEnabled = function () {
    return this.sectionScaleFactor === 100
}

seatsio.ChartDesigner.prototype.toJson = function () {
    var json = {}
    json.name = this.documentTitle
    json.tablesLabelCounter = seatsio.Tables.labelCounter
    json.uuidCounter = seatsio.Object.uuidCounter
    json.categories = this.categories.toJson()
    json.zones = this.zones.toJson()
    json.rowSpacing = this.rowSpacing
    json.rowChairSpacing = this.rowChairSpacing
    json.colorScheme = this.colorScheme
    json.version = this.version
    json.venueType = this.venueType
    json.sectionScaleFactor = this.sectionScaleFactor
    json.referenceChartVisible = this.referenceChartVisible
    if (this.subChartFloors.hasMultipleFloors()) {
        json.subChartFloors = this.subChartFloors.toJson()
        json.multiFloorView = this.multiFloorView
    } else {
        json.subChart = this.masterSubChart.toJson()
    }
    json.scannedOrCalibrated = this.scannedOrCalibrated
    return json
}

seatsio.ChartDesigner.prototype.fromJson = function (plan) {
    this.loadingFromJson = true
    this.initCategories(plan.categories)
    this.sectionScaleFactor = plan.sectionScaleFactor ? plan.sectionScaleFactor : 100
    this.showLegacySectionScaling = this.sectionScaleFactor !== 100
    let currentFloorIndex = this.subChartFloors.getCurrentFloorIndex()
    this.subChartFloors = plan.subChartFloors
        ? seatsio.SubChartFloors.fromJson(plan.subChartFloors, this)
        : new seatsio.SubChartFloors(this, [seatsio.MasterSubChart.fromJson(plan.subChart, this)])
    this.subChartFloors.setFloor(currentFloorIndex)
    this.subChartFloors.init()
    this.masterSubChart = this.subChartFloors.getCurrentMasterSubChart()
    this.zones.initFromJson(plan.zones)
    this.venueType = plan.venueType
    seatsio.ChartDesigner.showSectionContents = this.shouldShowSectionContents()
    this.showPrefixes = this.shouldShowPrefixes()
    seatsio.Tables.labelCounter = plan.tablesLabelCounter
    seatsio.Object.uuidCounter = plan.uuidCounter
    seatsio.ChartDesigner.snapToGridEnabled = this.storage.getItem('snapToGridEnabled')
    this.rowLabelsShown = this.storage.getItem('rowLabelsShown', false)
    this.labelsShown = this.storage.getItem('labelsShown', false)
    this.viewFromSeatsShown = this.storage.getItem('viewFromSeatsShown', false)
    this.rowSpacing = plan.rowSpacing === undefined ? seatsio.Row.DEFAULT_SPACING : plan.rowSpacing
    this.rowChairSpacing = plan.rowChairSpacing || seatsio.Row.DEFAULT_CHAIR_SPACING
    this.colorScheme = plan.colorScheme || 'light'
    this.documentTitle = plan.name
    this.multiFloorView = plan.multiFloorView || 'stage'
    this.shouldShowLegacySocialDistancingCheckbox = this.masterSubChart.allSeats().some(seat => seat.disabledBySocialDistancingRules)
    this.referenceChartVisible = this.getPlanReferenceChartVisible(plan)
    this.loadingFromJson = false
    this.scannedOrCalibrated = plan.scannedOrCalibrated === undefined ? true : plan.scannedOrCalibrated
    this.renderUI()
}

seatsio.ChartDesigner.prototype.getVenueSettings = function () {
    return seatsio.determineVenueType(this.venueType)
}

seatsio.ChartDesigner.prototype.initCategories = function (categoriesJson) {
    this.categories.setCategories(categoriesJson.maxCategoryKey, categoriesJson.list.map(function (categoryJson) {
        return new seatsio.Category(categoryJson.label, categoryJson.color, categoryJson.accessible, categoryJson.key)
    }))
}

seatsio.ChartDesigner.prototype.canvas = function () {
    return $(this.svg.node)
}

seatsio.ChartDesigner.prototype.activeSubChart = function () {
    if (this.sectionSubChart) {
        return this.sectionSubChart
    }
    return this.masterSubChart
}

seatsio.ChartDesigner.prototype.setState = function (newState) {
    if (this.debug) {
        // eslint-disable-next-line no-console
        console.log('setState from ' + this.state + ' to ' + newState)
    }
    if (this.state) {
        this.state.exit(newState)
    }
    let stateChange = !this.state || this.state.name !== newState.name
    this.state = newState
    this.state.init()
    this.setCursorToDefault()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.exitState = function () {
    if (this.state) {
        this.state.exit()
        this.state = null
    }
}

seatsio.ChartDesigner.prototype.getState = function () {
    return this.state
}

seatsio.ChartDesigner.prototype.toTextMode = function () {
    this.setState(new seatsio.TextModeState(this))
}

seatsio.ChartDesigner.prototype.drawHelperLines = function (point, drawingStarted) {
    this.helperLines.draw(point, drawingStarted)
}

seatsio.ChartDesigner.prototype.undrawHelperLines = function () {
    this.helperLines.undraw()
}

seatsio.ChartDesigner.prototype.onFlipHorizontal = function () {
    this.state.onFlip(true)
}

seatsio.ChartDesigner.prototype.onFlipVertical = function () {
    this.state.onFlip(false)
}

seatsio.ChartDesigner.prototype.onAlign = function () {
    this.state.onAlign()
}

seatsio.ChartDesigner.prototype.onNormalizeRows = function () {
    this.state.onNormalizeRows()
}

seatsio.ChartDesigner.prototype.onStraighten = function () {
    this.state.onStraighten()
}

seatsio.ChartDesigner.prototype.onEvenlySpace = function () {
    this.state.onEvenlySpace()
}

seatsio.ChartDesigner.prototype.drawLineThroughRay = function (ray) {
    return this.drawLine(ray.origin.x, ray.origin.y, ray.end.x, ray.end.y)
}

seatsio.ChartDesigner.prototype.doCurve = function (amount) {
    this.state.doCurve(amount)
}

seatsio.ChartDesigner.prototype.reselect = function () {
    this.state.reselect()
}

seatsio.ChartDesigner.prototype.setRowSpacing = function (amount) {
    this.rowSpacing = amount
    this.state.onDrawingToolInspectorValuesChange()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.setRowChairSpacing = function (amount) {
    this.rowChairSpacing = amount
    this.state.onDrawingToolInspectorValuesChange()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.setRowBlockStyle = function (style) {
    this.setToolProperty('RowDrawing.rowBlockStyle', style)
    this.state.onDrawingToolInspectorValuesChange()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.setVerticalRowLabelDirection = function (direction) {
    this.selectedObjects().setVerticalRowLabelDirection(direction)
    this.renderUI()
}

seatsio.ChartDesigner.prototype.showLabels = function () {
    this.labelsShown = true
    this.masterSubChart.showLabels()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.hideLabels = function () {
    this.labelsShown = false
    this.masterSubChart.hideLabels()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.showRowLabels = function () {
    this.rowLabelsShown = true
    this.masterSubChart.showRowLabels()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.hideRowLabels = function () {
    this.rowLabelsShown = false
    this.masterSubChart.hideRowLabels()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.refreshSectionSubChart = function () {
    if (this.atMasterSubChart()) {
        return null
    }
    var sectionUuid = this.sectionSubChart.section.uuid
    var section = this.masterSubChart.sections.findByUuid(sectionUuid)
    if (!section) {
        return null
    }
    return section.sectionSubChart
}

seatsio.ChartDesigner.prototype.loadDrawing = function (drawing) {
    this.getState().exit()
    this.activeSubChart().undraw()
    this.fromJson(drawing)
    this.sectionSubChart = this.refreshSectionSubChart()
    this.activeSubChart().draw()
    this.getState().reenter()
}

seatsio.ChartDesigner.prototype.onUndoPressed = function (e) {
    e.preventDefault()
    this.undo()
}

seatsio.ChartDesigner.prototype.undo = function () {
    if (this.history.canGoBack()) {
        this.getState().exit(new seatsio.DoNothingState())
        this.activeSubChart().undraw()
        var newState = this.history.goBack()
        this.fromJson(JSON.parse(newState))
        this.sectionSubChart = this.refreshSectionSubChart()
        this.updateStats()
        this.activeSubChart().refreshOutOfBounds()
        this.activeSubChart().draw()
        this.setDefaultState()
    }
}

seatsio.ChartDesigner.prototype.redo = function () {
    if (this.history.canGoForward()) {
        this.getState().exit(new seatsio.DoNothingState())
        this.activeSubChart().undraw()
        var newState = this.history.goForward()
        this.fromJson(JSON.parse(newState))
        this.sectionSubChart = this.refreshSectionSubChart()
        this.updateStats()
        this.activeSubChart().refreshOutOfBounds()
        this.activeSubChart().draw()
        this.setDefaultState()
    }
}

seatsio.ChartDesigner.prototype.toggleSnapToGrid = function () {
    seatsio.ChartDesigner.snapToGridEnabled = !seatsio.ChartDesigner.snapToGridEnabled
    this.renderUI()
    this.storage.setItem('snapToGridEnabled', seatsio.ChartDesigner.snapToGridEnabled)
}

seatsio.ChartDesigner.prototype.toggleShowSectionContents = function () {
    seatsio.ChartDesigner.showSectionContents = !seatsio.ChartDesigner.showSectionContents
    this.activeSubChart().sections.sections.forEach(section => section.redrawContents())
    this.renderUI()
    this.storage.setItem('showSectionContents', seatsio.ChartDesigner.showSectionContents)
}

seatsio.ChartDesigner.prototype.setReferenceChartVisible = function (state) {
    if (this.referenceChartVisible === state) {
        return
    }
    this.referenceChartVisible = state
    this.renderUI()
    this.activeSubChart().getReferenceChart().redraw()
}

seatsio.ChartDesigner.prototype.setReferenceChartShowAbove = function (state) {
    if (this.showReferenceChartAbove === state) {
        return
    }
    this.showReferenceChartAbove = state
    this.renderUI()
    if (this.showReferenceChartAbove && this.labelsShown) {
        this.hideLabels()
        this.onRestoreReferenceChartShowAbove = () => this.showLabels()
    }
    this.activeSubChart().getReferenceChart().redraw()
    if (!this.showReferenceChartAbove && this.onRestoreReferenceChartShowAbove) {
        this.onRestoreReferenceChartShowAbove()
        this.onRestoreReferenceChartShowAbove = undefined
    }
}

seatsio.ChartDesigner.prototype.toggleShowLabels = function () {
    if (this.labelsShown) {
        this.hideLabels()
    } else {
        this.showLabels()
    }
    this.storage.setItem('labelsShown', this.labelsShown)
}

seatsio.ChartDesigner.prototype.toggleShowRowLabels = function () {
    if (this.rowLabelsShown) {
        this.hideRowLabels()
    } else {
        this.showRowLabels()
    }
    this.storage.setItem('rowLabelsShown', this.rowLabelsShown)
}

seatsio.ChartDesigner.prototype.toggleColorScheme = function () {
    this.colorScheme = this.colorScheme !== 'dark' ? 'dark' : 'light'
    this.refreshBackgroundColor()
    this.activeSubChart().redraw()
    this.getState().reenter()
    this.renderUI()
    this.subChartFloors.redrawAbstractFloors()
}

seatsio.ChartDesigner.prototype.onActiveStateChanged = function (history) {
    this.uiStateUpdate({
        canUndo: history.canGoBack(),
        canRedo: history.canGoForward()
    })
}

seatsio.ChartDesigner.prototype.showViewFromSeats = function () {
    this.viewFromSeatsShown = true
    this.activeSubChart().showVFS()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.hideViewFromSeats = function () {
    this.viewFromSeatsShown = false
    this.activeSubChart().hideVFS()
    this.renderUI()
}

seatsio.ChartDesigner.prototype.toggleViewFromSeats = function () {
    if (this.viewFromSeatsShown) {
        this.hideViewFromSeats()
    } else {
        this.showViewFromSeats()
    }
    this.storage.setItem('viewFromSeatsShown', this.viewFromSeatsShown)
}

seatsio.ChartDesigner.prototype.requestStatsUpdate = function () {
    if (!this.requestStatsUpdateTimeout) {
        this.requestStatsUpdateTimeout = setTimeout(() => {
            delete (this.requestStatsUpdateTimeout)
            this.updateStats()
        }, 150 + (this.stats().totalPeopleCapacity ? Math.round(this.stats().totalPeopleCapacity / 75) : 0))
    }
}

seatsio.ChartDesigner.prototype.currentValidationScope = function () {
    if (this.sectionSubChart) {
        return [this.sectionSubChart]
    }
    return this.subChartFloors.subCharts
}

seatsio.ChartDesigner.prototype.isVenueWithZones = function () {
    return this.getVenueSettings().supportsZones
}

seatsio.ChartDesigner.prototype.getFocalPoint = function () {
    if (this.isVenueWithZones()) {
        return this.zones.getFocalPoint()
    }

    return this.activeSubChart().focalPoint
}

seatsio.ChartDesigner.prototype.availableStats = function (subCharts = this.currentValidationScope()) {
    return subCharts.length === 0 || subCharts[0].isMasterSubChart() || Object.keys(this.subChartStats).length === 0 ? this.globalStats : this.subChartStats
}

seatsio.ChartDesigner.prototype.stats = function (subCharts = this.currentValidationScope()) {
    return subCharts.length === 0 || subCharts[0].isMasterSubChart() ? this.globalStats : this.subChartStats
}

seatsio.ChartDesigner.prototype.updateStats = function (subCharts = this.currentValidationScope()) {
    const statsGenerator = new seatsio.ChartStatsGenerator(this.subChartFloors, subCharts, this.categories, this)
    const statsCollection = this.stats(subCharts)
    statsCollection.totalPeopleCapacity = statsGenerator.getTotalPeopleCapacity()
    statsCollection.totalBooths = statsGenerator.getTotalBooths()
    statsCollection.maxCapacityExceeded = statsCollection.totalPeopleCapacity + statsCollection.totalBooths > seatsio.ChartDesigner.MAX_CAPACITY
    statsCollection.unlabeledObjects = statsGenerator.getUnlabeled()
    statsCollection.capacityByObjectType = statsGenerator.getCapacityByObjectType()
    statsCollection.totalUnlabeledObjects = statsCollection.unlabeledObjects.count
    statsCollection.fileSizeByImage = statsGenerator.getFileSizeByImageWithBackground()
    statsCollection.imagesTotalSize = statsGenerator.getImagesTotalSize()
    statsCollection.missingFocalPoint = statsGenerator.isMissingFocalPoint()
    statsCollection.zonesMissingFocalPoint = statsGenerator.getZonesMissingFocalPoint()
    statsCollection.totalZonesMissingFocalPoint = statsGenerator.getTotalZonesMissingFocalPoint()
    statsCollection.hasUnusedFloors = statsGenerator.hasUnusedFloors()
    statsCollection.hasNoObjects = statsGenerator.hasNoObjects()
    statsCollection.emptySections = statsGenerator.getEmptySections()
    this.updateGlobalOnlyStats()
    this.updateDuplicateObjectsStats(statsGenerator, subCharts)
    this.updateCategoriesStats(statsGenerator, subCharts)
    this.updateObjectsOutOfBounds(statsGenerator, subCharts)
    this.updateEmptySectionsStats(statsGenerator, subCharts)
}

seatsio.ChartDesigner.prototype.updateGlobalOnlyStats = function () {
    const statsGenerator = new seatsio.ChartStatsGenerator(this.subChartFloors, [this.masterSubChart], this.categories, this)
    this.globalStats.objectTypesByCategory = statsGenerator.getObjectTypesByCategory()
    this.globalStats.totalCategoriesWithMultipleObjectTypes = Object.keys(this.globalStats.objectTypesByCategory).filter(key => this.globalStats.objectTypesByCategory[key].length > 1).length
}

seatsio.ChartDesigner.prototype.hasValidationWarningsOrErrors = function (subCharts = this.currentValidationScope()) {
    const states = this.getValidationStates(subCharts)
    const checkingStates = ['warning', 'error']
    return Object.keys(states).some(key => checkingStates.includes(states[key]))
}

seatsio.ChartDesigner.prototype.hasValidationErrors = function (subCharts = this.currentValidationScope()) {
    const states = this.getValidationStates(subCharts)
    return Object.keys(states).some(key => states[key] === 'error')
}

seatsio.ChartDesigner.prototype.hasMajorValidationErrors = function (subCharts = this.currentValidationScope()) {
    const states = this.getValidationStates(subCharts)
    return Object.keys(states)
        .filter(key => key !== 'hasNoObjects')
        .some(key => states[key] === 'error')
}

seatsio.ChartDesigner.prototype.getValidationStates = function (subCharts = this.currentValidationScope()) {
    return {"hasNoObjects":"","duplicates":"","uncategorized":"","unlabeled":"","missingFocalPoint":"","zonesMissingFocalPoint":"","hasUnusedFloors":"","hasMultipleFloors":false,"maxCapacityExceeded":""};
    const stats = this.stats(subCharts)
    // const chartValidation = this.v2Client.getWorkspaceSettings().chartValidation
    const chartValidation = {}
    const validationLevels = {
        OFF: 'notice',
        WARNING: 'warning',
        ERROR: 'error'
    }
    return {
        hasNoObjects: stats.hasNoObjects ? validationLevels[chartValidation.VALIDATE_NO_OBJECTS] : '',
        duplicates: stats.totalDuplicateObjects > 0 ? validationLevels[chartValidation.VALIDATE_DUPLICATE_LABELS] : '',
        uncategorized: stats.totalUncategorized > 0 ? validationLevels[chartValidation.VALIDATE_OBJECTS_WITHOUT_CATEGORIES] : '',
        unlabeled: stats.totalUnlabeledObjects > 0 ? validationLevels[chartValidation.VALIDATE_UNLABELED_OBJECTS] : '',
        missingFocalPoint: stats.missingFocalPoint ? validationLevels[chartValidation.VALIDATE_FOCAL_POINT] : '',
        zonesMissingFocalPoint: stats.totalZonesMissingFocalPoint > 0 ? validationLevels[chartValidation.VALIDATE_FOCAL_POINT] : '',
        hasUnusedFloors: stats.hasUnusedFloors ? validationLevels[chartValidation.VALIDATE_EMPTY_FLOOR] : '',
        typesPerCategory: stats.totalCategoriesWithMultipleObjectTypes > 0 ? validationLevels[chartValidation.VALIDATE_OBJECT_TYPES_PER_CATEGORY] : '',
        hasMultipleFloors: this.subChartFloors.hasMultipleFloors(),
        maxCapacityExceeded: stats.maxCapacityExceeded ? validationLevels.ERROR : ''
    }
}

seatsio.ChartDesigner.prototype.createStatsGeneratorWithActiveSubChart = function () {
    return new seatsio.ChartStatsGenerator(this.subChartFloors, [this.activeSubChart()], this.categories, this)
}

seatsio.ChartDesigner.prototype.updateDuplicateObjectsStats = function (statsGenerator, subCharts = this.currentValidationScope()) {
    if (!statsGenerator) {
        statsGenerator = this.createStatsGeneratorWithActiveSubChart()
    }
    let statsCollection = this.stats(subCharts)
    let duplicateObjects = statsGenerator.getDuplicateObjects()
    statsCollection.duplicateObjects = this.processDuplicateObjects(duplicateObjects)
    statsCollection.totalDuplicateObjects = _.keys(duplicateObjects).length
    this.masterSubChart.duplicateObjectsDetected(duplicateObjects)
}

seatsio.ChartDesigner.prototype.updateEmptySectionsStats = function (statsGenerator = null, subCharts = this.currentValidationScope()) {
    if (!statsGenerator) {
        statsGenerator = this.createStatsGeneratorWithActiveSubChart()
    }
    const statsCollection = this.stats(subCharts)
    statsCollection.emptySections = statsGenerator.getEmptySections()
    this.requestRenderUI()
}

seatsio.ChartDesigner.prototype.updateCategoriesStats = function (statsGenerator, subCharts = this.currentValidationScope()) {
    if (!statsGenerator) {
        statsGenerator = this.createStatsGeneratorWithActiveSubChart()
    }
    let statsCollection = this.stats(subCharts)
    statsCollection.uncategorizedObjects = statsGenerator.getUncategorized()
    statsCollection.totalUncategorized = statsCollection.uncategorizedObjects.count
    statsCollection.capacityByCategory = statsGenerator.getCapacityByCategory()
    statsCollection.boothsByCategory = statsGenerator.getBoothsByCategory()
    this.requestRenderUI()
}

seatsio.ChartDesigner.prototype.updateObjectsOutOfBounds = function (statsGenerator = null, subCharts = this.currentValidationScope()) {
    if (!statsGenerator) {
        statsGenerator = this.createStatsGeneratorWithActiveSubChart()
    }
    let statsCollection = this.stats(subCharts)
    statsCollection.hasObjectsOutOfBounds = statsGenerator.hasObjectsOutOfBounds()
    if (statsCollection.hasObjectsOutOfBounds) {
        this.addOverlayMessage('objects-out-of-section-bounds', 'warning')
    } else {
        this.removeOverlayMessage('objects-out-of-section-bounds')
    }
    this.requestRenderUI()
}

seatsio.ChartDesigner.prototype.setSelectedSubobjectsCount = function (count) {
    this.selectedSubobjectsCount = count
    this.renderUI()
}

seatsio.ChartDesigner.prototype.clearSelectedCount = function () {
    this.setSelectedSubobjectsCount(0)
    this.setSelectedObjectsCount(0)
    this.setSelectedObjectsUuid([])
    this.selectedSubobjectsLongestCount = null
}

seatsio.ChartDesigner.prototype.setSelectedObjectsCount = function (count) {
    this.selectedObjectsCount = count
    this.renderUI()
}

seatsio.ChartDesigner.prototype.setSelectedSeatsCount = function (objects) {
    let objectsWithSeats = objects.filter(object => typeof object.getChairs === 'function')
    this.selectedObjectsCount = objects.length
    this.selectedSubobjectsCount = objectsWithSeats.flatMap(object => object.getChairs()).length
    this.selectedSubobjectsLongestCount = objectsWithSeats.reduce((r, object) => Math.max(r, object.getChairs().length), 0)
    this.selectedObjectsUuid = objectsWithSeats.map(object => object.uuid)
    this.renderUI()
}

seatsio.ChartDesigner.prototype.selectedObjects = function () {
    return this.state.selectedObjectsObject
}

seatsio.ChartDesigner.prototype.setSelectedObjectsUuid = function (uuid) {
    this.selectedObjectsUuid = uuid
    this.renderUI()
}

seatsio.ChartDesigner.defaultName = function () {
    return d('untitled-chart')
}

seatsio.ChartDesigner.prototype.canCreateNewFloor = function () {
    return this.features.isEnabled(seatsio.Features.Type.MULTIPLE_FLOORS) &&
        this.subChartFloors.length() < seatsio.SubChartFloors.MAX_FLOORS
}

seatsio.ChartDesigner.prototype.getFloorDetails = function () {
    return this.subChartFloors.getFloorDetails()
}

seatsio.ChartDesigner.prototype.setDocumentTitle = function (title) {
    this.documentTitle = title
    this.renderUI()
}

seatsio.ChartDesigner.prototype.setMultiFloorView = function (view) {
    this.multiFloorView = view
    this.renderUI()
}

seatsio.ChartDesigner.prototype.refreshToolProperties = function () {
    this.setToolProperty('Icon.size', seatsio.Icon.getNewIconSize(this.zoomer))
    this.setToolProperty('Line.strokeWidth', seatsio.ShapedObjects.Line.getNewLineWidth(this.zoomer))
}

seatsio.ChartDesigner.prototype.setToolProperty = function (property, value) {
    this.toolProperties[property] = value
}

seatsio.ChartDesigner.prototype.getToolProperty = function (property) {
    return this.toolProperties[property]
}

seatsio.ChartDesigner.prototype.requestRenderUI = function () {
    if (this.requestedRenderUI) return
    this.requestedRenderUI = true
    requestAnimationFrame(() => {
        this.requestedRenderUI = false
        this.renderUI()
    })
}

seatsio.ChartDesigner.prototype.renderUI = function () {
    if (this.changingView) {
        return
    }
    if (this.renderedUIonThisFrame) {
        this.requestRenderUI()
        return
    }

    if (!this.root) {
        this.root = ReactDOM.createRoot(document.getElementById('designerApp'))
    }

    this.root.render(React.createElement(DesignerApp, this.getUIState()))
    this.renderedUIonThisFrame = true
    requestAnimationFrame(() => {
        this.renderedUIonThisFrame = false
    })
}

seatsio.ChartDesigner.prototype.addOverlayMessage = function (key, params, type = 'info') {
    this.overlayMessages[key] = { type, params }
}

seatsio.ChartDesigner.prototype.removeOverlayMessage = function (key) {
    delete this.overlayMessages[key]
}

seatsio.ChartDesigner.prototype.flashOverlayMessage = function (key, type = 'info', params = undefined, timeout = 5000) {
    let me = this
    me.addOverlayMessage(key, params, type)
    me.renderUI()
    setTimeout(function () {
        me.removeOverlayMessage(key)
        me.renderUI()
    }, timeout)
}

seatsio.ChartDesigner.prototype.uiStateUpdate = function (state) {
    let changes = false
    Object.keys(state).forEach(key => {
        let value = state[key]
        if (this.designerAppState[key] !== value) {
            this.designerAppState[key] = value
            changes = true
        }
    })
    if (changes) {
        this.renderUI()
    }
}

seatsio.ChartDesigner.prototype.uiStateToggle = function (key, value) {
    this.designerAppState[key] = this.designerAppState[key] === value ? null : value
    this.renderUI()
    return this.designerAppState[key]
}

seatsio.ChartDesigner.prototype.busyIndicatorOn = function (key) {
    if (!this.busyIndicators.includes(key)) {
        this.busyIndicators.push(key)
        this.renderUI()
    }
}

seatsio.ChartDesigner.prototype.busyIndicatorOff = function (key) {
    if (this.busyIndicators.includes(key)) {
        this.busyIndicators.remove(key)
        this.renderUI()
    }
}

seatsio.ChartDesigner.prototype.processDuplicateObjects = function (duplicateObjects) {
    return Object.keys(duplicateObjects).map(fullLabel => {
        let objects = duplicateObjects[fullLabel]
        let object = objects[0]

        return {
            total: objects.length,
            fullLabel,
            floor: this.subChartFloors.hasMultipleFloors() ? object.floorName() : undefined,
            sectionLabel: object.getSectionLabel(),
            parentUuid: _.uniq(objects.map(object => object.subChart.section && object.subChart.section.uuid)),
            parentLabel: object.parent && object.parent.getLabel(),
            parentType: object.parent && object.parent.type,
            objectLabel: object.getLabel()
        }
    })
}

seatsio.ChartDesigner.prototype.getContextActions = function () {
    if (this.features.isDisabled(seatsio.Features.Type.CONTEXT_ACTIONS)) {
        return []
    }
    let actions = this.selectedObjects() ? this.selectedObjects().getContextActions() : []
    if (!this.clipboard.isEmpty()) {
        actions.push('paste')
    }
    return actions
}

seatsio.ChartDesigner.prototype.getUIState = function () {
    return {
        abTest: Object.assign({}, this.abTest),
        uiState: Object.assign({}, this.designerAppState),
        busyIndicators: this.busyIndicators.slice(),
        overlayMessages: Object.assign({}, this.overlayMessages),
        designer: {
            chartHasEvents: this.chartHasEvents(),
            shouldShowLegacySocialDistancingCheckbox: this.shouldShowLegacySocialDistancingCheckbox,
            ignoredLabelEditingWarnings: Array.from(this.ignoredLabelEditingWarnings),
            ignoreLabelDisableWarning: Array.from(this.ignoredLabelDisableWarnings),
            loaded: this.chartLoaded,
            state: this.state.name,
            tool: this.state.toolName,
            toolHint: this.state.toolHint,
            disabledFeatures: this.features.getDisabled(),
            snapToGrid: seatsio.ChartDesigner.snapToGridEnabled,
            showSectionContents: seatsio.ChartDesigner.showSectionContents,
            showLabels: this.labelsShown,
            showRowLabels: this.rowLabelsShown,
            showAllTools: true,
            viewFromSeatsShown: this.viewFromSeatsShown,
            atMasterSubChart: this.atMasterSubChart(),
            sectionName: this.atMasterSubChart() ? null : this.sectionSubChart.section.label,
            sectionUuid: this.atMasterSubChart() ? null : this.sectionSubChart.section.uuid,
            minZoomLevel: seatsio.Zoomer.minZoomLevel,
            maxZoomLevel: seatsio.Zoomer.maxZoomLevel,
            zoomLevel: this.zoomer.zoomLevel,
            altKey: this.altWasPressed,
            ctrlKey: this.ctrlWasPressed,
            shiftKey: this.shiftWasPressed,
            spacebarIsPressed: this.spacebarIsPressed,
            enableCanvasGrabber: this.enableCanvasGrabber,
            rightMouseButton: this.rightMouseButtonPressed,
            lastGroupTool: Object.assign({}, this.lastGroupTool),
            toolProperties: Object.assign({}, this.toolProperties),
            currentFloor: this.subChartFloors.getCurrentFloorIndex(),
            canCreateNewFloor: this.canCreateNewFloor(),
            canvasColorScheme: this.canvasColorScheme,
            showReferenceChartAbove: this.showReferenceChartAbove,
            currentZoneKey: this.zones.currentZoneKey,
            apiUrl: this.apiUrl,
            // secretKey: this.v2Client.user ? this.v2Client.user.secretKey : undefined,
            enable3d: this.enable3d
        },
        document: {
            status: this.status,
            title: this.documentTitle,
            readOnly: this.isReadOnly(),
            categories: this.categories.all().map(category => Object.assign({}, category)),
            zones: this.zones.all().map(zone => ({ ...zone, canBeDeleted: this.zones.canZoneBeDeleted(zone.key) })),
            subChartStats: this.subChartStats ? Object.assign({}, this.subChartStats) : {},
            globalStats: this.globalStats ? Object.assign({}, this.globalStats) : {},
            rowSpacing: this.rowSpacing,
            referenceChartScale: this.masterSubChart.referenceChart.backgroundImageScale,
            floors: this.subChartFloors.length(),
            chartKey: this.chartKey,
            // workspaceKey: this.getWorkspaceKey(),
            chartJsonForPreview: this.toJson(),
            colorScheme: this.getCanvasColorScheme()
        },
        selection: {
            uuid: this.selectedObjectsUuid,
            count: this.selectedObjectsCount,
            subCount: this.selectedSubobjectsCount,
            longestSubCount: this.selectedSubobjectsLongestCount,
            sheets: this.getInspectorSheets(),
            contextActions: this.getContextActions(),
            data: {},
            info: {
                hasDuplicateObjects: this.selectedObjects() && this.selectedObjects().selectedObjectHasDuplicateObjects(),
                canBeCurved: this.selectedObjects() && this.selectedObjects().canBeCurved(),
                canChairSpacingBeEdited: this.selectedObjects() && this.selectedObjects().canChairSpacingBeEdited(),
                canBeSmoothened: this.selectedObjects() && this.selectedObjects().canBeSmoothened(),
                canSeatCountBeEdited: this.selectedObjects() && this.selectedObjects().canSeatCountBeEdited()
            },
            rowSpacing: this.selectedObjects() && this.selectedObjects().getRowSpacing()
        },
        onRenderModeToggle: this.setRenderMode
    }
}

seatsio.ChartDesigner.prototype.getWorkspaceKey = function () {
    return this.v2Client.getWorkspaceKey()
}

seatsio.ChartDesigner.prototype.getSelectedObjects = function () {
    if (this.selectedObjects() && this.selectedObjects().hasSelectedObjects()) {
        return this.selectedObjects().arrayOfObjects
    } else if (this.state.hasSelectedObjects()) {
        return this.state.getSelectedObjects()
    } else {
        return []
    }
}

seatsio.ChartDesigner.prototype.getMultiFloorView = function () {
    return this.multiFloorView || 'stage'
}

seatsio.ChartDesigner.prototype.getInspectorSheets = function () {
    let selectedObjects = this.getSelectedObjects()
    if (selectedObjects.length > 0) {
        let inspectorSheetsFromArray = this.getInspectorSheetsFromArray(selectedObjects)
        return _.pickBy(
            inspectorSheetsFromArray,
            (sheet, sheetName) => this.isObjectSheetEnabled(sheetName)
        )
    } else {
        return this.state.getInspectorSheets() || (
            this.atMasterSubChart() ? {
                'ChartInfo.name': this.documentTitle,
                'ChartInfo.isEmpty': this.activeSubChart().isEmpty() && !this.subChartFloors.hasUsedFloors(),
                'ChartInfo.totalPeopleCapacity': this.stats().totalPeopleCapacity,
                'ChartInfo.maxCapacityExceeded': this.stats().maxCapacityExceeded,
                'ChartInfo.totalBooths': this.stats().totalBooths,
                'ChartInfo.totalUnlabeledObjects': this.stats().totalUnlabeledObjects,
                'ChartInfo.totalDuplicateObjects': this.stats().totalDuplicateObjects,
                'ChartInfo.totalUncategorized': this.stats().totalUncategorized,
                'ChartInfo.totalCategoriesWithMultipleObjectTypes': this.stats().totalCategoriesWithMultipleObjectTypes,
                'ChartInfo.missingFocalPoint': this.stats().missingFocalPoint,
                'ChartInfo.totalZonesMissingFocalPoint': this.stats().totalZonesMissingFocalPoint,
                'ChartInfo.hasUnusedFloors': this.stats().hasUnusedFloors,
                'ChartInfo.hasNoObjects': this.stats().hasNoObjects,
                'ChartInfo.imagesTotalSize': this.stats().imagesTotalSize,
                'ChartInfo.totalCategories': this.categories.all().length,
                'ChartInfo.hasMultipleFloors': this.subChartFloors.hasMultipleFloors(),
                'ChartInfo.emptySections': this.stats().emptySections,
                'ReferenceChart.url': this.masterSubChart.referenceChart.url(),
                'ReferenceChart.scale': this.masterSubChart.referenceChart.backgroundImageScale,
                'ReferenceChart.visible': this.referenceChartVisible,
                'ReferenceChart.showAbove': this.showReferenceChartAbove,
                'ReferenceChart.fileType': this.masterSubChart.referenceChart.backgroundFileType,
                'ChartBackground.url': this.activeSubChart().backgroundImage.url(),
                'ChartBackground.scale': this.activeSubChart().backgroundImage.backgroundImageScale,
                'ChartBackground.visibleToTicketBuyers': this.activeSubChart().backgroundImage.showOnRenderedCharts,
                'ChartBackground.fileSize': this.activeSubChart().backgroundImage.fileSize(),
                'ChartBackground.fileType': this.activeSubChart().backgroundImage.backgroundFileType,
                'MultiFloor.view': this.getMultiFloorView()
            } : {
                'SectionInfo.name': this.activeSubChart().section.label,
                'SectionInfo.isEmpty': this.activeSubChart().isEmpty(),
                'SectionInfo.totalPeopleCapacity': this.subChartStats.totalPeopleCapacity,
                'SectionInfo.totalBooths': this.subChartStats.totalBooths,
                'SectionInfo.totalUnlabeledObjects': this.subChartStats.totalUnlabeledObjects,
                'SectionInfo.totalDuplicateObjects': this.subChartStats.totalDuplicateObjects,
                'SectionInfo.totalUncategorized': this.subChartStats.totalUncategorized,
                'SectionInfo.sectionScale': this.sectionScaleFactor,
                'SectionInfo.imagesTotalSize': this.subChartStats.imagesTotalSize,
                'SectionInfo.hasObjectsOutOfBounds': this.subChartStats.hasObjectsOutOfBounds,
                'ReferenceChart.url': this.masterSubChart.referenceChart.url(),
                'ReferenceChart.scale': this.masterSubChart.referenceChart.backgroundImageScale,
                'ReferenceChart.visible': this.referenceChartVisible,
                'ReferenceChart.showAbove': this.showReferenceChartAbove
            }
        )
    }
}

seatsio.ChartDesigner.prototype.isObjectSheetEnabled = function (sheetName) {
    if (sheetName.startsWith('ObjectLabeling.') || sheetName.startsWith('SeatLabeling.') || sheetName.startsWith('Label.')) {
        return this.features.isEnabled(seatsio.Features.Type.LABELING)
    }
    if (sheetName.startsWith('Category.') || sheetName.startsWith('SubChart.')) {
        return true
    }
    if (!sheetName.includes('.')) {
        return true
    }
    return this.features.isEnabled(seatsio.Features.Type.OBJECT_PROPERTIES)
}

seatsio.ChartDesigner.prototype.getInspectorSheetsFromArray = function (objectsArray) {
    let commonSheets
    let inspectorSheets = objectsArray.map(object => {
        return object.getInspectorSheets()
    })
    let sheets = inspectorSheets.forEach(objectInspectorSheets => {
        if (commonSheets) {
            commonSheets = Object.keys(commonSheets)
                .filter(commonSheet => Object.keys(objectInspectorSheets).includes(commonSheet))
                // eslint-disable-next-line no-sequences
                .reduce((res, key) => (res[key] = this.getInspectorSheetsValues(inspectorSheets, key), res), {})
        } else {
            commonSheets = objectInspectorSheets
        }
    })
    return commonSheets
}

seatsio.ChartDesigner.prototype.getInspectorSheetsValues = function (inspectorSheets, key) {
    if (seatsio.ChartDesigner.sumInspectorSheetValues.includes(key)) {
        return inspectorSheets.reduce((total, objectInspectorSheets) => total + (objectInspectorSheets[key] || 0), 0)
    } else {
        let values = _.uniq(inspectorSheets.flatMap(objectInspectorSheets => objectInspectorSheets[key])).filter(value => value !== undefined)
        return values.length > 1 ? values : values[0]
    }
}

seatsio.ChartDesigner.prototype.getPlanReferenceChartVisible = function (plan) {
    if (plan.referenceChartVisible === undefined) {
        return plan.subChart && plan.subChart.referenceChart && plan.subChart.referenceChart.visible !== undefined
            ? plan.subChart.referenceChart.visible
            : true
    } else {
        return plan.referenceChartVisible
    }
}

seatsio.ChartDesigner.prototype.shouldShowPrefixes = function () {
    return this.masterSubChart.allBookableParentObjects().some(o => o.objectLabeling && o.objectLabeling.prefix && o.objectLabeling.prefix.length > 0)
}

seatsio.ChartDesigner.prototype.getTranslatedRowDisplayTypeSuggestions = function () {
    return _.uniq(seatsio.Row.DISPLAY_OBJECT_TYPES.map(type => d(type))
        .concat([TextInput.SUGGESTIONS_SEPARATOR])
        .concat(this.masterSubChart.allRows().map(row => row.displayObjectType).filter(type => !seatsio.Row.DISPLAY_OBJECT_TYPES.includes(type)).sort())
    )
}

seatsio.ChartDesigner.prototype.getTranslatedSeatDisplayTypeSuggestions = function () {
    return _.uniq(seatsio.Chair.DISPLAY_OBJECT_TYPES.map(type => d(type))
        .concat([TextInput.SUGGESTIONS_SEPARATOR])
        .concat(this.masterSubChart.allObjectsWithSeats().flatMap(o => o.chairs).map(chair => chair.displayObjectType).filter(type => !seatsio.Chair.DISPLAY_OBJECT_TYPES.includes(type)).sort())
    )
}

seatsio.ChartDesigner.prototype.chartHasEvents = function () {
    return this.status !== 'NOT_USED'
}

seatsio.ChartDesigner.prototype.shouldShowLegacySocialDistancingCheckbox = function () {
    return this.shouldShowLegacySocialDistancingCheckbox
}

seatsio.ChartDesigner.prototype.ignoreLabelEditingWarning = function (objectType) {
    this.ignoredLabelEditingWarnings.add(objectType)
    this.renderUI()
}

seatsio.ChartDesigner.prototype.ignoreLabelDisableWarning = function (objectType) {
    this.ignoredLabelDisableWarnings.add(objectType)
    this.renderUI()
}

seatsio.ChartDesigner.prototype.useScanningResult = function (scanningResult, isSection) {
    this.activeSubChart().undraw()
    if (isSection) {
        this.useScanningResultForSection(scanningResult)
    } else {
        this.useScanningResultForChart(scanningResult)
    }
    this.activeSubChart().draw()
    this.centerCanvasAndFillScreen()
}

seatsio.ChartDesigner.prototype.useScanningResultForChart = function (scanningResult) {
    let drawing = this.chartScanningResultToDrawing(scanningResult)
    this.fromJson(drawing)
}

seatsio.ChartDesigner.prototype.useScanningResultForSection = function (scanningResult) {
    const drawing = this.sectionScanningResultToDrawing(scanningResult)

    const referenceChartScale = this.masterSubChart.referenceChart.backgroundImageScale / 100
    const scaleDiff = drawing.referenceChart.scaleFactor / referenceChartScale
    this.subChartFloors.scale(scaleDiff, seatsio.designer.scannedOrCalibrated)

    this.rowSpacing = drawing.rowSpacing

    const drawingJsonRows = this.scanningResultRowsToDrawing(drawing.rows)
    this.activeSubChart().rows = seatsio.SubChart.rowsFromJson(drawingJsonRows, this.activeSubChart())

    seatsio.designer.scannedOrCalibrated = true
}

seatsio.ChartDesigner.prototype.sectionsWithObjects = function () {
    return this.subChartFloors.allMasterSubCharts().some(subChart => subChart.hasSectionWithObjects())
}

seatsio.ChartDesigner.prototype.sectionScanningResultToDrawing = function (scanningResult) {
    if (this.sectionsWithObjects()) {
        const referenceChartScale = this.masterSubChart.referenceChart.backgroundImageScale / 100
        return scanningResult.toAlreadyScaledSectionJson(referenceChartScale, seatsio.Chair.width, seatsio.Row.DEFAULT_CHAIR_SPACING, seatsio.Row.DEFAULT_CHAIR_SPACING)
    }
    return scanningResult.toSectionJson(seatsio.Chair.width, seatsio.Row.DEFAULT_CHAIR_SPACING, seatsio.Row.DEFAULT_CHAIR_SPACING)
}

seatsio.ChartDesigner.prototype.chartScanningResultToDrawing = function (scanningResult) {
    let drawing = this.toJson()
    let drawingFromScan = scanningResult.toDrawingJson(seatsio.Chair.width, seatsio.Row.DEFAULT_CHAIR_SPACING, seatsio.Row.DEFAULT_CHAIR_SPACING)
    seatsio.Object.uuidCounter = 0

    const referenceChart = drawing.subChart.referenceChart
    drawing.subChart = seatsio.VenueTypeSwitcher.createMasterDataStructure()
    drawing.subChart.referenceChart = referenceChart

    drawing.subChart.rows = this.scanningResultRowsToDrawing(drawingFromScan.rows)
    drawing.subChart.width = drawingFromScan.width
    drawing.subChart.height = drawingFromScan.height

    drawing.subChart.referenceChart.origin = drawingFromScan.referenceChart.origin
    drawing.subChart.referenceChart.backgroundImageZoom = drawingFromScan.referenceChart.scaleFactor * 100

    drawing.rowSpacing = drawingFromScan.rowSpacing
    drawing.uuidCounter = seatsio.Object.uuidCounter
    drawing.tablesLabelCounter = 1
    drawing.referenceChartVisible = true

    return drawing
}

seatsio.ChartDesigner.prototype.scanningResultRowsToDrawing = function (scannedRows) {
    return scannedRows.map(row => {
        return {
            label: seatsio.LabelingTextInput.emptyLabel,
            chairSpacing: row.seatSpacing,
            uuid: seatsio.Object.uuid(),
            seats: row.seats.map(seat => {
                return {
                    label: seat.label ? seat.label : seatsio.LabelingTextInput.emptyLabel,
                    x: seat.center.x,
                    y: seat.center.y,
                    uuid: seatsio.Object.uuid()
                }
            }),
            // TODO: for simplicity, we consider curved rows segmented rows. It would be
            // even better (though more complicated code-wise) to treat them as actual
            // curved rows
            points: row.type === 'curved' || row.type === 'segmented' ? row.seats : null
        }
    })
}

seatsio.ChartDesigner.snapToAngle = 2
seatsio.ChartDesigner.snapToGridEnabled = true
seatsio.ChartDesigner.showSectionContents = false
seatsio.ChartDesigner.sumInspectorSheetValues = [
    'SubChart.totalPeopleCapacity',
    'SubChart.totalBooths'
]

seatsio.ChartDesigner.prototype.shouldShowSectionContents = function () {
    if (this.showLegacySectionScaling || this.features.isDisabled(seatsio.Features.Type.SECTIONS)) {
        return false
    }
    return this.storage.getItem('showSectionContents', this.masterSubChart.allBookableParentObjects().length < 800)
}

seatsio.ChartDesigner.SIZE = 20000
seatsio.ChartDesigner.MAX_CAPACITY = 200000

seatsio.Obfuscator = {}

seatsio.Obfuscator.deobfuscate = (input, key) => {
    const keyAsInt = seatsio.Obfuscator.keyToNumberBetween0And63(key)
    const obfuscated = new Uint8Array(input)
    for (let i = 0; i < obfuscated.length; ++i) {
        obfuscated[i] = obfuscated[i] - keyAsInt
    }
    return new TextDecoder('utf-8').decode(obfuscated)
}

seatsio.Obfuscator.keyToNumberBetween0And63 = (key) => {
    return seatsio.Obfuscator.hashCode(key) & 63
}

seatsio.Obfuscator.hashCode = (str) => {
    let hashcode = 0
    const mod = 10007
    const shift = 29
    for (let i = 0; i < str.length; i++) {
        hashcode = ((shift * hashcode) % mod + str.charCodeAt(i)) % mod
    }
    return hashcode
}

seatsio.V2Client = function (apiUrl, workspaceKey) {
    this.apiUrl = apiUrl
    this.workspaceKey = workspaceKey
    this.user = undefined
    this.workspaceSettings = undefined
}

seatsio.V2Client.prototype.init = function (chartDesigner) {
    var me = this
    return me.determineUser(chartDesigner)
        .then(user => me.user = user)
        .then(() => me.determineWorkspaceSettings(chartDesigner))
        .then(settings => me.workspaceSettings = settings)
}

seatsio.V2Client.prototype.determineUser = function (chartDesigner) {
    if (chartDesigner.anonymous()) {
        return $.when()
    }

    return this.authenticatedAjax(chartDesigner.secretKey || chartDesigner.designerKey, {
        url: '/accounts/me'
    })
}

seatsio.V2Client.prototype.determineWorkspaceSettings = function () {
    if (!this.user) {
        return $.when()
    }

    var me = this
    return this.authenticatedAjax(me.user.secretKey, {
        url: '/workspaces/' + me.getWorkspaceKey()
    }).then(function (workspace) {
        return workspace.settings
    })
}

seatsio.V2Client.prototype.retrievePublishedDrawingByWorkspaceKey = function (chartKey) {
    return $.ajax({
        url: this.apiUrl + '/system/public/' + this.getWorkspaceKey() + '/charts/' + chartKey
    })
}

seatsio.V2Client.prototype.saveChart = function (chartKey, chart) {
    return this.authenticatedAjax(this.user.secretKey, {
        type: 'POST',
        url: `/system/public/charts/${chartKey}`,
        data: chart,
        contentType: 'application/json',
        headers: {
            'Content-encoding': 'deflate'
        },
        processData: false,
        timeout: 30000
    })
}

seatsio.V2Client.prototype.getWorkspaceKey = function () {
    if (this.workspaceKey) {
        return this.workspaceKey
    }
    if (this.user) {
        return this.user.defaultWorkspace.key
    }
    return null
}

seatsio.V2Client.prototype.retrieveChart = function (chartKey) {
    return this.authenticatedAjax(this.user.secretKey, {
        url: '/charts/' + chartKey
    })
}

seatsio.V2Client.prototype.retrievePublishedDrawing = function (chartKey) {
    return this.fetchDrawingVersionAndDeobfuscate('published', chartKey)
}

seatsio.V2Client.prototype.retrieveDraftDrawing = function (chartKey) {
    return this.fetchDrawingVersionAndDeobfuscate('draft', chartKey)
}

seatsio.V2Client.prototype.fetchDrawingVersionAndDeobfuscate = function (version, chartKey) {
    let url = '/system/public/charts/' + chartKey + '/version/' + version
    return this
        .authenticatedFetch(this.user.secretKey, url)
        .then(async response => {
            let body = await response.arrayBuffer()
            return JSON.parse(seatsio.Obfuscator.deobfuscate(body, chartKey))
        })
}

seatsio.V2Client.prototype.publishDraft = function (chartKey) {
    return this.authenticatedAjax(this.user.secretKey, {
        method: 'POST',
        url: '/charts/' + chartKey + '/version/draft/actions/publish'
    })
}

seatsio.V2Client.prototype.discardDraft = function (chartKey) {
    return this.authenticatedAjax(this.user.secretKey, {
        method: 'POST',
        url: '/charts/' + chartKey + '/version/draft/actions/discard'
    })
}

seatsio.V2Client.prototype.uploadImage = function (formData, chartKey, onSuccess, onError, onAbort, resize = true) {
    function loadHandler (e) {
        const xhr = e.target
        if (xhr.status === 200) {
            onSuccess(JSON.parse(xhr.responseText))
        } else if (xhr.status === 400) {
            let error = JSON.parse(xhr.responseText)
            onError(error.errors[0].code)
        } else {
            onError(xhr.responseText)
        }
    }

    let xhr = new XMLHttpRequest()
    let url = this.apiUrl + '/charts/' + chartKey + '/images?resize=' + resize
    xhr.addEventListener('load', loadHandler, false)
    xhr.addEventListener('error', onError, false)
    xhr.addEventListener('abort', onAbort, false)
    xhr.open('POST', url)
    xhr.setRequestHeader('Authorization', this.encodeSecret(this.user.secretKey))
    xhr.send(formData)
}

seatsio.V2Client.prototype.uploadImageWithoutResizing = function (formData, chartKey, onSuccess, onError, onAbort) {
    this.uploadImage(formData, chartKey, onSuccess, onError, onAbort, false)
}

seatsio.V2Client.prototype.encodeSecret = function (secret) {
    return 'Basic ' + btoa(secret + ':')
}

seatsio.V2Client.prototype.authenticatedFetch = function (secret, relativeUrl) {
    let fullUrl = this.apiUrl + relativeUrl
    let headers = {
        'Authorization': this.encodeSecret(secret),
        'X-Client-Tool': 'Designer'
    }
    if (this.getWorkspaceKey()) {
        headers['X-Workspace-Key'] = this.getWorkspaceKey()
    }
    return fetch(fullUrl, {
        method: 'GET',
        headers: headers
    }).then(response => {
        if (response.ok) {
            return response
        } else {
            throw response
        }
    })
}

seatsio.V2Client.prototype.authenticatedAjax = function (secret, config) {
    var me = this
    config.beforeSend = function (xhr) {
        xhr.setRequestHeader('Authorization', me.encodeSecret(secret))
        if (me.getWorkspaceKey()) {
            xhr.setRequestHeader('X-Workspace-Key', me.getWorkspaceKey())
        }
        xhr.setRequestHeader('X-Client-Tool', 'Designer')
    }
    config.url = me.apiUrl + config.url
    return $.ajax(config)
}

seatsio.V2Client.prototype.getWorkspaceSettings = function () {
    if (this.workspaceSettings) {
        return this.workspaceSettings
    } else {
        return {
            chartValidation: {}
        }
    }
}

seatsio.DataCollectorClient = class {
    constructor (dataCollectorUrl) {
        this.dataCollectorUrl = dataCollectorUrl
    }

    logEvent (event) {
        return fetch(this.dataCollectorUrl + '/events', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(event)
        })
    }
}

