    discardDraft () {
        this.designer.statusChanger.discardDraft().then(
            () => window.location.reload(),
            () => alert(d('discard-draft-error'))
        )
    }

    publishDraft () {
        this.uiStateUpdate({ save: 'saving' })
        this.closeModalDialog()
        this.designer.statusChanger.publishDraft()
            .then(() => {
                seatsio.designer.setStatus('PUBLISHED')
                this.uiStateUpdate({ save: 'saved' })
                this.designer.busyIndicatorOff('publish')
                if (this.designer.onExitRequested) {
                    this.designer.onExitRequested()
                }
            }, () => {
                alert(d('publishDraftError'))
                this.uiStateUpdate({ save: 'rejected' })
            })
    }

