    selectObjectByUuid (uuid) {
        if (!uuid) {
            return this.selectObject(null)
        }
        let object = this.designer.activeSubChart().findByUuid(uuid)
        this.selectObject(object)
    }

    selectObjectOrSectionByUuid (uuid) {
        if (uuid) {
            let object = this.designer.activeSubChart().findByUuid(uuid)
            if (object) {
                this.designer.setState(new seatsio.ObjectsSelectedState(this.designer, [object]))
            } else {
                let section = this.designer.subChartFloors.allMasterSubCharts().reduce((match, subChart) => match || subChart.sections.findByUuid(uuid), null)
                this.designer.goToFloor(section.subChart.floorIndex())
                this.designer.setState(new seatsio.ObjectsSelectedState(this.designer, [section]))
            }
        }
        this.softShowLabels()
    }

