    _getTargetSubTool (targetMainTool, tools) {
        let [currentMainTool, currentSubTool] = this.designer.getState().toolName.split('-')
        let targetSubTool = this.designer.lastGroupTool[targetMainTool]

        if (currentMainTool === targetMainTool && tools.includes(currentSubTool)) {
            let targetIndex = tools.indexOf(targetSubTool) + (this.designer.shiftWasPressed ? -1 : 1)
            if (targetIndex >= tools.length) {
                targetIndex = 0
            } else if (targetIndex < 0) {
                targetIndex = tools.length - 1
            }
            targetSubTool = tools[targetIndex]
        }

        return targetSubTool
    }

