    /** * Tooltip ***/

    showTooltip (contents, e, showLeft = false) {
        this.uiStateUpdate({
            globalTooltipContents: contents,
            globalTooltipVisible: true
        })
        if (e) {
            let rect = e.target.getBoundingClientRect()
            if (showLeft) {
                this.uiStateUpdate({ globalTooltipPosition: { right: window.innerWidth - rect.left, top: rect.bottom } })
            } else {
                this.uiStateUpdate({ globalTooltipPosition: { left: rect.right, top: rect.bottom } })
            }
        }
    }

