seatsio.ObjectLabel = function (parent) {
    this.parent = parent
    this.subChart = this.parent.subChart
    this.designer = this.subChart.designer
    this.visible = true
}

seatsio.ObjectLabel.prototype.verticallyOriented = function () {
    return this.parent.verticallyOriented()
}

seatsio.ObjectLabel.prototype.iconAndLabelXSpacing = function (name) {
    return this.getFontSize() * 0.5
}

seatsio.ObjectLabel.prototype.iconAndLabelYSpacing = function (name) {
    return this.getFontSize() * 0.2
}

seatsio.ObjectLabel.prototype.applyRotation = function (position) {
    return position
        .rotateAround(this.parent.center(), this.parentRotationAngle())
        .rotateAround(this.parent.labelPosition(), this.labelRotationAngle())
}

seatsio.ObjectLabel.prototype.determineIconObjectPosition = function () {
    let position = this.parent.labelPosition()
    if (this.canDrawLabel()) {
        if (this.verticallyOriented()) {
            position = position.addToY(-(this.getFontSize() + this.iconAndLabelYSpacing()) / 2)
        } else {
            let labelBBox = seatsio.Bbox.fromView(this.labelElement.rbox(), this.designer)
            position = labelBBox.center().addToX(-labelBBox.width / 2 - (this.getIconFontSize() + this.iconAndLabelXSpacing()) / 2)
        }
    }
    return this.applyRotation(position)
}

seatsio.ObjectLabel.prototype.determineTextObjectPosition = function () {
    let position = this.parent.labelPosition()
    if (this.canDrawIcon()) {
        if (this.verticallyOriented()) {
            position = position.addToY((this.getIconFontSize() + this.iconAndLabelYSpacing()) / 2)
        } else {
            position = position.addToX((this.getIconFontSize() + this.iconAndLabelXSpacing()) / 2)
        }
    }
    return position
}

seatsio.ObjectLabel.prototype.getIconFontSize = function () {
    return this.parent.labelSize * this.parent.iconSizeMultiplier()
}

seatsio.ObjectLabel.prototype.getFontSize = function () {
    return this.parent.labelSize
}

seatsio.ObjectLabel.prototype.parentRotationAngle = function () {
    return this.parent.getShape().rotationAngle || 0
}

seatsio.ObjectLabel.prototype.labelRotationAngle = function () {
    return this.parent.labelRotationAngle || 0
}

seatsio.ObjectLabel.prototype.combinedRotationAngle = function () {
    return this.parentRotationAngle() + this.labelRotationAngle()
}

seatsio.ObjectLabel.prototype.isBackgroundDark = function () {
    return new seatsio.Color(this.parent.determineNonHighlightedColor()).brehaut().getLuminance() < 0.7
}

seatsio.ObjectLabel.prototype.determineTextColor = function () {
    return this.parent.determineLabelColor()
}

seatsio.ObjectLabel.prototype.canDrawLabel = function () {
    return this.parent.labelShown !== false && this.parent.getLabelText() && this.parent.getLabelText().length > 0
}

seatsio.ObjectLabel.prototype.canDrawIcon = function () {
    return this.parent.getLabelIcon() !== null
}

seatsio.ObjectLabel.prototype.displayLabel = function () {
    return this.canDrawLabel()
}

seatsio.ObjectLabel.prototype.displayIconLabel = function () {
    return this.canDrawIcon()
}

seatsio.ObjectLabel.prototype.redraw = function () {
    if (this.subChart.isActive()) {
        this.redrawLabel()
        this.redrawIconLabel()
        this.postLabelDraw()
        if (!this.visible) {
            this.hide()
        }
    }
    return this
}

seatsio.ObjectLabel.prototype.redrawLabel = function () {
    if (this.labelElement) {
        this.labelElement.remove()
    }
    if (!this.displayLabel()) {
        return
    }
    var position = this.determineTextObjectPosition()
    this.labelElement = this.designer.drawer.text(position.x, position.y, whitespaceToNonBreakingSpaces(this.parent.getLabelText()),
        {
            'font-size': this.getFontSize(),
            'font-family': seatsio.TextInput.defaultFontFamily,
            'font-weight': 'bold',
            'fill': this.determineTextColor()
        })
        .toLayer(this.getLayer(), this.designer, this.parent.zIndex)
        .applyZoom(this.designer)
    this.labelElement.node.setAttribute('pointer-events', 'none')
}

seatsio.ObjectLabel.prototype.applyElementAttributes = function () {
    if (this.labelElement) {
        this.labelElement.attr({
            'fill': this.determineTextColor()
        })
    }
    if (this.iconLabel) {
        this.iconLabel.attr({
            'fill': this.determineTextColor()
        })
    }
}

seatsio.ObjectLabel.prototype.postLabelDraw = function () {
    if (this.labelElement) {
        let position = this.applyRotation(this.determineTextObjectPosition())
        this.labelElement.attr({ x: position.x, y: position.y })
        this.labelElement.zoomAndRotateAround(this.combinedRotationAngle(), new seatsio.Point(position.x, position.y), this.designer)
    }
}

seatsio.ObjectLabel.prototype.redrawIconLabel = function () {
    if (this.iconLabel) {
        this.iconLabel.remove()
    }
    if (!this.displayIconLabel()) {
        return
    }
    var position = this.determineIconObjectPosition()
    this.iconLabel = this.designer.drawer.text(position.x, position.y, this.parent.getLabelIcon(),
        {
            'font-size': this.getIconFontSize(),
            'font-family': 'seatsdesigner',
            'fill': this.determineTextColor()
        })
        .toLayer(this.getLayer(), this.designer, this.parent.zIndex)
        .zoomAndRotateAround(this.combinedRotationAngle(), new seatsio.Point(position.x, position.y), this.designer)
    this.iconLabel.node.setAttribute('pointer-events', 'none')
}

seatsio.ObjectLabel.prototype.getLayer = function () {
    if (this.parent.getLayer) {
        return this.parent.getLayer()
    }
    return 'textsLayer'
}

seatsio.ObjectLabel.prototype.undraw = function () {
    if (this.labelElement) {
        this.labelElement.remove()
    }
    if (this.iconLabel) {
        this.iconLabel.remove()
    }
}

seatsio.ObjectLabel.prototype.show = function () {
    if (this.labelElement) {
        this.labelElement.show()
    }
    if (this.iconLabel) {
        this.iconLabel.show()
    }
    this.visible = true
}

seatsio.ObjectLabel.prototype.hide = function () {
    if (this.labelElement) {
        this.labelElement.hide()
    }
    if (this.iconLabel) {
        this.iconLabel.hide()
    }
    this.visible = false
}

seatsio.ObjectLabel.prototype.visibleElementsSet = function () {
    return [this.labelElement, this.iconLabel]
}

seatsio.ObjectLabel.MIN_LABEL_SIZE = 6
seatsio.ObjectLabel.MAX_LABEL_SIZE = 500

seatsio.ObjectLabelSupport = function () {}

seatsio.ObjectLabelSupport.prototype.init = function () {
    this.labelSize = seatsio.ObjectLabelSupport.DEFAULT_LABEL_SIZE
    this.labelHorizontalOffset = 0
    this.labelVerticalOffset = 0
    this.icon = null
    this.objectLabel = new seatsio.ObjectLabel(this)
}

seatsio.ObjectLabelSupport.prototype.refreshLabel = function () {
    this.redrawLabel()
}

seatsio.ObjectLabelSupport.prototype.redrawLabel = function () {
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.iconSizeMultiplier = function () {
    return 1
}

seatsio.ObjectLabelSupport.prototype.changeLabel = function (label) {
    if (this.label === label) return
    if (label) label = label.trim()
    this.label = label
}

seatsio.ObjectLabelSupport.prototype.setIcon = function (icon) {
    if (this.icon === icon) return
    this.icon = icon
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.changeDisplayLabel = function (displayLabel) {
    if (displayLabel === this.label || !displayLabel) {
        this.displayLabel = null
    } else {
        this.displayLabel = displayLabel
    }
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.setLabelSize = function (labelSize) {
    if (this.labelSize === labelSize) return
    this.labelSize = labelSize
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.showLabel = function () {
    this.objectLabel.show()
}

seatsio.ObjectLabelSupport.prototype.hideLabel = function () {
    this.objectLabel.hide()
}

seatsio.ObjectLabelSupport.prototype.setLabelHorizontalOffset = function (horizontalOffset) {
    if (this.labelHorizontalOffset === horizontalOffset) return
    this.labelHorizontalOffset = horizontalOffset
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.setLabelVerticalOffset = function (verticalOffset) {
    if (this.labelVerticalOffset === verticalOffset) return
    this.labelVerticalOffset = verticalOffset
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.setLabelHorizontalOffsetPerc = function (perc) {
    let newValue = Math.round(perc / 100 * this.bbox().width)
    if (this.labelHorizontalOffset === newValue) return
    this.labelHorizontalOffset = newValue
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.setLabelVerticalOffsetPerc = function (perc) {
    let newValue = Math.round(perc / 100 * this.bbox().height)
    if (this.labelVerticalOffset === newValue) return
    this.labelVerticalOffset = newValue
    this.objectLabel.redraw()
}

seatsio.ObjectLabelSupport.prototype.labelPosition = function () {
    return this.center()
        .addToX(this.labelHorizontalOffset)
        .addToY(this.labelVerticalOffset)
}

seatsio.ObjectLabelSupport.prototype.getLabelIcon = function () {
    if (this.icon) return seatsUnicode(this.icon)
    return this.isAccessible() ? seatsUnicode('wheelchair') : null
}

seatsio.ObjectLabelSupport.prototype.applyElementAttributes = function () {
    seatsio.Object.prototype.applyElementAttributes.call(this)
    this.objectLabel.applyElementAttributes()
}

seatsio.ObjectLabelSupport.DEFAULT_LABEL_SIZE = 12

seatsio.PolygonSupport = function () {}

seatsio.PolygonSupport.getPoints = function () {
    return this.getShape().points
}

seatsio.PolygonSupport.showNodes = function () {
    if (!this.showingNodes) {
        this.showingNodes = true
        this.getShape().makePointsMovable()
        this.showNodesSides()
    }
}

seatsio.PolygonSupport.hideNodes = function () {
    if (this.showingNodes) {
        this.showingNodes = false
        this.getShape().makePointsNotMovable()
        this.hideNodesSides()
    }
}

seatsio.PolygonSupport.refreshNodes = function () {
    if (this.showingNodes) {
        this.hideNodes()
        this.showNodes()
    }
}

seatsio.PolygonSupport.showNodePlaceholders = function () {
    this.showingNodePlaceholders = true
    this.getShape().showNodePlaceholders()
}

seatsio.PolygonSupport.hideNodePlaceholders = function () {
    this.showingNodePlaceholders = false
    this.getShape().hideNodePlaceholders()
}

seatsio.PolygonSupport.refreshNodePlaceholders = function () {
    if (this.showingNodePlaceholders) {
        this.hideNodePlaceholders()
        this.showNodePlaceholders()
    }
}

seatsio.PolygonSupport.showNodesSides = function () {
    if (this.sides) return
    const closeNodePath = this.shouldUseClosedNodeSides()
    this.sides = this.getPoints().map((corner, i, points) => {
        if (!closeNodePath && i === points.length - 1) {
            return null
        }
        let nextCorner = points[i + 1] || points[0]
        let side = new seatsio.PolygonSide(this, corner, nextCorner)
        side.show()
        return side
    }).filter(side => side !== null)
}

seatsio.PolygonSupport.hideNodesSides = function () {
    if (this.sides) {
        this.sides.forEach(side => side.hide())
        this.sides = null
    }
}

seatsio.PolygonSupport.shouldUseClosedNodeSides = function () {
    return this.getShape().type !== 'line'
}

seatsio.PolygonSupport.refreshNodesSides = function () {
    if (this.sides) {
        this.hideNodesSides()
        this.showNodesSides()
    }
}

seatsio.PolygonSupport.canShowStrokeSelectorOutline = function () {
    return this.getShape().type !== 'line'
}

seatsio.PolygonSupport.showStrokeSelector = function () {
    if (!this.canShowStrokeSelectorOutline()) {
        return
    }

    this.hideStrokeSelector()

    this.strokeSelector = this.designer.drawer
        .path(this.pathString(),
            {
                'stroke': '#0784fa',
                'stroke-width': this.designer.zoomer.unzoom(12),
                'opacity': 0,
                'cursor': 'pointer'
            })
        .toLayer('transformationHandlesLayer', this.designer)
        .applyZoom(this.designer)

    this.strokeSelectorOutline = this.designer.drawer
        .path(this.pathString(), { 'stroke': '#0784fa', 'stroke-width': this.designer.zoomer.unzoom(2), 'opacity': 0 })
        .toLayer('transformationHandlesLayer', this.designer)
        .applyZoom(this.designer)
    this.strokeSelectorOutline.node.setAttribute('pointer-events', 'none')

    this.strokeSelector.node.onclick = () => this.designer.setState(new seatsio.PolygonSelectedState(this.designer, [this]))
    this.strokeSelector.node.onmousedown = e => {
        e.stopPropagation()
        this.strokeSelectorOutline.attr({ stroke: '#005cc5' })
    }
    this.strokeSelector.node.onmouseup = () => this.strokeSelectorOutline.attr({ stroke: '#0784fa' })
    this.strokeSelector.node.onmouseover = () => {
        this.showStrokeSelectorTimeout = setTimeout(() => {
            if (this.strokeSelectorOutline) {
                this.strokeSelectorOutline.attr({ opacity: 1 })
            }
            this.showNodePlaceholders()
            this.showStrokeSelectorTimeout = null
        }, 50)
        this.showHUD()
    }
    this.strokeSelector.node.onmouseout = () => {
        if (this.strokeSelectorOutline) this.strokeSelectorOutline.attr({ stroke: '#0784fa', opacity: 0 })
        this.hideNodePlaceholders()
        if (this.showStrokeSelectorTimeout) {
            clearTimeout(this.showStrokeSelectorTimeout)
        }
    }
}

seatsio.PolygonSupport.hideStrokeSelector = function () {
    if (this.strokeSelector) {
        this.strokeSelector.remove()
        this.strokeSelector = null
    }
    if (this.strokeSelectorOutline) {
        this.strokeSelectorOutline.remove()
        this.strokeSelectorOutline = null
    }
}

seatsio.PolygonSupport.refreshStrokeSelector = function () {
    if (this.strokeSelector || this.strokeSelectorOutline) {
        this.showStrokeSelector()
    }
}

seatsio.PolygonSupport.addPoint = function (point, insertIndex) {
    let corner = this.getShape().addPoint(point, insertIndex)
    this.redraw()
    if (this.sides) this.refreshNodesSides()
    return corner
}

seatsio.PolygonSupport.removePoint = function (point) {
    if (this.getShape().removePoint(point)) {
        point.unhighlight()
        this.redraw()
        if (this.sides) this.refreshNodesSides()
    }
}

seatsio.PolygonSupport.pathString = function () {
    return this.getShape().pathString()
}

seatsio.PolygonSupport.hideOverlays = function () {
    if (this.strokeSelector && this.strokeSelectorOutline) {
        this.overlaysHidden = true
        this.hideStrokeSelector()
    }
}

seatsio.PolygonSupport.restoreOverlays = function () {
    if (this.overlaysHidden) {
        this.showStrokeSelector()
        this.overlaysHidden = false
    }
}

seatsio.PolygonSideDragHandle = class PolygonSideDragHandle {
    constructor (side) {
        this.side = side
        this.designer = this.side.designer
        this.arrowSize = 11
        this.interactionSize = 9
        this.elements = []
        this.hovered = false
    }

    getCenter () {
        return this.side.asRay().middle()
    }

    getAngle () {
        return this.side.asRay().angle()
    }

    isCursorHovering (cursorPoint) {
        if (this.designer.altWasPressed) {
            return false
        }
        return this.getCenter().distanceToPoint(cursorPoint) < this.designer.zoomer.unzoom(this.interactionSize)
    }

    hover () {
        if (!this.hovered) {
            this.hovered = true
            this.redraw()
        }
    }

    unhover () {
        if (this.hovered) {
            this.hovered = false
            this.redraw()
        }
    }

    redraw () {
        this.hide()
        this.show()
    }

    show () {
        if (this.elements.length > 0) {
            return
        }
        const arrowPath = this.getArrowPath(this.arrowSize + (this.hovered ? 2 : 0))
        this.elements = [
            this.drawTriangle(arrowPath),
            this.drawTriangle(arrowPath, 180)
        ]
    }

    getArrowPath (size) {
        return [
            new seatsio.Point(-size / 2, 0),
            new seatsio.Point(0, size / 2),
            new seatsio.Point(size / 2, 0),
            new seatsio.Point(-size / 2, 0)
        ]
    }

    drawTriangle (points, rotation = 0) {
        const center = this.getCenter()
        const offsetFromCenter = this.designer.zoomer.unzoom(this.hovered ? 5 : 3)
        points = points
            .map(point => center.add(point).addToY(offsetFromCenter))
            .map(point => point.rotateAround(center, this.getAngle() + rotation))
        const element = this.designer.drawLineFromPointToPoint(points)
            .applyZoomButKeepSize(this.designer)
            .toLayer('nodesLayer', this.designer)
            .attr({
                'stroke': 'white',
                'fill': seatsio.PolygonDrawingSnapper.snapColors['default'],
                'stroke-width': 1
            })
        element.node.setAttribute('pointer-events', 'none')
        return element
    }

    hide () {
        if (this.elements.length > 0) {
            this.elements.forEach(element => element.remove())
            this.elements = []
        }
    }
}

seatsio.PolygonSide = class PolygonSide {
    constructor (parent, startCorner, endCorner) {
        this.parent = parent
        this.designer = parent.designer
        this.startCorner = startCorner
        this.endCorner = endCorner
        this.nodeSize = 5
        this.hovered = false
        this.snapper = new seatsio.PolygonDrawingSnapper(this.designer)
        this.dragHandle = new seatsio.PolygonSideDragHandle(this)
        this.sideDragMove = this.sideDragMove.bind(this)
        this.sideDragEnd = this.sideDragEnd.bind(this)
    }

    refreshAltToggle () {
        if (!this.hovered) {
            return
        }
        this.updateOnMouseMove()
        if (this.designer.altWasPressed) {
            this.dragHandle.hide()
        } else {
            this.dragHandle.show()
        }
    }

    draw () {
        this.shapeElement = this.designer.drawLineBetweenPoints(this.startCorner.point, this.endCorner.point)
            .toLayer('transformationHandlesLayer', this.designer, this.parent.zIndex)
            .attr({ 'stroke': 'black', 'stroke-width': this.designer.zoomer.unzoom(12), 'opacity': 0 })
        this.shapeElement.node.onmousedown = e => {
            if (e.button !== 0) return
            if (this.dragHandle.isCursorHovering(this.getPointOnSegmentFromEvent(e))) {
                this.sideDragStart(e)
                return
            }
            this.hidePlaceholderNode()
            this.dragHandle.hide()
            let newPoint = this.getPointOnSegmentFromEvent(e)
            let newPolygonCornerPoint = this.parent.addPoint(newPoint, this.parent.getPoints().indexOf(this.endCorner))
            newPolygonCornerPoint.makeMovable()
        }
        this.shapeElement.node.onmouseover = e => {
            this.hovered = true
            if (this.dragging) {
                return
            }
            if (!this.designer.altWasPressed) {
                this.dragHandle.show()
            }
            this.designer.setCursor('node-on')
            this.showPlaceholderNode(this.getPointOnSegmentFromEvent(e))
        }
        this.shapeElement.node.onmousemove = e => {
            if (this.dragging) {
                return
            }
            this.onMouseMove(this.getPointOnSegmentFromEvent(e))
        }
        this.shapeElement.node.onmouseout = e => {
            this.hovered = false
            if (this.dragging) {
                return
            }
            this.dragHandle.hide()
            this.designer.setCursorToDefault()
            this.hidePlaceholderNode()
        }
    }

    sideDragStart (e) {
        this.parent.lockBboxCenter && this.parent.lockBboxCenter()
        this.designer.setCursor('grabbing')
        this.designer.getState().onPolygonSideDragStarted(this, seatsio.Point.fromEvent(e, this.designer))
        this.dragging = true
        this.sideDragStartPosition = this.getPointOnSegmentFromEvent(e)
        window.addEventListener('mousemove', this.sideDragMove)
        window.addEventListener('mouseup', this.sideDragEnd)
        this.dragHandle.hide()
    }

    sideDragMove (e) {
        const position = seatsio.Point.fromEvent(e, this.designer)
        this.designer.getState().onPolygonSideDragged(this, position)
    }

    sideDragEnd () {
        this.parent.releaseBboxCenter && this.parent.releaseBboxCenter()
        this.designer.setCursor('node-off')
        this.dragging = false
        window.removeEventListener('mousemove', this.sideDragMove)
        window.removeEventListener('mouseup', this.sideDragEnd)
        this.designer.getState().onPolygonSideDragEnded(this)
        this.designer.reselect()
    }

    moveTo (point) {
        const snappedPoint = this.snapper.snap(null, point, []).snapPoint
        const distanceToSide = this.asRay().enlargeOnBothSides(10000).distanceToPoint(snappedPoint)
        const perpendicularAngle = this.asRay().angle() + this.calculateDirection(snappedPoint) * 90
        const previousStartCornerPoint = this.startCorner.point
        const previousEndCornerPoint = this.endCorner.point
        this.startCorner.moveTo(this.calculateNewCornerPosition(this.startCorner, perpendicularAngle, distanceToSide))
        this.endCorner.moveTo(this.calculateNewCornerPosition(this.endCorner, perpendicularAngle, distanceToSide))
        if (this.parent.shape.isAreaLargeEnoughOnScreen(this.designer.zoomer.zoomLevel)) {
            this.parent.redraw()
        } else {
            this.startCorner.moveTo(previousStartCornerPoint)
            this.endCorner.moveTo(previousEndCornerPoint)
            this.parent.redraw()
        }
    }

    calculateNewCornerPosition (corner, perpendicularAngle, distanceToSide) {
        return new seatsio.RayFromOriginAndAngle(corner.point, perpendicularAngle).pointAtDistanceFromPoint(distanceToSide, corner.point)
    }

    calculateDirection (snappedPoint) {
        let angleBetweenSideAndPoint = new seatsio.Angle(this.asRay().angleBetween(new seatsio.Ray(this.startCorner.point, snappedPoint)))
        if (angleBetweenSideAndPoint.isQ1() || angleBetweenSideAndPoint.isQ2()) {
            return -1
        } else {
            return 1
        }
    }

    asRay () {
        return new seatsio.Ray(this.startCorner.point, this.endCorner.point)
    }

    show () {
        if (!this.shapeElement) {
            this.draw()
        }
    }

    hide () {
        this.hidePlaceholderNode()
        if (this.shapeElement) {
            this.shapeElement.remove()
            this.shapeElement = null
        }
        this.dragHandle.hide()
    }

    getPointOnSegmentFromEvent (e) {
        let clickedPoint = seatsio.Point.fromEvent(e, this.designer)
        return this.getPointOnSegment(clickedPoint)
    }

    getPointOnSegment (point) {
        return seatsio.Point.getClosestPointOnLines(point, [this.startCorner.point, this.endCorner.point])
    }

    showPlaceholderNode (point) {
        this.hidePlaceholderNode()
        this.placeholderNode = this.designer.drawer
            .rect(point.x - this.nodeSize / 2, point.y - this.nodeSize / 2, 0, 0, 0,
                {
                    'width': this.nodeSize,
                    'height': this.nodeSize,
                    'fill': 'white',
                    'stroke': seatsio.PolygonDrawingSnapper.snapColors['default'],
                    'stroke-width': 1.25
                })
            .applyZoomButKeepSize(this.designer)
        this.placeholderNode.node.setAttribute('pointer-events', 'none')
    }

    onMouseMove (point) {
        this.lastCursorPoint = point
        this.updateOnMouseMove()
    }

    updateOnMouseMove () {
        if (!this.lastCursorPoint) {
            return
        }
        if (this.dragHandle.isCursorHovering(this.lastCursorPoint)) {
            this.designer.setCursor('grab')
            this.dragHandle.hover()
            this.hidePlaceholderNode()
        } else {
            this.designer.setCursor('node-on')
            this.dragHandle.unhover()
            if (this.placeholderNode) {
                this.updatePlaceholderNode(this.lastCursorPoint)
            } else {
                this.showPlaceholderNode(this.lastCursorPoint)
            }
        }
    }

    updatePlaceholderNode (point) {
        this.placeholderNode
            .attr({
                'x': point.x - this.nodeSize / 2,
                'y': point.y - this.nodeSize / 2
            })
            .applyZoomButKeepSize(this.designer)
    }

    hidePlaceholderNode () {
        if (this.placeholderNode) {
            this.placeholderNode.remove()
            this.placeholderNode = null
        }
    }
}

seatsio.OverlayIcon = class OverlayIcon {
    constructor (parent) {
        this.parent = parent
        this.subChart = this.parent.subChart
        this.designer = this.subChart.designer
        this.label = null
        this.icon = seatsio.OverlayIcon.MISSING_ICON_PLACEHOLDER
        this.preset = 'normal'
        this.onClickCallback = null
        this.isHUDShown = false
    }

    setLabel (label) {
        this.label = label
        if (this.setElement) this.applyProperties()
    }

    setIcon (icon, preset, onClickCallback, label) {
        icon = seatsUnicode(icon) || seatsio.OverlayIcon.MISSING_ICON_PLACEHOLDER
        this.icon = icon
        this.preset = preset
        this.onClickCallback = onClickCallback
        if (typeof label !== 'undefined') this.label = label
        if (this.setElement) {
            this.applyStyling(true)
        } else {
            this.draw()
        }
    }

    showIcon (icon, preset, onClickCallback, label) {
        this.setIcon(icon, preset, onClickCallback, label)
        this.show()
    }

    onMouseDown (e) {
        e.stopPropagation()
        new SVG.Runner(100)
            .element(this.surfaceElement)
            .attr({
                'r': this.getStyle().surface.r * 0.95
            })
            .ease(SVG.easing.bezier(0.19, 1, 0.22, 1))
            .finish()
    }

    onMouseUp (e) {
        e.stopPropagation()
        new SVG.Runner(300)
            .element(this.surfaceElement)
            .attr({
                'r': this.getStyle().surface.r
            })
            .ease(SVG.easing.bezier(0.44, 2.16, 0.47, 0.74))
            .finish()
    }

    onMouseOver (e) {
        if (this.isHUDShown) return
        this.isHUDShown = true
        new SVG.Runner(200)
            .element(this.surfaceElement)
            .attr({
                'r': this.getStyle().surface.r * 1.08
            })
            .ease(SVG.easing.bezier(0.44, 2.16, 0.47, 0.74))
            .finish()
    }

    onMouseOut (e) {
        if (!this.isHUDShown) return
        if (this.parent.selector && e.toElement !== this.parent.selector.selectionRectangle) {
            this.designer.getState().onObjectMouseOut(this.parent, e)
        }
        this.isHUDShown = false
        new SVG.Runner(300)
            .element(this.surfaceElement)
            .attr({
                'r': this.getStyle().surface.r
            })
            .ease(SVG.easing.bezier(0.44, 2.16, 0.47, 0.74))
            .finish()
    }

    onClick (e) {
        e.stopPropagation()
        this.onClickCallback(e)
    }

    determineObjectPosition () {
        return this.parent.centroid(this.designer.zoomer.unzoom(20))
    }

    draw () {
        if (!this.setElement) {
            this.setElement = seatsio.set()
        }

        this.surfaceElement = this.designer.drawer.circle(0, 0, 0, {})
            .toLayer('overlayIconsLayer', this.designer, this.parent.zIndex)
            .applyZoom(this.designer)

        this.iconElement = this.designer.drawer.text(0, 0, '', {})
            .toLayer('overlayIconsLayer', this.designer, this.parent.zIndex)
            .applyZoom(this.designer)
        this.iconElement.node.setAttribute('pointer-events', 'none')

        this.labelElement = this.designer.drawer.text(0, 0, '', {})
            .toLayer('overlayIconsLayer', this.designer, this.parent.zIndex)
            .applyZoom(this.designer)
        this.labelElement.node.setAttribute('pointer-events', 'none')

        if (this.forChair()) this.setElement.push(this.surfaceElement, this.iconElement)
        else this.setElement.push(this.surfaceElement, this.iconElement, this.labelElement)

        this.surfaceElement.node.onmouseover = this.onMouseOver.bind(this)
        this.surfaceElement.node.onmouseout = this.onMouseOut.bind(this)
        this.surfaceElement.node.onmousedown = this.onMouseDown.bind(this)
        this.surfaceElement.node.onmouseup = this.onMouseUp.bind(this)
        this.surfaceElement.node.onclick = this.onClick.bind(this)

        this.applyStyling(true)

        if (this.visible) {
            this.show()
        } else {
            this.hide()
        }
    }

    applyProperties () {
        this.iconElement.node.textContent = this.getIconElementText()
        this.labelElement.node.textContent = this.getLabelElementText()
    }

    getIconElementText () {
        return this.icon
    }

    getLabelElementText () {
        return this.label
    }

    applyStyling (withProperties = false) {
        let position = this.determineObjectPosition()
        let style = this.getStyle()

        this.surfaceElement
            .attr(Object.assign(
                {
                    'cx': position.x,
                    'cy': this.forChair() ? position.y : position.y - this.applyScale(10),
                    'r': style.surface.r,
                    'stroke-width': style.surface['stroke-width'],
                    'cursor': 'pointer'
                },
                style.surface))

        this.iconElement
            .attr({
                'x': position.x,
                'y': this.forChair() ? position.y : position.y - this.applyScale(10),
                'font-size': style.icon['font-size'],
                'cursor': 'pointer',
                'font-family': 'seatsdesigner',
                'fill': style.icon.fill
            })
        if (withProperties && this.iconElement.node) {
            this.iconElement.node.textContent = this.getIconElementText()
        }

        if (!this.forChair()) {
            this.labelElement
                .attr({
                    'x': position.x,
                    'y': position.y + this.applyScale(10),
                    'font-size': style.label['font-size'],
                    'font-family': seatsio.TextInput.defaultFontFamily,
                    'fill': style.label.fill
                })
            if (withProperties && this.labelElement.node) {
                this.labelElement.node.textContent = this.getLabelElementText()
            }
        }
    }

    forChair () {
        return this.preset === 'chair-highlight'
    }

    undraw () {
        if (this.setElement) this.setElement.remove()
    }

    redraw () {
        if (this.setElement) this.setElement.clear()
        this.draw()
    }

    applyScale (value) {
        return this.designer.zoomer.unzoom(value)
    }

    applyZoom () {
        this.applyStyling()
    }

    show () {
        this.visible = true
        if (this.setElement) {
            this.setElement.show()
        }
    }

    hide () {
        this.visible = false
        if (this.setElement) this.setElement.hide()
    }

    visibleElementsSet () {
        return [this.setElement]
    }

    getSurfaceNode () {
        return this.surfaceElement.node
    }

    isBackgroundLight () {
        return new seatsio.Color(this.parent.determineNonHighlightedColor()).isLight()
    }

    getStyle () {
        switch (this.preset) {
            case 'highlight':
                return {
                    surface: {
                        'r': this.applyScale(11),
                        'fill': 'white',
                        'fill-opacity': 1,
                        'stroke': 'black',
                        'stroke-width': this.applyScale(0.5),
                        'stroke-opacity': 0.2
                    },
                    icon: {
                        'fill': 'rgba(0, 0, 0, 1)',
                        'font-size': this.applyScale(12)
                    },
                    label: {
                        'fill': this.isBackgroundLight() ? 'rgba(0, 0, 0, .8)' : 'rgba(255, 255, 255, .8)',
                        'font-size': this.applyScale(8)
                    }
                }
            case 'blur':
                return {
                    surface: {
                        'r': this.applyScale(11),
                        'fill': 'white',
                        'fill-opacity': 0.35,
                        'stroke': 'black',
                        'stroke-width': this.applyScale(0.5),
                        'stroke-opacity': 0.1
                    },
                    icon: {
                        'fill': 'rgba(50, 50, 50, 0.4)',
                        'font-size': this.applyScale(12)
                    },
                    label: {
                        'fill': this.isBackgroundLight() ? 'rgba(0, 0, 0, .6)' : 'rgba(255, 255, 255, .6)',
                        'font-size': this.applyScale(8)
                    }
                }
            case 'chair-highlight':
                return {
                    surface: {
                        'r': 8,
                        'fill': 'white',
                        'fill-opacity': 1,
                        'stroke': 'black',
                        'stroke-width': 1,
                        'stroke-opacity': 1
                    },
                    icon: {
                        'fill': 'rgba(0, 0, 0, 1)',
                        'font-size': 11
                    }
                }
            default:
                return {
                    surface: {
                        'r': this.applyScale(11),
                        'fill': 'white',
                        'fill-opacity': 1,
                        'stroke': 'black',
                        'stroke-width': this.applyScale(0.5),
                        'stroke-opacity': 0.2
                    },
                    icon: {
                        'fill': 'rgba(0, 0, 0, 1)',
                        'font-size': this.applyScale(12)
                    },
                    label: {
                        'fill': this.isBackgroundLight() ? 'rgba(0, 0, 0, .8)' : 'rgba(255, 255, 255, .8)',
                        'font-size': this.applyScale(8)
                    }
                }
        }
    }
}

seatsio.OverlayIcon.MISSING_ICON_PLACEHOLDER = '✻'

seatsio.PositionGuidesSupport = function () {}

seatsio.PositionGuidesSupport.prototype.drawPositionGuides = function (simple) {
    this.undrawPositionGuides()
    this.positionGuides = seatsio.PositionGuidesSupport.drawPositionGuides(this.designer, this.getPositionGuides(), simple)
    return this
}

seatsio.PositionGuidesSupport.drawPositionGuidesFromBBox = function (designer, bbox) {
    let positionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRect(bbox, designer)
    return seatsio.PositionGuidesSupport.drawPositionGuides(designer, positionGuides)
}

seatsio.PositionGuidesSupport.drawRowPositionGuidesFromRay = function (designer, ray, snapType) {
    let positionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRow(designer, ray, 0, snapType)
    return seatsio.PositionGuidesSupport.drawPositionGuides(designer, positionGuides)
}

seatsio.PositionGuidesSupport.drawRowPositionGuidesFromMultiRay = function (designer, multiRay, snapType) {
    let positionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForSegmentedRow(designer, multiRay, snapType)
    return seatsio.PositionGuidesSupport.drawPositionGuides(designer, positionGuides)
}

seatsio.PositionGuidesSupport.drawRowPositionGuidesFromPoint = function (designer, point) {
    let positionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint(designer, point)
    return seatsio.PositionGuidesSupport.drawPositionGuides(designer, positionGuides)
}

seatsio.PositionGuidesSupport.drawPositionGuides = function (designer, positionGuides, simple = false) {
    let elementSet = seatsio.set()
    positionGuides.forEach(guide => {
        let ray = guide.ray
        let color = seatsio.PositionGuidesSupport.GUIDE_COLORS[guide.color] || seatsio.PositionGuidesSupport.GUIDE_COLORS.blue
        let opacity = guide.opacity || 1
        if (guide.circles) {
            if (simple) {
                return
            }
            const distance = designer.zoomer.unzoom(200)
            const rayLeft = ray.revert().enlarge(distance).revert().enlarge(-ray.length()).revert()
            const rayRight = ray.enlarge(distance).revert().enlarge(-ray.length()).revert()
            const invisibleStyle = {
                opacity: 0
            }
            const style = {
                stroke: color,
                fill: 'none',
                opacity
            }
            const drawChairs = (chair, i) => {
                if (i > 0) {
                    chair.attr(style)
                } else {
                    chair.attr(invisibleStyle)
                }
            }

            const chairShapesLeft = seatsio.Row.drawShapes(rayLeft.origin, rayLeft.end, designer, guide.circlesGap)
            chairShapesLeft.forEach(drawChairs)

            const chairShapesRight = seatsio.Row.drawShapes(rayRight.origin, rayRight.end, designer, guide.circlesGap)
            chairShapesRight.forEach(drawChairs)

            elementSet.push(chairShapesLeft, chairShapesRight)
        } else {
            if (!guide.segment) {
                ray = ray.enlargeOnBothSides(designer.zoomer.unzoom(1200))
            }
            let element = designer
                .drawLine(ray.origin.x, ray.origin.y, ray.end.x, ray.end.y)
                .attr({
                    'opacity': opacity,
                    'stroke': color,
                    'stroke-dasharray': guide.dasharray,
                    'stroke-width': designer.zoomer.unzoom(guide.width || 1.5)
                })
            element.node.setAttribute('pointer-events', 'none')
            elementSet.push(element)
        }
    })
    elementSet
        .toLayer('guides', designer)
        .applyZoom(designer)
    return elementSet
}

seatsio.PositionGuidesSupport.prototype.getPositionGuides = function () {
    return []
}

seatsio.PositionGuidesSupport.prototype.undrawPositionGuides = function () {
    if (this.positionGuides) {
        this.positionGuides.forEach(item => item.remove())
        this.positionGuides.clear()
    }
    return this
}

seatsio.PositionGuidesSupport.prototype.positionGuideBBox = function () {
    return this.bbox()
}

seatsio.PositionGuidesSupport.prototype.positionGuideRay = function () {
    return new seatsio.Ray(this.center(), this.center())
}

seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRect = function (bbox, designer) {
    if (typeof bbox === 'undefined') {
        bbox = this.positionGuideBBox()
    }
    const width = 1
    designer = designer || this.designer
    const opacity = designer.getCanvasColorScheme() !== 'light' ? 0.4 : 0.2
    return [
        {
            ray: new seatsio.Ray(bbox.topLeft(), bbox.topRight()),
            color: 'blue',
            width,
            opacity
        },
        {
            ray: new seatsio.Ray(bbox.bottomLeft(), bbox.bottomRight()),
            color: 'blue',
            width,
            opacity
        },
        {
            ray: new seatsio.Ray(bbox.topLeft(), bbox.bottomLeft()),
            color: 'blue',
            width,
            opacity
        },
        {
            ray: new seatsio.Ray(bbox.topRight(), bbox.bottomRight()),
            color: 'blue',
            width,
            opacity
        },
        {
            ray: new seatsio.Ray(bbox.middleLeft(), bbox.middleRight()),
            color: 'magenta',
            width,
            opacity
        },
        {
            ray: new seatsio.Ray(bbox.topMiddle(), bbox.bottomMiddle()),
            color: 'magenta',
            width,
            opacity
        }
    ]
}

seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRow = function (designer, ray, circles, snapType) {
    let circlesGap = 0
    if (typeof ray === 'undefined') {
        ray = this.positionGuideRay()
    }
    if (typeof circles === 'undefined' && !this.curveGhostPointsSet()) {
        circles = this.chairs.length
        circlesGap = this.chairSpacing || 0
    }
    const darkMode = designer.getCanvasColorScheme !== 'light'
    const angleSnap = snapType === 'angle'
    const axisSnap = snapType === 'axis'
    let guides = [
        {
            ray,
            color: angleSnap ? 'gold' : (axisSnap ? 'green' : 'magenta'),
            width: 1,
            opacity: snapType ? 1 : (darkMode ? 0.6 : 0.3)
        },
        {
            ray: new seatsio.Ray(ray.origin, ray.end.rotateAround(ray.origin, 90)),
            color: 'blue',
            width: 1,
            opacity: darkMode ? 0.4 : 0.2
        },
        {
            ray: new seatsio.Ray(ray.end, ray.origin.rotateAround(ray.end, 90)),
            color: 'blue',
            width: 1,
            opacity: darkMode ? 0.4 : 0.2
        }
    ]
    if (circles) {
        guides.push({
            ray,
            color: 'blue',
            circles,
            circlesGap,
            opacity: darkMode ? 0.7 : 0.4
        })
    }
    return guides
}

seatsio.PositionGuidesSupport.prototype.getPositionGuidesForSegmentedRow = function (designer, multiRay, snapType) {
    if (typeof multiRay === 'undefined') {
        multiRay = this.positionGuideRay()
    }
    const darkMode = designer.getCanvasColorScheme !== 'light'
    const angleSnap = snapType === 'angle'
    const axisSnap = snapType === 'axis'
    let guides = [
        {
            ray: multiRay.first(),
            color: 'magenta',
            width: 1,
            opacity: (darkMode ? 0.6 : 0.3)
        },
        {
            ray: multiRay.last(),
            color: angleSnap ? 'gold' : (axisSnap ? 'green' : 'magenta'),
            width: 1,
            opacity: snapType ? 1.0 : (darkMode ? 0.6 : 0.3)
        },
        {
            ray: new seatsio.Ray(multiRay.first().origin, multiRay.first().end.rotateAround(multiRay.first().origin, 90)),
            color: 'blue',
            width: 1,
            opacity: darkMode ? 0.4 : 0.2
        },
        {
            ray: new seatsio.Ray(multiRay.last().end, multiRay.last().origin.rotateAround(multiRay.last().end, 90)),
            color: 'blue',
            width: 1,
            opacity: darkMode ? 0.4 : 0.2
        }
    ]
    return guides
}

seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint = function (designer, point, snapType, snapRay, snapSecondRay = null) {
    if (typeof designer === 'undefined') {
        designer = this.designer
    }
    if (typeof point === 'undefined') {
        point = this.point
    }
    let extension = designer.zoomer.unzoom(1200)
    if (['firstCorner', 'closestCorner'].includes(snapType)) {
        return []
    }
    let verticallyAligned = ['verticallyAligned', 'rayAlignedAndVertical'].includes(snapType)
    let horizontallyAligned = ['horizontallyAligned', 'rayAlignedAndHorizontal'].includes(snapType)
    let guides = [
        {
            ray: new seatsio.Ray(point.addToY(-extension), point.addToY(extension)),
            color: verticallyAligned ? 'green' : 'blue',
            width: 1,
            opacity: verticallyAligned ? 1 : 0.5
        },
        {
            ray: new seatsio.Ray(point.addToX(-extension), point.addToX(extension)),
            color: horizontallyAligned ? 'green' : 'blue',
            width: 1,
            opacity: horizontallyAligned ? 1 : 0.5
        }
    ]
    if (snapRay) {
        guides.push({
            ray: snapRay,
            color: 'magenta',
            width: 2,
            opacity: 1,
            segment: true
        },
        {
            ray: snapRay,
            color: 'magenta',
            width: 1,
            opacity: 1
        })
    }
    if (snapSecondRay) {
        guides.push({
            ray: snapSecondRay,
            color: 'magenta',
            width: 2,
            opacity: 1,
            segment: true
        },
        {
            ray: snapSecondRay,
            color: 'magenta',
            width: 1,
            opacity: 1
        })
    }
    return guides
}

seatsio.PositionGuidesSupport.GUIDE_COLORS = {
    blue: 'rgb(0, 136, 255)',
    magenta: '#FF0070',
    gold: '#FFA700',
    grey: 'rgb(60, 60, 60)',
    green: '#9DE329'
}

seatsio.PositionGuidesSet = class PositionGuidesSet {
    constructor (designer, guides) {
        this.designer = designer
        this.guides = guides
        this.elementSet = seatsio.set()
    }

    set () {
        return this.elementSet
    }

    getGuides () {
        return typeof this.guides === 'function' ? this.guides() : (this.guides || [])
    }

    draw (simple) {
        if (typeof this.simple !== 'undefined') {
            this.simple = simple
        }
        this.undraw()
        this.elementSet = seatsio.PositionGuidesSupport.drawPositionGuides(this.designer, this.getGuides(), this.simple)
        return this
    }

    refresh (guides) {
        this.guides = guides
        this.draw()
        return this
    }

    undraw () {
        this.elementSet.forEach(item => item.remove())
        this.elementSet.clear()
        return this
    }
}

seatsio.Features = function (designer) {
    this.designer = designer
    this.modifiers = []
}

seatsio.Features.prototype.withModifier = function (modifier) {
    this.modifiers.push(modifier)
    return this
}

seatsio.Features.prototype.isEnabled = function (feature) {
    var status = this.getStatus(feature)
    return status === seatsio.Features.Status.ENABLED || status === seatsio.Features.Status.UNHIDDEN
}

seatsio.Features.prototype.isDisabled = function (feature) {
    var status = this.getStatus(feature)
    return status === seatsio.Features.Status.DISABLED || status === seatsio.Features.Status.HIDDEN
}

seatsio.Features.prototype.isReadOnly = function (feature) {
    return this.getStatus(feature) === seatsio.Features.Status.READ_ONLY
}

seatsio.Features.prototype.getStatus = function (feature) {
    return this.modifiers.reduce(function (status, modifier) {
        var newStatus = modifier.getFeatureStatus(feature, status)
        if (newStatus) {
            return newStatus
        }
        return status
    }, seatsio.Features.Status.ENABLED)
}

seatsio.Features.prototype.getDisabled = function () {
    return Object.values(seatsio.Features.Type).map((featureName) => {
        if (this.isDisabled(featureName) || this.isReadOnly(featureName)) {
            return featureName
        }
    })
}

seatsio.Features.Type = {}
