seatsio.Chair.prototype.determineStrokeWidth = function () {
    if (this.parent.bookAsAWhole) {
        return 3
    }
    return seatsio.Chair.drawStrokeWidth
}

seatsio.Chair.prototype.determineStrokeColor = function () {
    if (this.parent.bookAsAWhole) {
        return seatsio.Color.create(this.determineBaseColor()).softenedBy(this.hasVisibleIcon() ? 50 : 65, this.isDarkCanvas()).toCSS()
    }
    if (this.hasVisibleIcon()) {
        return this.determineFillColor()
    }
    return seatsio.Object.prototype.determineStrokeColor.apply(this)
}

seatsio.Chair.prototype.determineFillColor = function (baseColor = undefined) {
    if (baseColor === undefined) {
        baseColor = this.determineBaseColor()
    }
    if (this.parent.bookAsAWhole) {
        return seatsio.Color.create(baseColor).softenedBy(this.hasVisibleIcon() ? 50 : 25, this.isDarkCanvas()).toCSS()
    }
    return seatsio.Color.create(baseColor).softenedBy(50, this.isDarkCanvas()).toCSS()
}

seatsio.Chair.prototype.getRotation = function () {
    return this.parent.getRotation()
}

seatsio.Chair.prototype.undraw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    this.overlayIcon.undraw()
    if (this.circle) {
        if (this.labeler) {
            this.labeler.objectUndrawn()
        }
        this.circle.remove()
        this.circle = null
    }
    if (this.iconLabel) {
        this.iconLabel.remove()
        this.iconLabel = null
    }
}

