seatsio.SelectedObjects.prototype.joinSelectedObjects = function () {
    const mergingObjects = this.arrayOfObjects.concat()
    const mainObject = mergingObjects.shift()
    const newCombinedObject = mainObject.join(mergingObjects)
    this.arrayOfObjects.forEach(object => object.remove())
    newCombinedObject.redraw()
    this.designer.renderUI()
    return newCombinedObject
}

seatsio.SelectedObjects.prototype.splitSelectedObjects = function () {
    const unmergedObjects = this.arrayOfObjects.flatMap(object => object.split())
    this.arrayOfObjects.forEach(object => object.remove())
    unmergedObjects.forEach(object => object.redraw())
    this.designer.renderUI()
    return unmergedObjects
}

