seatsio.SelectedObjects.prototype.invertObjectLabeling = function () {
    let labels = this.getArrayOfObjectsSorted().map(o => o.label)
    this.getArrayOfObjectsSorted().reverse().forEach((object, index) => object.changeLabel(labels[index]))
    this.designer.renderUI()
}

