seatsio.ChartStatsGenerator = class ChartStatsGenerator {
    constructor (subChartFloors, subCharts, categories, designer) {
        this.subChartFloors = subChartFloors
        this.subCharts = subCharts
        this.categories = categories
        this.designer = designer
    }

    getTotalPeopleCapacity () {
        return this.subCharts.reduce((total, subChart) => total + subChart.totalPeopleCapacity(), 0)
    }

    getTotalBooths () {
        return this.subCharts.reduce((total, subChart) => total + subChart.allBooths().length, 0)
    }

    getTotalNumberOfTables () {
        return this.subCharts.reduce((total, subChart) => total + subChart.allTables().length, 0)
    }

    getNumberOfUnlabeledSeats (subCharts = this.subCharts) {
        return subCharts.flatMap(subChart => subChart.objectsWithSeats()).reduce((total, object) => {
            return total + object.numberOfUnlabeledSeats()
        }, 0)
    }

    getNumberOfUnlabeledTables (subCharts = this.subCharts) {
        return subCharts.flatMap(subChart => subChart.tables.tables).reduce((total, table) => {
            if (table.hasLabel()) {
                return total
            }
            return total + 1
        }, 0)
    }

    getTotalNumberOfRows () {
        return this.subCharts.flatMap(subChart => subChart.allRows()).length
    }

    getNumberOfUnlabeledRows (subCharts = this.subCharts) {
        return subCharts.flatMap(subChart => subChart.rows).reduce((total, row) => {
            if (row.hasLabel()) {
                return total
            }
            return total + 1
        }, 0)
    }

    getDuplicateObjects () {
        let allBookableObjectsWithLabel = this.subChartFloors.allBookableObjectsWithTables()
            .filter(object => object.hasLabel())
        let objectsByLabel = _.groupBy(allBookableObjectsWithLabel, object => object.getFullLabel())
        let objectsOfSubchartByLabel = _.mapValues(objectsByLabel, this.onlyObjectsFromSubCharts(this.subCharts))
        return _.omitBy(objectsOfSubchartByLabel, objects => objects.length <= 1)
    }

    onlyObjectsFromSubCharts (subCharts) {
        if (this.masterSubChartScope(subCharts)) {
            return objects => objects
        }
        return objects => {
            let containsObjectsOfSubchart = objects.some(object => subCharts.includes(object.subChart))
            return containsObjectsOfSubchart ? objects : []
        }
    }

    getUncategorized (subCharts = this.subCharts) {
        let details = subCharts.flatMap(subChart => subChart.categorisableParentObjects()).map(object => {
            let count = 0
            if (object.type === 'section') {
                count = this.getUncategorized([object.sectionSubChart]).count
            } else if (object.type === 'table' || object.type === 'row') {
                count = object.subChart.category ? 0 : object.uncategorizedChildren().length
            } else {
                count = object.subChart.category || object.category ? 0 : 1
            }
            return {
                uuid: object.uuid,
                floor: this.subChartFloors.hasMultipleFloors() ? object.floorName() : undefined,
                type: object.type,
                label: object.label,
                count
            }
        }).filter(entry => entry.count > 0)

        return {
            count: details.reduce((total, entry) => total += entry.count, 0),
            details
        }
    }

    getUnlabeled (subCharts = this.subCharts) {
        let details = subCharts.flatMap(subChart => subChart.bookableParentObjectsWithSections()).map(object => {
            let numberOfUnlabeledChildren = 0
            if (object.type === 'section') {
                numberOfUnlabeledChildren = this.getUnlabeled([object.sectionSubChart]).count
            } else if (object.type === 'table' || object.type === 'row') {
                numberOfUnlabeledChildren = object.numberOfUnlabeledSeats()
            } else if ((object.type === 'booth' || object.type === 'generalAdmission') && !object.hasLabel()) {
                numberOfUnlabeledChildren = 0
            } else {
                return { count: 0 }
            }
            return {
                uuid: object.uuid,
                floor: this.subChartFloors.hasMultipleFloors() ? object.floorName() : undefined,
                type: object.type,
                label: object.label,
                count: numberOfUnlabeledChildren,
                isUnlabeled: object.isUnlabeled()
            }
        }).filter(entry => entry.count > 0 || entry.isUnlabeled)

        return {
            count: details.reduce((total, entry) => {
                return total + entry.count + (entry.isUnlabeled ? 1 : 0)
            }, 0),
            details
        }
    }

    getCapacityByObjectType (subCharts = this.subCharts) {
        return subCharts.flatMap(subChart => subChart.allBookableParentObjects()).reduce((capacities, object) => {
            let capacity = object.totalPeopleCapacity()
            if (capacity > 0) {
                if (!capacities[object.type]) {
                    capacities[object.type] = 0
                }
                capacities[object.type] += capacity
            }
            return capacities
        }, {})
    }

    getCapacityByCategory (subCharts = this.subCharts) {
        return subCharts.flatMap(subChart => subChart.allBookableObjects()).reduce((capacities, object) => {
            let capacity = object.totalPeopleCapacity()
            if (capacity > 0) {
                let category = object.category || object.subChart.category
                let categoryId = category ? category.key : -1
                if (!capacities[categoryId]) {
                    capacities[categoryId] = 0
                }
                capacities[categoryId] += capacity
            }
            return capacities
        }, {})
    }

    getBoothsByCategory (subCharts = this.subCharts) {
        return subCharts.flatMap(subChart => subChart.allBooths()).reduce((capacities, object) => {
            let category = object.category || object.subChart.category
            let categoryId = category ? category.key : -1
            if (!capacities[categoryId]) {
                capacities[categoryId] = 0
            }
            capacities[categoryId] += 1
            return capacities
        }, {})
    }

    getObjectTypesByCategory () {
        let typesByCategory = this.categories.all().reduce((r, category) => {
            r[category.key] = []
            return r
        }, {})
        this.subChartFloors.allBookableObjects().forEach(object => {
            let categoryKey = (object.category || object.subChart.category || {}).key
            if (categoryKey && typesByCategory[categoryKey] !== undefined) {
                let objectType = object.type === 'chair' ? object.parent.type : object.type
                if (!typesByCategory[categoryKey].contains(objectType)) {
                    typesByCategory[categoryKey].push(objectType)
                }
            }
        })
        return typesByCategory
    }

    getFileSizeByImageWithBackground (subCharts) {
        let listing = this.getFileSizeByImage(subCharts)
        this.subCharts
            .filter(subChart => subChart.isMasterSubChart() && subChart.backgroundImage.url() && subChart.backgroundImage.showOnRenderedCharts)
            .forEach(subChart => listing[subChart.backgroundImage.url()] = subChart.backgroundImage.fileSize())
        return listing
    }

    getFileSizeByImage (subCharts = this.subCharts) {
        let listing = {}
        return subCharts.flatMap(subChart => subChart.allImageObjects()).reduce((listing, image) => {
            listing[image.url()] = image.fileSize
            return listing
        }, listing)
    }

    getImagesTotalSize (subCharts = this.subCharts) {
        let imageObjectsSize = Object.values(this.getFileSizeByImage(subCharts))
            .reduce((total, fileSize) => total + fileSize, 0)
        let backgroundImagesSize = subCharts
            .filter(subChart => subChart.isMasterSubChart() && subChart.backgroundImage.showOnRenderedCharts)
            .reduce((total, subChart) => total + subChart.backgroundImage.fileSize(), 0)
        return imageObjectsSize + backgroundImagesSize
    }

    getEmptySections (subChartFloors = this.subChartFloors) {
        return subChartFloors.allMasterSubCharts()
            .flatMap(masterSubChart => masterSubChart.allSubCharts())
            .filter(subChart => subChart.isEmpty() && subChart.isSectionSubChart())
            .map(sectionSubChart => {
                const { label, uuid } = sectionSubChart.section
                return {
                    label,
                    uuid,
                    type: 'section'
                }
            })
    }

    isMissingFocalPoint () {
        if (this.designer.isVenueWithZones()) {
            return undefined
        }
        return !this.subChartFloors.firstFloorSubChart().focalPoint.isSet()
    }

    getZonesMissingFocalPoint () {
        const zones = this.designer.zones.getZonesMissingFocalPoint()
        return {
            count: zones.length,
            details: zones
        }
    }

    getTotalZonesMissingFocalPoint () {
        if (this.designer.zones.count() === 0) {
            return undefined
        }
        return this.designer.zones.getZonesMissingFocalPoint().length
    }

    hasUnusedFloors () {
        if (this.subChartFloors.hasMultipleFloors()) {
            return this.subChartFloors.allMasterSubCharts().some(masterSubChart => masterSubChart.isUnused())
        }
        return undefined
    }

    hasNoObjects () {
        return this.subChartFloors.allBookableObjects().length === 0
    }

    hasObjectsOutOfBounds (subChart = this.subCharts[0]) {
        return !subChart.isMasterSubChart() && subChart.allSelectableObjectsExceptSections().some(object => object.getIsOutOfBounds())
    }

    masterSubChartScope (subCharts) {
        return subCharts.some(subChart => subChart.isMasterSubChart())
    }
}

seatsio.Keyboard = class Keyboard {
    constructor (designer) {
        this.designer = designer
        this.ZOOM_SCALE_THRESHOLD = 0.1
        this.EDITABLE_TEXT_QUERY = '#drawing > .editableText'
    }

    onGestureStart (e) {
        e.preventDefault()
        let viewportCenterInCanvas = this.designer.pointInCanvasCenteredInViewport()
        let zoomTransformOriginX = viewportCenterInCanvas.x / this.designer.canvas().width()
        let zoomTransformOriginY = viewportCenterInCanvas.y / this.designer.canvas().height()
        this.designer.canvas().css('transform-origin', `${zoomTransformOriginX * 100}% ${zoomTransformOriginY * 100}%`)
        $(this.EDITABLE_TEXT_QUERY).hide()
    }

    onGestureChange (e) {
        e.preventDefault()
        let scale = this.clampZoomScale(e.originalEvent.scale)
        this.designer.canvas().css('transform', `scale(${scale})`)
    }

    onGestureEnd (e) {
        e.preventDefault()
        this.designer.zoomer.zoom(this.designer.pointInCanvasCenteredInViewport(), this.designer.zoomer.zoomLevel * e.originalEvent.scale)
        this.designer.canvas().css('transform', 'none')
        $(this.EDITABLE_TEXT_QUERY).show()
    }

    onWheel (e) {
        if (this.altPressed(e)) {
            e.preventDefault()
            e.stopPropagation()
            let mousePosition = new seatsio.Point(e.originalEvent.pageX, e.originalEvent.pageY)
            this.designer.canvas().css('transform-origin', `${mousePosition.x}px ${mousePosition.y}px`)
            if (this.setFinalZoomTimeout) {
                clearTimeout(this.setFinalZoomTimeout)
            } else {
                this.wheelZoomScale = 1.0
                $(this.EDITABLE_TEXT_QUERY).hide()
            }
            this.wheelZoomScale = this.clampZoomScale(this.wheelZoomScale + e.originalEvent.deltaY / 200)
            this.designer.canvas().css('transform', `scale(${this.wheelZoomScale})`)
            this.setFinalZoomTimeout = setTimeout(() => {
                this.designer.zoomer.zoom(mousePosition, this.designer.zoomer.zoomLevel * this.wheelZoomScale)
                this.setFinalZoomTimeout = null
                this.designer.canvas().css('transform', 'none')
                $(this.EDITABLE_TEXT_QUERY).show()
            }, 300)
        }
    }

    clampZoomScale (scale) {
        let minScale = seatsio.Zoomer.minZoomLevel / this.designer.zoomer.zoomLevel
        let maxScale = seatsio.Zoomer.maxZoomLevel / this.designer.zoomer.zoomLevel
        return Math.min(maxScale, Math.max(minScale, scale))
    }

    onKeyDown (e) {
        let modifierHasChanged = this.modifierChanged(e)

        this.designer.ctrlWasPressed = this.ctrlPressed(e)
        this.designer.shiftWasPressed = this.shiftPressed(e)
        this.designer.altWasPressed = this.altPressed(e)

        if (this.isSpacebar(e)) {
            e.preventDefault()
            e.stopPropagation()
            this.designer.state.onSpacebarPressed()
        }
        if (this.deletePressed(e)) {
            e.preventDefault()
            this.designer.onDelete()
        } else if (this.enterPressed(e)) {
            this.designer.state.onEnterPressed()
        } else if (this.duplicatePressed(e)) {
            this.designer.onDuplicate()
        } else if (this.copyCombinationPressed(e)) {
            e.preventDefault()
            this.designer.onCopy()
        } else if (this.cutCombinationPressed(e)) {
            e.preventDefault()
            this.designer.onCut()
        } else if (this.pasteCombinationPressed(e)) {
            e.preventDefault()
            this.designer.onPaste()
        } else if (this.exitSectionPressed(e)) {
            e.preventDefault()
            if (this.designer.activeSubChart()) {
                this.designer.showMasterSubChart()
            }
        } else if (this.escapePressed(e)) {
            e.preventDefault()
            this.designer.state.onEscapePressed()
        } else if (this.undoCombinationPressed(e)) {
            this.designer.onUndoPressed(e)
        } else if (this.redoCombinationPressed(e)) {
            this.designer.redo()
        } else if (this.arrowPressed(e)) {
            this.designer.state.onArrowPressed(e)
        } else if (this.altPressed(e)) {
            this.designer.state.onAltPressed(e)
        } else if (this.shiftPressed(e)) {
            this.designer.state.onShiftPressed(e)
        } else if (this.ctrlPressed(e)) {
            this.designer.state.onCtrlPressed(e)
        }

        if (this.floorPressed(e)) {
            e.preventDefault()
            e.stopPropagation()
            this.designer.goToFloor(e.keyCode - KEYS.NUM_1)
        } else if (this.deselectPressed(e)) {
            e.preventDefault()
            this.designer.state.deselect()
        } else if (this.toggleReferenceChartPressed(e)) {
            e.preventDefault()
            this.designer.uiEvents.toggleReferenceChartVisible()
        } else if (this.toggleReferenceChartShowAbovePressed(e)) {
            e.preventDefault()
            this.designer.uiEvents.setReferenceChartShowAbove(true)
        } else if (this.hotkeyPressed(e)) {
            e.preventDefault()
            let event = this.hotkeyPressed(e).uiEvent
            if (event) {
                this.designer.uiEvents.trigger(event)
            }
        }

        if (modifierHasChanged) {
            this.designer.state.onModifierChange(e)
            this.designer.renderUI()
        }
    }

    onKeyUp (e) {
        let modifierHasChanged = this.modifierChanged(e)
        let ctrlWasPressed = this.designer.ctrlWasPressed
        let shiftWasPressed = this.designer.shiftWasPressed
        let altWasPressed = this.designer.altWasPressed

        this.designer.ctrlWasPressed = this.ctrlPressed(e)
        this.designer.shiftWasPressed = this.shiftPressed(e)
        this.designer.altWasPressed = this.altPressed(e)

        if (this.isSpacebar(e)) {
            e.preventDefault()
            e.stopPropagation()
            this.designer.state.onSpacebarReleased()
        }
        if (altWasPressed && !this.altPressed(e)) {
            this.designer.state.onAltReleased()
        }
        if (shiftWasPressed && !this.shiftPressed(e)) {
            this.designer.state.onShiftReleased()
        }
        if (ctrlWasPressed && !this.ctrlPressed(e)) {
            this.designer.state.onCtrlReleased()
        }

        if (this.toggleReferenceChartShowAbovePressed(e)) {
            e.preventDefault()
            this.designer.uiEvents.setReferenceChartShowAbove(false)
        }

        if (modifierHasChanged) {
            this.designer.state.onModifierChange(e)
            this.designer.renderUI()
        }
    }

    releaseAllModifierKeys () {
        if (this.designer.altWasPressed) {
            this.designer.altWasPressed = false
            this.designer.state.onAltReleased()
        }
        if (this.designer.ctrlWasPressed) {
            this.designer.ctrlWasPressed = false
            this.designer.state.onCtrlReleased()
        }
        if (this.designer.shiftWasPressed) {
            this.designer.shiftWasPressed = false
            this.designer.state.onShiftReleased()
        }
    }

    hotkeyPressed (e) {
        if (this.ctrlPressed(e)) {
            return ACTIONS_HOTKEYS['META+' + e.key.toUpperCase()]
        } else if (!this.modifierPressed(e)) {
            return TOOLS_HOTKEYS[e.key.toLowerCase()]
        }
    }

    enterPressed (e) {
        return e.keyCode === KEYS.ENTER
    }

    ctrlPressed (e) {
        return (seatsio.isMac && e.metaKey) || (!seatsio.isMac && e.ctrlKey)
    }

    shiftPressed (e) {
        return e.shiftKey
    }

    altPressed (e) {
        return e.altKey
    }

    isSpacebar (e) {
        return e.key === ' '
    }

    modifierPressed (e) {
        return this.ctrlPressed(e) || this.shiftPressed(e) || this.altPressed(e)
    }

    arrowPressed (e) {
        return this.upPressed(e) || this.downPressed(e) || this.leftPressed(e) || this.rightPressed(e)
    }

    upPressed (e) {
        return e.keyCode === KEYS.UP
    }

    downPressed (e) {
        return e.keyCode === KEYS.DOWN
    }

    leftPressed (e) {
        return e.keyCode === KEYS.LEFT
    }

    rightPressed (e) {
        return e.keyCode === KEYS.RIGHT
    }

    duplicatePressed (e) {
        return this.ctrlPressed(e) && e.key.toLowerCase() === 'j'
    }

    deletePressed (e) {
        return e.keyCode === KEYS.DEL || e.keyCode === KEYS.BACKSPACE
    }

    exitSectionPressed (e) {
        return this.ctrlPressed(e) && this.escapePressed(e)
    }

    deselectPressed (e) {
        return this.ctrlPressed(e) && e.key.toLowerCase() === 'd'
    }

    toggleReferenceChartPressed (e) {
        return this.ctrlPressed(e) && e.key.toLowerCase() === 'e'
    }

    toggleReferenceChartShowAbovePressed (e) {
        return !this.modifierPressed(e) && e.key && e.key.toLowerCase() === 'w'
    }

    escapePressed (e) {
        return e.keyCode === KEYS.ESCAPE
    }

    floorPressed (e) {
        return this.ctrlPressed(e) && this.altPressed(e) && e.keyCode >= KEYS.NUM_1 && e.keyCode <= KEYS.NUM_9
    }

    undoCombinationPressed (e) {
        return this.ctrlPressed(e) && e.keyCode === KEYS.Z && !this.shiftPressed(e)
    }

    redoCombinationPressed (e) {
        return (this.ctrlPressed(e) && e.keyCode === KEYS.Z && this.shiftPressed(e)) || (this.ctrlPressed(e) && e.keyCode === KEYS.Y)
    }

    cutCombinationPressed (e) {
        return (this.ctrlPressed(e) && e.keyCode === KEYS.X)
    }

    copyCombinationPressed (e) {
        return (this.ctrlPressed(e) && e.keyCode === KEYS.C)
    }

    pasteCombinationPressed (e) {
        return (this.ctrlPressed(e) && e.keyCode === KEYS.V)
    }

    pageUpPressed (e) {
        return e.keyCode === KEYS.PAGE_UP
    }

    pageDownPressed (e) {
        return e.keyCode === KEYS.PAGE_DOWN
    }

    homePressed (e) {
        return e.keyCode === KEYS.HOME
    }

    endPressed (e) {
        return e.keyCode === KEYS.END
    }

    modifierChanged (e) {
        return this.designer.ctrlWasPressed !== this.ctrlPressed(e) || this.designer.shiftWasPressed !== this.shiftPressed(e) || this.designer.altWasPressed !== this.altPressed(e)
    }
}

const KEYS = {
    BACKSPACE: 8,
    DEL: 46,
    Z: 90,
    Y: 89,
    C: 67,
    V: 86,
    X: 88,
    SHIFT: 16,
    ENTER: 13,
    ESCAPE: 27,
    LEFT: 37,
    UP: 38,
    RIGHT: 39,
    DOWN: 40,
    NUM_1: 49,
    NUM_9: 57,
    PAGE_UP: 33,
    PAGE_DOWN: 34,
    END: 35,
    HOME: 36
}

const TOOLS_HOTKEYS = {
    v: { toolName: 'select-cursor', uiEvent: 'toolSelectCursor' },
    c: { toolName: 'select-brush', uiEvent: 'toolSelectBrush' },
    x: { toolName: 'select-seats', uiEvent: 'toolSelectSeats' },
    z: { toolName: 'select-sameType', uiEvent: 'toolSelectSameType' },
    a: { toolName: 'node', uiEvent: 'toolNode' },
    f: { toolName: 'focalpoint', uiEvent: 'toolFocalPoint' },
    s: { toolName: 'section', uiEvent: 'toolSection' },
    r: { toolName: 'row', uiEvent: 'toolRow' },
    e: { toolName: 'table', uiEvent: 'toolTable' },
    b: { toolName: 'booth', uiEvent: 'toolBooth' },
    o: { toolName: 'icon', uiEvent: 'toolIcon' },
    g: { toolName: 'ga', uiEvent: 'toolGa' },
    h: { toolName: 'shape', uiEvent: 'toolShape' },
    l: { toolName: 'line', uiEvent: 'toolLine' },
    t: { toolName: 'text', uiEvent: 'toolText' },
    i: { toolName: 'image', uiEvent: 'toolImageObject' },
    ' ': { toolName: 'hand' }
}

const ALT_KEY = seatsio.isMac ? '⌥' : 'Alt'
const META_KEY = seatsio.isMac ? '⌘' : 'Ctrl'
const SHIFT_KEY = seatsio.isMac ? '⇧' : 'Shift'
const BACKSPACE_KEY = seatsio.isMac ? 'delete' : 'Backspace'
const SHORTCUT_CONNECTOR = seatsio.isMac ? '' : '+'

function buildShortcut (shortcuts) {
    return shortcuts.nonFalsies().join(SHORTCUT_CONNECTOR)
}

seatsio.JsonWithType = class JsonWithDeserializer {
    constructor (json, typeName) {
        this.json = json
        this.typeName = typeName
    }
}

seatsio.Clipboard = class Clipboard {
    constructor (designer) {
        this.designer = designer
        this.deserializers = {
            'section': seatsio.Section.fromJson,
            'ga': seatsio.GeneralAdmissionArea.fromJson,
            'row': seatsio.Row.createFromModel,
            'booth': seatsio.Booth.fromJson,
            'shapedObject': seatsio.ShapedObject.fromJson,
            'imageObject': seatsio.ImageObject.fromJson,
            'textInput': seatsio.TextInput.fromJson,
            'rectangularTable': seatsio.RectTable.fromJson,
            'roundTable': seatsio.RoundTable.fromJson,
            'icon': seatsio.Icon.fromJson
        }
    }

    copy (data) {
        this.store(data
            .map(o => o.flash())
            .filter(o => 'getObjectTypeName' in o)
            .map(o => new seatsio.JsonWithType(o.toJson(), o.getObjectTypeName())))
        this.designer.renderUI()
    }

    paste () {
        const subChart = this.designer.activeSubChart()
        const data = this.retrieve()
        const objects = data.map(o => {
            const deserialize = this.deserializers[o.typeName]
            return deserialize(o.json, subChart)
        })

        const unsupportedObjectTypes = subChart.listUnsupportedObjectTypes(objects)
        if (unsupportedObjectTypes.length > 0) {
            this.flashWarning(unsupportedObjectTypes)
            return
        }

        if (objects.some(object => !this.designer.zones.canPlaceObject(object))) {
            this.designer.flashOverlayMessage('paste-failed-no-zone', 'warning')
            return
        }

        const duplicates = objects.map(o => o.duplicate(subChart))
        this.drawInCenterOfViewport(duplicates)
        this.designer.updateStats()
        duplicates.forEach(o => o.redraw())
        this.designer.setState(new seatsio.ObjectsSelectedState(this.designer, duplicates))
    }

    flashWarning (unsupportedObjectTypes) {
        if (unsupportedObjectTypes.length === 1) {
            this.designer.flashOverlayMessage('paste-failed-single', 'warning', {
                'unsupportedObjectType': d(unsupportedObjectTypes[0]).toLowerCase(),
                'where': d(this.where())
            })
        } else {
            this.designer.flashOverlayMessage('paste-failed', 'warning', {
                'unsupportedObjectTypes': unsupportedObjectTypes.map(t => d(t).toLowerCase()).join(', '),
                'where': d(this.where())
            })
        }
    }

    where () {
        if (!this.designer.getVenueSettings().supportsSections) {
            return 'onChartWithoutSections'
        }
        if (this.designer.activeSubChart().isMasterSubChart()) {
            return 'outsideSection'
        }
        return 'insideSection'
    }

    store (toStore) {
        this.designer.storage.setItem('clipboard', toStore)
    }

    retrieve () {
        return this.designer.storage.getItem('clipboard')
    }

    drawInCenterOfViewport (duplicates) {
        let centerPoint = this.designer.pointInCanvasCenteredInViewport().fromView(this.designer)
        let toMoveVector = centerPoint.subtract(seatsio.Bbox.mergedFromObjects(duplicates).center())
        duplicates.forEach(o => {
            return o.draw().moved(toMoveVector)
        })
    }

    isEmpty () {
        let data = this.retrieve()
        if (!data) {
            return true
        } else {
            return data.length === 0
        }
    }
}

class SortedArray extends Array {
    constructor (comparator) {
        super()
        this.comparator = comparator
    }

    insert (el) {
        let left = 0
        let right = this.length

        while (true) {
            if (left === right) {
                this.splice(left, 0, el)
                return left
            }

            let mid = Math.floor((right + left) / 2)

            let comparisonResult = this.comparator(el, this[mid])
            if (comparisonResult < 0) {
                right = mid
            } else {
                left = mid + 1
            }
        }
    }
}

class SvgElementSet {
    constructor (items) {
        if (items) {
            this._setItems(SvgElementSet.flatten(items))
        } else {
            this._setItems([])
        }
    }

    push (...items) {
        this._setItems([
            ...this.items,
            ...items.nonFalsies()
        ])
        return this
    }

    forEach (f) {
        this.items.forEach(f)
        return this
    }

    attr (name, value) {
        this.forEach(item => item.attr(name, value))
        return this
    }

    clear () {
        this._setItems([])
        return this
    }

    startTransformation () {
        this.forEach(function (el) {
            el.transformationAtStart = el.matrix()
        })
        return this
    }

    transform (transformation) {
        this.forEach(function (el) {
            el.transform(transformation.multiply(el.transformationAtStart))
        })
        return this
    }

    endTransformation () {
        this.forEach(function (el) {
            el.transformationAtStart = undefined
        })
        return this
    }

    toLayer (layerName, designer) {
        this.forEach(function (el) {
            el.toLayer(layerName, designer)
        })
        return this
    }

    applyZoom (designer) {
        this.forEach(function (el) {
            el.applyZoom(designer)
        })
        return this
    }

    hide () {
        this.forEach(function (el) {
            el.hide()
        })
        return this
    }

    show () {
        this.forEach(function (el) {
            el.show()
        })
        return this
    }

    remove () {
        this.forEach(function (el) {
            el.remove()
        })
        return this.clear()
    }

    stop () {
        this.forEach(function (el) {
            el.stop()
        })
        return this
    }

    translate (x, y) {
        this.forEach(function (el) {
            let translationMatrix = new SVG.Matrix().translate(x, y).transform(el.matrix())
            el.transform(translationMatrix)
        })
        return this
    }

    zoomAndRotateTo (rotationAngle, designer, zoomLevel, center) {
        this.forEach(function (el) {
            el.zoomAndRotateTo(rotationAngle, designer, zoomLevel, center)
        })
        return this
    }

    disablePointerEvents () {
        this.forEach(function (el) {
            el.disablePointerEvents()
        })
        return this
    }

    last () {
        return this.items[this.items.length - 1]
    }

    toArray () {
        return [...this.items]
    }

    _setItems (items) {
        this.items = items
        this.length = items.length
    }

    static flatten (items) {
        return items
            .flatMap(item => {
                if (item && item.forEach) {
                    return item
                }
                return [item]
            })
            .nonFalsies()
    }
}

seatsio.ButtonGroup = function () {
    this.buttons = []
}

seatsio.ButtonGroup.prototype.withOptionalButton = function (button) {
    if (button) {
        this.buttons.push(button)
    }
    return this
}

seatsio.ButtonGroup.prototype.render = function () {
    if (this.buttons.length === 0) {
        return null
    }
    if (this.buttons.length === 1) {
        return this.buttons[0].renderAsSingleButton()
    }
    return this.renderButtonGroup(this.buttons)
}

seatsio.ButtonGroup.prototype.renderButtonGroup = function (buttons) {
    return $('<div class="btn-group dropup">')
        .append(buttons[0].renderAsSingleButton())
        .append(this.createCaret())
        .append(this.createDropdownMenu(buttons.slice(1)))
}

seatsio.ButtonGroup.prototype.createDropdownMenu = function (buttons) {
    var me = this
    var dropdownMenu = $('<ul class="dropdown-menu pull-right">')
    buttons.forEach(function (button) {
        var buttonLink = $('<a href="#">')
            .html(button.iconWithText())
            .on('click', preventDefault(button.onClick))
        dropdownMenu.append($('<li>').append(buttonLink))
    })
    return dropdownMenu
}

seatsio.ButtonGroup.prototype.createCaret = function () {
    return $('<button class="btn btn-lg btn-default dropdown-toggle" data-toggle="dropdown">')
        .append('<span class="caret">')
}

seatsio.ButtonGroupButton = function (label, icon, onClick, redrawer) {
    this.label = label
    this.icon = icon || 'fa'
    this.onClick = onClick
    this.redrawer = redrawer
    this.asyncClickInProgress = false
}

seatsio.ButtonGroupButton.prototype.renderAsSingleButton = function () {
    return this.asyncClickInProgress ? this.renderWithSpinner() : this.renderWithoutSpinner()
}

seatsio.ButtonGroupButton.prototype.renderWithSpinner = function () {
    return $('<button type="button" class="btn btn-lg btn-default">')
        .html($('<img>').attr('src', 'ajax-loader.gif'))
        .attr('disabled', 'disabled')
}

seatsio.ButtonGroupButton.prototype.iconWithText = function () {
    return $('<span>')
        .append($('<i>').addClass(this.icon))
        .append('&nbsp;&nbsp;' + this.label)
}

seatsio.ButtonGroupButton.prototype.renderWithoutSpinner = function () {
    var me = this
    return $('<button type="button" class="btn btn-lg btn-default">')
        .html(me.iconWithText())
        .on('click', function (e) {
            e.preventDefault()
            var clickDeferred = me.onClick()
            if (clickDeferred) {
                me.setAsyncClickInProgress(true)
                clickDeferred.always(function () {
                    me.setAsyncClickInProgress(false)
                })
            }
        })
}

seatsio.ButtonGroupButton.prototype.setAsyncClickInProgress = function (asyncClickInProgress) {
    this.asyncClickInProgress = asyncClickInProgress
    this.redrawer()
}

seatsio.Bbox = class Bbox {
    constructor (origin, width, height) {
        this.origin = origin
        this.width = width
        this.height = height
    }

    static fromRBox (rbox) {
        return new seatsio.Bbox(new seatsio.Point(rbox.x, rbox.y), rbox.width, rbox.height)
    }

    static fromOriginAndDimensions (origin, width, height) {
        return new seatsio.Bbox(origin, width, height)
    }

    static fromTopLeftAndLowerRight (origin, lowerRight) {
        var width = lowerRight.x - origin.x
        var height = lowerRight.y - origin.y
        return new seatsio.Bbox(origin, width, height)
    }

    static mergedFromObjects (objects) {
        var bboxes = objects.map(function (object) {
            return object.bbox()
        })
        return seatsio.Bbox.merged(bboxes)
    }

    static mergedFromObjectsSelectionIndicator (objects) {
        if (objects.length === 0) {
            return new seatsio.Bbox(new seatsio.Point(0, 0), 0, 0)
        }

        let points = objects.flatMap(object => {
            if (object.type === 'row') {
                return object.bboxForSelection().toPoints()
            }
            return object.selectionIndicator ? object.selectionIndicator().toPoints() : object.bbox().toPoints()
        })
        let minX = points.map(seatsio.Point.x).reduce(seatsio.PolygonShape.min)
        let minY = points.map(seatsio.Point.y).reduce(seatsio.PolygonShape.min)
        let maxX = points.map(seatsio.Point.x).reduce(seatsio.PolygonShape.max)
        let maxY = points.map(seatsio.Point.y).reduce(seatsio.PolygonShape.max)
        return new seatsio.Bbox(new seatsio.Point(minX, minY), maxX - minX, maxY - minY)
    }

    static coreMergedFromObjects (objects) {
        var bboxes = objects.map(function (object) {
            return object.coreBbox()
        })
        return seatsio.Bbox.merged(bboxes)
    }

    static merged (bboxes) {
        return bboxes.reduce(function (totalBbox, bbox) {
            if (bbox === null) {
                return totalBbox
            }
            if (totalBbox === null) {
                return bbox
            }
            return totalBbox.mergeWith(bbox)
        }, null)
    }

    static fromView (bbox, designer) {
        let origin = new seatsio.Point(bbox.x, bbox.y).fromView(designer)
        let width = designer.zoomer.unzoom(bbox.width)
        let height = designer.zoomer.unzoom(bbox.height)
        return new seatsio.Bbox(origin, width, height)
    }

    static toView (bbox, designer) {
        var originInView = bbox.origin.toView(designer)
        var widthInView = designer.zoomer.zoomed(bbox.width)
        var heightInView = designer.zoomer.zoomed(bbox.height)
        return {
            x: originInView.x,
            y: originInView.y,
            x2: originInView.x + widthInView,
            y2: originInView.y + heightInView,
            width: widthInView,
            height: heightInView
        }
    }

    static drawPathThroughPoints (bbox, designer) {
        var path = 'M' + bbox.origin.x + ',' + bbox.origin.y + 'L' + bbox.topRight().x + ',' + bbox.topRight().y + ',' + bbox.bottomRight().x + ',' + bbox.bottomRight().y + ',' + bbox.bottomLeft().x + ',' + bbox.bottomLeft().y + ',' + bbox.origin.x + ',' + bbox.origin.y
        return designer.drawer.path(path).applyZoom(designer)
    }

    static drawRectangle (bbox, designer) {
        return designer.drawRectangle(bbox.origin.x, bbox.origin.y, bbox.bottomRight().x, bbox.bottomRight().y).applyZoom(designer)
    }

    center () {
        return this.middleLeft().averageWith(this.middleRight())
    }

    topLeft () {
        return this.origin
    }

    topMiddle () {
        return this.origin.averageWith(this.topRight())
    }

    topRight () {
        return this.origin.addToX(this.width)
    }

    bottomLeft () {
        return this.origin.addToY(this.height)
    }

    bottomMiddle () {
        return this.bottomLeft().averageWith(this.bottomRight())
    }

    bottomRight () {
        return this.origin.addToX(this.width).addToY(this.height)
    }

    middleLeft () {
        return this.origin.averageWith(this.bottomLeft())
    }

    middleMiddle () {
        return this.center()
    }

    middleRight () {
        return this.topRight().averageWith(this.bottomRight())
    }

    isEmpty () {
        return this.width === 0 || this.height === 0
    }

    mergeWith (bbox) {
        if (!bbox) {
            return this
        }
        var origin = new seatsio.Point(
            Math.min(bbox.origin.x, this.origin.x),
            Math.min(bbox.origin.y, this.origin.y)
        )
        var lowerRight = new seatsio.Point(
            Math.max(bbox.bottomRight().x, this.bottomRight().x),
            Math.max(bbox.bottomRight().y, this.bottomRight().y)
        )
        return seatsio.Bbox.fromTopLeftAndLowerRight(origin, lowerRight)
    }

    round () {
        return new seatsio.Bbox(this.origin.floor(), Math.ceil(this.width), Math.ceil(this.height))
    }

    enlarge (amount) {
        return seatsio.Bbox.fromTopLeftAndLowerRight(this.topLeft().addToXAndY(-amount), this.bottomRight().addToXAndY(amount))
    }

    enlargedByXY (amountX, amountY) {
        amountX /= 2
        amountY /= 2
        return seatsio.Bbox.fromTopLeftAndLowerRight(this.topLeft().add(new seatsio.Point(-amountX, -amountY)), this.bottomRight().add(new seatsio.Point(amountX, amountY)))
    }

    diagonalLength () {
        return this.topLeft().distanceToPoint(this.bottomRight())
    }

    toPoints () {
        return [this.topLeft(), this.topRight(), this.bottomRight(), this.bottomLeft()]
    }

    toRays () {
        return [
            new seatsio.Ray(this.topLeft(), this.topRight()),
            new seatsio.Ray(this.topRight(), this.bottomRight()),
            new seatsio.Ray(this.bottomRight(), this.bottomLeft()),
            new seatsio.Ray(this.bottomLeft(), this.topLeft())
        ]
    }

    toPolygon () {
        return new seatsio.PolygonShape(this.toPoints())
    }

    containsPoint (point) {
        return numberInRange(point.x, this.origin.x, this.origin.x + this.width) && numberInRange(point.y, this.origin.y, this.origin.y + this.height)
    }

    containsBbox (bbox) {
        return bbox.toPoints().every(point => this.containsPoint(point))
    }

    toViewRbox (designer) {
        return seatsio.Bbox.toView(this, designer)
    }

    toViewBbox (designer) {
        return seatsio.Bbox.fromRBox(this.toViewRbox(designer))
    }
}

seatsio.ItemSelector = function (designer) {
    this.designer = designer
    this.selectionRectangle = null
    this.selectedObjects = []
}

seatsio.ItemSelector.prototype.startSelection = function (startpoint, validator) {
    this.startpoint = startpoint
    this.validator = validator
}

seatsio.ItemSelector.prototype.paintSelected = seatsio.ObjectsSelector.prototype.paintSelected
seatsio.ItemSelector.prototype.paintUnselected = seatsio.ObjectsSelector.prototype.paintUnselected

seatsio.ItemSelector.prototype.selectMultipleObjects = function (endpoint) {
    if (this.selectionRectangle) {
        this.selectionRectangle.remove()
    }
    this.selectionRectangle = this.designer
        .drawRectangle(this.startpoint.x, this.startpoint.y, endpoint.x, endpoint.y)
        .applyZoom(this.designer)
        .attr({
            'fill': 'rgba(50, 50, 50, 0.16)',
            'stroke': 'white',
            'stroke-width': this.designer.zoomer.unzoom(0.75)
        })
    this.selectedObjects = []
    this.doSelection(this.designer.activeSubChart().categorisableObjects())
    this.designer.setSelectedSubobjectsCount(this.selectedObjects.length)
}

seatsio.ItemSelector.prototype.inBbox = function (object, selectionRBox) {
    return isRBoxIntersect(object.bbox().toViewRbox(this.designer), selectionRBox)
}

seatsio.ItemSelector.prototype.doSelection = function (items) {
    const selectionRBox = this.selectionRectangle.rbox()
    items.forEach(item => {
        const isEnclosedBySelection = this.inBbox(item, selectionRBox)
        if (isEnclosedBySelection && (!this.validator || this.validator(item))) {
            this.selectedObjects.push(item)
            item.paintSelected()
        } else {
            item.paintUnselected()
        }
    })
}

seatsio.ItemSelector.prototype.hasSelectedObjects = function () {
    return this.selectedObjects.length > 0
}

seatsio.ItemSelector.prototype.deselectObjects = function () {
    this.paintUnselected(this.selectedObjects)
    this.selectedObjects = []
}

seatsio.ItemSelector.prototype.stopSelecting = function () {
    this.deselectObjects()
    if (this.selectionRectangle) this.selectionRectangle.remove()
    this.designer.clearSelectedCount()
}

seatsio.BackgroundImage = function (subChart) {
    this.subChart = subChart
    this.designer = subChart.designer
    this.backgroundImage = null
    this.opacity = 1
    this.backgroundImageWidth = null
    this.backgroundImageHeight = null
    this.backgroundImageUrl = null
    this.backgroundImageKey = null
    this.backgroundFileSize = null
    this.backgroundFileType = null
    this.origin = null
    this.backgroundImageScale = seatsio.BackgroundImage.DEFAULT_SCALE
    this.showOnRenderedCharts = true
}

seatsio.BackgroundImage.prototype.width = function () {
    return this.backgroundImageWidth
}

seatsio.BackgroundImage.prototype.height = function () {
    return this.backgroundImageHeight
}

seatsio.BackgroundImage.prototype.getBackgroundImage = function () {
    return this.backgroundImage
}

seatsio.BackgroundImage.prototype.displaySectionOverlay = function () {
    return false
}

seatsio.BackgroundImage.prototype.hideLabels = function () {
}

seatsio.BackgroundImage.prototype.showLabels = function () {
}

seatsio.BackgroundImage.prototype.showLabelAndChildLabels = function () {
}

seatsio.BackgroundImage.prototype.hideLabelAndChildLabels = function () {
}

seatsio.BackgroundImage.prototype.determineBackgroundImageLayer = function () {
    return 'backgroundFillLayer'
}

seatsio.BackgroundImage.prototype.determineOpacity = function () {
    return this.opacity
}

seatsio.BackgroundImage.prototype.determineBackgroundImageOpacity = function () {
    return this.determineOpacity() * (this.displaySectionOverlay() ? 4 / 5 : 1)
}

seatsio.BackgroundImage.prototype.determineOverlayBackgroundImageOpacity = function () {
    return this.determineOpacity() * (this.displaySectionOverlay() ? 1 / 5 : 1)
}

seatsio.BackgroundImage.prototype.draw = function () {
    if (!this.url() || !this.origin) {
        return
    }
    if (!this.subChart.isActive()) {
        return
    }
    this.backgroundImage = this.designer.drawer.image(this.url(), this.backgroundImageWidth, this.backgroundImageHeight,
        {
            x: this.origin.x,
            y: this.origin.y,
            'opacity': this.determineBackgroundImageOpacity()
        })
        .setExtraZoom(this.backgroundImageScale / 100)
        .toLayer(this.determineBackgroundImageLayer(), this.designer)
        .applyZoom(this.designer)
    if (this.displaySectionOverlay()) {
        this.overlayBackgroundImage = this.designer.drawer.image(this.url(), this.backgroundImageWidth, this.backgroundImageHeight,
            {
                x: this.origin.x,
                y: this.origin.y,
                'opacity': this.determineOverlayBackgroundImageOpacity()
            })
            .setExtraZoom(this.backgroundImageScale / 100)
            .toLayer('overlayBackgroundLayer', this.designer)
            .applyZoom(this.designer)
    }
}

seatsio.BackgroundImage.prototype.isSet = function () {
    return this.backgroundImageUrl || this.backgroundImageKey
}

seatsio.BackgroundImage.prototype.url = function () {
    if (this.backgroundImageUrl) {
        return this.backgroundImageUrl
    }
    if (this.backgroundImageKey) {
        return this.designer.publicApiUrl + '/system/public/charts/images/' + this.backgroundImageKey
    }
    return null
}

seatsio.BackgroundImage.prototype.undraw = function () {
    if (this.backgroundImage) {
        this.backgroundImage.remove()
        this.backgroundImage = null
    }
    if (this.overlayBackgroundImage) {
        this.overlayBackgroundImage.remove()
        this.overlayBackgroundImage = null
    }
}

seatsio.BackgroundImage.prototype.blur = function () {
}

seatsio.BackgroundImage.prototype.unblur = function () {
}

seatsio.BackgroundImage.prototype.toJson = function () {
    if (!this.url() || !this.origin) {
        return null
    }
    return {
        'backgroundImageUrl': this.backgroundImageUrl,
        'backgroundImageKey': this.backgroundImageKey,
        'backgroundFileSize': this.fileSize(),
        'backgroundFileType': this.backgroundFileType,
        'backgroundImageZoom': this.backgroundImageScale,
        'opacity': this.opacity,
        'showOnRenderedCharts': this.showOnRenderedCharts,
        'origin': this.origin.toJson(this.subChart),
        'backgroundImageWidth': this.backgroundImageWidth,
        'backgroundImageHeight': this.backgroundImageHeight
    }
}

seatsio.BackgroundImage.prototype.removeBackgroundImage = function () {
    if (this.backgroundImage) {
        this.backgroundImage.remove()
    }
    this.backgroundImage = null
    if (this.overlayBackgroundImage) {
        this.overlayBackgroundImage.remove()
    }
    this.overlayBackgroundImage = null
    this.origin = null
    this.backgroundImageHeight = null
    this.backgroundImageWidth = null
    this.backgroundImageUrl = null
    this.backgroundImageKey = null
    this.backgroundFileSize = null
    this.backgroundFileType = null
    this.backgroundImageScale = seatsio.BackgroundImage.DEFAULT_SCALE
    this.showOnRenderedCharts = true
    this.designer.requestStatsUpdate()
    this.designer.renderUI()
}

seatsio.BackgroundImage.prototype.setBackgroundImage = function (backgroundImageKey) {
    if (backgroundImageKey === this.backgroundImageKey) {
        return this
    }
    this.removeBackgroundImage()
    if (backgroundImageKey) {
        this.backgroundImageKey = backgroundImageKey
        this.loadBackgroundImage(() => this.designer.renderUI())
    }
    return this
}

seatsio.BackgroundImage.prototype.setBackgroundFileSizeAndType = function (size, type) {
    this.backgroundFileSize = size
    this.backgroundFileType = type
    return this
}

seatsio.BackgroundImage.prototype.fileSize = function () {
    return this.backgroundFileSize || 0
}

seatsio.BackgroundImage.prototype.loadBackgroundImage = function (successCallback) {
    const busyIndicator = 'chartBackgroundImage'
    this.designer.busyIndicatorOn(busyIndicator, true)
    var image = new Image()
    image.src = this.url()
    image.onload = seatsio.BackgroundImage.onLoad.bind(image, this, successCallback, busyIndicator, this.subChart)
    image.onerror = seatsio.BackgroundImage.onError.bind(image, this, busyIndicator)
}

seatsio.BackgroundImage.onLoad = function (backgroundImage, successCallback, busyIndicator, subChart) {
    backgroundImage.backgroundImageWidth = this.width
    backgroundImage.backgroundImageHeight = this.height

    if (!backgroundImage.origin) {
        backgroundImage.origin = backgroundImage.designer.canvasCenter
            .addToX(-1 * backgroundImage.backgroundImageWidth / 2)
            .addToY(-1 * backgroundImage.backgroundImageHeight / 2)
    }
    if (subChart.isMasterSubChart() && backgroundImage.designer.activeSubChart() === subChart) {
        backgroundImage.redraw()
    } else if (subChart.isSectionSubChart() && backgroundImage.designer.activeSubChart() === subChart) {
        subChart.backgroundImageForSection.redraw()
        subChart.referenceChart.redraw()
    }
    if (successCallback) {
        successCallback()
    }
    backgroundImage.designer.busyIndicatorOff(busyIndicator)
}

seatsio.BackgroundImage.onError = function (backgroundImage, busyIndicator) {
    alert(d('image-load-error'))
    backgroundImage.designer.busyIndicatorOff(busyIndicator)
}

seatsio.BackgroundImage.prototype.setScale = function (scale) {
    this.backgroundImageScale = scale
    this.redraw()
    this.designer.renderUI()
}

seatsio.BackgroundImage.prototype.applyZoom = function () {
    if (this.backgroundImage) {
        this.backgroundImage.applyZoom(this.designer)
    }
    if (this.overlayBackgroundImage) {
        this.overlayBackgroundImage.applyZoom(this.designer)
    }
}

seatsio.BackgroundImage.prototype.redraw = function () {
    this.undraw()
    this.draw()
}

seatsio.BackgroundImage.prototype.setOpacity = function (number) {
    if (this.getBackgroundImage()) {
        this.opacity = number
        this.backgroundImage.attr({ 'opacity': this.determineBackgroundImageOpacity() })
        if (this.overlayBackgroundImage) this.overlayBackgroundImage.attr({ 'opacity': this.determineBackgroundImageOpacity() * 1 / 5 })
    }
}

seatsio.BackgroundImage.prototype.setShowOnRenderedCharts = function (showOnRenderedCharts) {
    this.showOnRenderedCharts = showOnRenderedCharts
    if (showOnRenderedCharts) {
        this.setOpacity(1)
    } else {
        this.setOpacity(seatsio.BackgroundImage.OPACITY_WHEN_NOT_SHOWN_ON_RENDERED_CHART)
    }
    this.designer.renderUI()
}

seatsio.BackgroundImage.prototype.bbox = function () {
    if (!this.origin) {
        return new seatsio.RectangleShape(this.designer.canvasCenter, 0, 0).bbox()
    }
    var scaleFactor = this.backgroundImageScale / 100
    var width = this.backgroundImageWidth * scaleFactor
    var height = this.backgroundImageHeight * scaleFactor
    var center = this.origin.addToX(this.backgroundImageWidth / 2).addToY(this.backgroundImageHeight / 2)
    return new seatsio.RectangleShape(center, width, height).bbox()
}

seatsio.BackgroundImage.prototype.scaleImmediately = seatsio.Object.prototype.scaleImmediately

seatsio.BackgroundImage.prototype.doScale = function (factor, center) {
    if (this.isSet()) {
        this.backgroundImageScale = Math.round(this.stateBeforeScaling.backgroundImageScale * factor)
        const backgroundImageCenter = this.stateBeforeScaling.origin.addToX(this.backgroundImageWidth / 2).addToY(this.backgroundImageHeight / 2)
        const scaledBackgroundImageCenter = new seatsio.Ray(center, backgroundImageCenter).enlargeByFactor(factor).end
        this.origin = scaledBackgroundImageCenter.addToX(-this.backgroundImageWidth / 2).addToY(-this.backgroundImageHeight / 2)
        this.redraw()
    }
}

seatsio.BackgroundImage.fromJson = function (json, subChart) {
    var backgroundImage = new seatsio.BackgroundImage(subChart)
    if (json && (json.backgroundImageUrl || json.backgroundImageKey)) {
        this.setFromJson(backgroundImage, json, subChart)
    }
    return backgroundImage
}

seatsio.BackgroundImage.setFromJson = function (backgroundImage, json, subChart) {
    backgroundImage.backgroundImageScale = json.backgroundImageZoom
    if (json.origin) {
        backgroundImage.origin = seatsio.Point.fromJson(json.origin, subChart)
    }
    backgroundImage.backgroundImageUrl = json.backgroundImageUrl
    backgroundImage.backgroundImageKey = json.backgroundImageKey
    backgroundImage.backgroundFileSize = json.backgroundFileSize
    backgroundImage.backgroundFileType = json.backgroundFileType
    backgroundImage.opacity = json.opacity
    backgroundImage.showOnRenderedCharts = json.showOnRenderedCharts
    backgroundImage.backgroundImageWidth = json.backgroundImageWidth
    backgroundImage.backgroundImageHeight = json.backgroundImageHeight
    backgroundImage.loadBackgroundImage()
}

seatsio.BackgroundImage.DEFAULT_SCALE = 100
seatsio.BackgroundImage.OPACITY_WHEN_NOT_SHOWN_ON_RENDERED_CHART = 0.25

seatsio.ReferenceChart = class ReferenceChart extends seatsio.BackgroundImage {
    constructor (subChart) {
        super(subChart)
        this.visible = true
        this.opacity = seatsio.ReferenceChart.OPACITY
    }

    displaySectionOverlay () {
        return false
    }

    determineBackgroundImageLayer () {
        return this.designer.showReferenceChartAbove ? 'aboveAllBackgroundLayer' : 'backgroundLayer'
    }

    determineOpacity () {
        if (this.designer.showReferenceChartAbove) {
            return 0.9
        }
        if (!this.designer.referenceChartVisible) {
            return 0
        }
        return seatsio.ReferenceChart.OPACITY
    }

    removeBackgroundImage () {
        this.visible = true
        return super.removeBackgroundImage()
    }

    setScale (scale) {
        super.setScale(scale)
        this.designer.renderUI()
        return this
    }

    setBackgroundImage (backgroundImageKey) {
        if (backgroundImageKey !== this.backgroundImageKey) {
            this.openDialogWhenDone = true
        }
        return super.setBackgroundImage(backgroundImageKey)
    }

    loadBackgroundImage (successCallback) {
        const busyIndicator = 'referenceChartImage'
        this.designer.busyIndicatorOn(busyIndicator)
        var image = new Image()
        image.src = this.url()
        image.onload = seatsio.ReferenceChart.onLoad.bind(image, this, successCallback, busyIndicator, this.subChart)
        image.onerror = seatsio.BackgroundImage.onError.bind(image, this, busyIndicator)
    }

    static onLoad (referenceChart, successCallback, busyIndicator, subChart) {
        super.onLoad(referenceChart, successCallback, busyIndicator, subChart)
        if (referenceChart.openDialogWhenDone) {
            referenceChart.designer.uiEvents.openReferenceChartDialogAfterUploadingReferenceChart()
            referenceChart.openDialogWhenDone = false
        }
    }

    static onError (referenceChart, busyIndicator) {
        super.onError(referenceChart, busyIndicator)
        referenceChart.openDialogWhenDone = false
    }

    imageMask () {
        return undefined
    }

    toJson () {
        if (!this.url() || !this.origin) {
            return null
        }
        return {
            'backgroundImageUrl': this.backgroundImageUrl,
            'backgroundImageKey': this.backgroundImageKey,
            'backgroundFileSize': this.fileSize(),
            'backgroundFileType': this.backgroundFileType,
            'backgroundImageZoom': this.backgroundImageScale,
            'opacity': seatsio.ReferenceChart.OPACITY,
            'origin': this.origin.toJson(this.subChart)
        }
    }

    static fromJson (json, subChart) {
        var referenceChart = new seatsio.ReferenceChart(subChart)
        if (json && (json.backgroundImageUrl || json.backgroundImageKey)) {
            this.setFromJson(referenceChart, json, subChart)
        }
        return referenceChart
    }
}

seatsio.ReferenceChart.OPACITY = 0.8
seatsio.ReferenceChart.MAX_UPLOAD_FILESIZE_MB = 15

seatsio.Saver = function (chartDesigner) {
    this.chartDesigner = chartDesigner
    this.deflater = this.createDeflater()
    this.deferred = null
}

seatsio.Saver.prototype.createDeflater = function () {
    function errorType (response) {
        let responseJson = response.responseJSON
        if (responseJson) {
            let errors = responseJson.errors
            if (errors && errors.length > 0 && errors[0].code === 'DRAWING_VALIDATION_FAILED') {
                return 'SAVE_FAILED_VALIDATION_ERROR'
            }
        }
        return 'SAVE_FAILED_UNKNOWN_ERROR'
    }

    var me = this
    var deflater = new Worker('./js/deflater/deflater.js')
    deflater.onmessage = function (e) {
        console.log(e.data);
        // me.chartDesigner.v2Client
        //     .saveChart(me.chartDesigner.chartKey, e.data)
        //     .then(me.saveSuccess.bind(me), response => me.saveError(errorType(response)))
    }
    deflater.onerror = function (error) {
        me.saveError(error.message)
    }
    return deflater
}

seatsio.Saver.prototype.save = function (drawing) {
    // if (this.chartDesigner.isReadOnly()) {
    //     this.chartDesigner.uiEvents.saveRejected()
    //     return
    // }
    console.log(drawing);
    this.showSavingFeedback()
    this.deferred = $.Deferred()
    this.deflater.postMessage(drawing)
    return this.deferred
}

seatsio.Saver.prototype.saveSuccess = function (x, y, response) {
    if (response.status === 201) {
        this.chartDesigner.onChartCreated(this.chartDesigner.chartKey)
    } else {
        this.chartDesigner.onChartUpdated()
    }
    var responseJSON = response.responseJSON
    this.chartDesigner.setStatus(responseJSON.status)
    this.showSaveSuccessfulFeedback()
    this.deferred.resolve()
}

seatsio.Saver.prototype.saveError = function (errorType) {
    this.showSaveFailedFeedback(errorType)
    if (errorType === 'SAVE_FAILED_VALIDATION_ERROR') {
        this.deferred.resolve()
    } else {
        this.deferred.reject()
    }
}

seatsio.Saver.prototype.showSavingFeedback = function () {
    this.chartDesigner.uiEvents.savingStart()
}

seatsio.Saver.prototype.showSaveSuccessfulFeedback = function () {
    this.chartDesigner.uiEvents.saveSuccess(moment())
}

seatsio.Saver.prototype.showSaveFailedFeedback = function (errorType) {
    this.chartDesigner.uiEvents.saveRejected(errorType)
}

seatsio.ObjectSelector = function (object, designer) {
    this.object = object
    this.designer = designer
    this.selectionRectangles = []
    this.selected = false
}

seatsio.ObjectSelector.prototype.objectUndrawn = function () {
    this.undraw()
}

seatsio.ObjectSelector.prototype.undraw = function () {
    this.selectionRectangles.forEach(selectionRectangle => selectionRectangle.remove())
    this.selectionRectangles = []
}

seatsio.ObjectSelector.prototype.enable = function () {
    this.selectionRectangles.forEach(selectionRectangle => selectionRectangle.show())
}

seatsio.ObjectSelector.prototype.disable = function () {
    this.selectionRectangles.forEach(selectionRectangle => selectionRectangle.hide())
}

seatsio.ObjectSelector.prototype.allElementsSet = function () {
    return seatsio.set(this.selectionRectangles)
}

seatsio.ObjectSelector.prototype.changeCursorTo = function (cursor) {
    this.selectionRectangles.forEach(selectionRectangle => selectionRectangle.attr({ cursor }))
}

seatsio.ObjectSelector.prototype.changeCursorToDefault = function () {
    this.selectionRectangles.forEach(selectionRectangle => selectionRectangle.attr({ cursor: null }))
}

seatsio.ObjectSelector.prototype.objectDrawn = function () {
    this.undraw()
    this.selectionRectangles = this.object.createSelectionRectangles()
    this.selectionRectangles.forEach(selectionRectangle => {
        selectionRectangle.toLayer(this.object.layer, this.designer, this.object.determineDrawZIndex())
        selectionRectangle.node.onmousedown = (e) => {
            this.designer.mouseDown = true
            this.designer.getState().onObjectMouseDown(this.object, e)
        }
        selectionRectangle.node.onmouseup = (e) => {
            this.designer.mouseDown = false
            this.designer.getState().onObjectMouseUp(this.object, e)
        }
        selectionRectangle.node.onmouseover = (e) => {
            this.designer.getState().onObjectMouseOver(this.object, e)
        }
        selectionRectangle.node.onmouseout = (e) => {
            if (!this.object.getHUDNodes().includes(e.toElement)) {
                this.designer.getState().onObjectMouseOut(this.object, e)
            }
        }
        selectionRectangle.node.onclick = (e) => {
            e.stopPropagation()
            this.designer.getState().onObjectClicked(this.object, e)
        }
        selectionRectangle.node.ondblclick = e => this.designer.getState().onObjectDoubleClicked(this.object, e)
        selectionRectangle.onDrag(
            this.designer,
            (dx, dy, e) => {
                this.designer.getState().onObjectDragged(this.object, dx, dy, seatsio.Point.fromEvent(e, this.designer))
            },
            (e) => {
                this.designer.getState().onObjectDragStarted(this.object, seatsio.Point.fromEvent(e, this.designer))
            },
            (totalDrag) => {
                this.designer.getState().onObjectDragEnded(this.object, totalDrag)
            }
        )
    })
}

seatsio.ObjectMover = function (object) {
    this.object = object
}

seatsio.ObjectMover.prototype.start = function () {
    if (this.object.designer.labelsShown) {
        this.object.hideLabelAndChildLabels()
    }
    this.object.hideOverlays()
    this.object.hideAllIconLabels()
    this.object.hideHUD()
    this.object.drawPositionGuides()
    this.object.allElementsSet().startTransformation()
}

seatsio.ObjectMover.prototype.move = function (dx, dy) {
    this.object.allElementsSet().transform(seatsio.Vector.fromView(dx, dy, this.object.designer).snapToGrid().asTranslation())
    return this.object
}

seatsio.ObjectMover.prototype.end = function (totalDistance) {
    if (this.object.designer.labelsShown) {
        this.object.showLabelAndChildLabels()
    }
    this.object.showAllIconLabels()
    this.object.moved(totalDistance.snapToGrid())
    this.object.allElementsSet().endTransformation()
    this.object.undrawPositionGuides()
    this.object.restoreOverlays()
    if (!this.object.subChart.isMasterSubChart()) {
        this.object.designer.updateObjectsOutOfBounds()
    }
}

seatsio.ObjectMover.prototype.doMove = function (distance) {
    this.start()
    this.move(distance.x, distance.y)
    this.end(distance)
    return this.object
}

seatsio.SubChart = function () {
}

seatsio.SubChart.prototype.init = function (designer) {
    this.designer = designer
    this.tables = new seatsio.Tables(this)
    this.rows = []
    this.textInputs = []
    this.imageObjects = new seatsio.ImageObjects(this)
    this.bbox = null
    this.shapes = new seatsio.ShapedObjects(this)
    this.booths = new seatsio.Booths(this)
    this.icons = new seatsio.Icons(this)
    this.sections = new seatsio.Sections(this)
    this.generalAdmissionAreas = new seatsio.GeneralAdmissionAreas(this)
    return this
}

seatsio.SubChart.prototype.isMasterSubChart = function () {
    return false
}

seatsio.SubChart.prototype.listUnsupportedObjectTypes = function (objects) {
    return []
}

seatsio.SubChart.prototype.getBBox = function () {
    return this.getContentsBBox()
}

seatsio.SubChart.prototype.getContentsBBox = function () {
    if (!this.bbox) {
        this.computeBbox()
    }
    return this.bbox
}

seatsio.SubChart.prototype.refreshOutOfBounds = function () {
}

seatsio.SubChart.prototype.getMinAndMaxDistance = function (point) {
    var min = null
    var max = null
    this.chairs().forEach(function (chair) {
        var distance = point.distanceToPoint(chair.center())
        if (min === null) {
            min = distance
            max = distance
        } else if (distance < min) {
            min = distance
        } else if (distance > max) {
            max = distance
        }
    })
    return {
        'min': min,
        'max': max
    }
}

seatsio.SubChart.prototype.deleteRow = function (row) {
    this.rows.splice(this.rows.indexOf(row), 1)
    row.undraw()
    this.designer.requestStatsUpdate()
}

seatsio.SubChart.prototype.addRow = function (row) {
    row.published = false
    return this.loadRow(row)
}

seatsio.SubChart.prototype.loadRow = function (row) {
    this.rows.push(row)
    row.refreshOutOfBounds()
    this.designer.requestStatsUpdate()
    return row
}

seatsio.SubChart.prototype.addTextInput = function (textInput) {
    this.textInputs.push(textInput)
    this.designer.requestStatsUpdate()
    return textInput
}

seatsio.SubChart.prototype.removeTextInput = function (textInput) {
    textInput.undraw()
    this.textInputs.remove(textInput)
    this.designer.requestStatsUpdate()
}

seatsio.SubChart.prototype.isEmpty = function () {
    return this.allSelectableObjects().length === 0
}

seatsio.SubChart.prototype.allSelectableObjects = function () {
    return this.allSelectableObjectsExceptSections()
        .concat(this.sections.sections)
}

seatsio.SubChart.prototype.GAsAndSections = function () {
    return this.generalAdmissionAreas.areas
        .concat(this.sections.sections)
}

seatsio.SubChart.prototype.allSelectableObjectsExceptSections = function () {
    return this.rows
        .concat(this.tables.tables)
        .concat(this.booths.booths)
        .concat(this.icons.icons)
        .concat(this.textInputs)
        .concat(this.imageObjects.images)
        .concat(this.shapes.shapes)
        .concat(this.generalAdmissionAreas.areas)
}

seatsio.SubChart.prototype.categorisableParentObjects = function () {
    return this.rows
        .concat(this.tables.tables)
        .concat(this.booths.booths)
        .concat(this.generalAdmissionAreas.areas)
}

seatsio.SubChart.prototype.categorisableObjects = function () {
    return this.chairs()
        .concat(this.booths.booths)
        .concat(this.generalAdmissionAreas.areas)
}

seatsio.SubChart.prototype.bookableObjects = function () {
    return this.chairs()
        .concat(this.booths.booths)
        .concat(this.generalAdmissionAreas.areas)
}

seatsio.SubChart.prototype.bookableParentObjects = function () {
    return this.rows
        .concat(this.tables.tables)
        .concat(this.booths.booths)
        .concat(this.generalAdmissionAreas.areas)
}

seatsio.SubChart.prototype.bookableParentObjectsWithSections = function () {
    return this.bookableParentObjects()
        .concat(this.sections.sections)
}

seatsio.SubChart.prototype.nonBookableObjects = function () {
    return this.textInputs
        .concat(this.shapes.shapes)
        .concat(this.sections.sections)
}

seatsio.SubChart.prototype.findByUuid = function (uuid) {
    return this.allSelectableObjects().findOne(object => object.uuid === uuid)
}

seatsio.SubChart.prototype.hideLabels = function () {
    this.allNonSeatLabelableObjects().forEach(function (object) {
        object.hideLabelAndChildLabels()
    })
    this.bookableObjects().forEach(object => object.applyElementAttributes())
}

seatsio.SubChart.prototype.showRowLabels = function () {
    this.allRows().forEach(function (row) {
        row.showLabel()
    })
}

seatsio.SubChart.prototype.hideRowLabels = function () {
    this.allRows().forEach(function (row) {
        row.hideLabel()
    })
}

seatsio.SubChart.prototype.showLabels = function () {
    this.allNonSeatLabelableObjects().forEach(function (object) {
        object.showLabelAndChildLabels()
    })
    this.bookableObjects().forEach(object => object.applyElementAttributes())
}

seatsio.SubChart.prototype.showVFS = function () {
    this.sections.sections.forEach(section => section.showVFS())
    this.generalAdmissionAreas.areas.forEach(area => area.showVFS())
    this.allSeats().forEach(seat => seat.showVFS())
    this.allTables().forEach(table => table.showVFS())
}

seatsio.SubChart.prototype.hideVFS = function () {
    this.sections.sections.forEach(section => section.hideVFS())
    this.generalAdmissionAreas.areas.forEach(area => area.hideVFS())
    this.allSeats().forEach(seat => seat.hideVFS())
    this.allTables().forEach(table => table.hideVFS())
}

seatsio.SubChart.prototype.draw = function () {
    this.allObjects().forEach(function (object) {
        object.draw()
    })
    return this
}

seatsio.SubChart.prototype.undraw = function () {
    this.allObjects().forEach(function (object) {
        object.undraw()
    })
}

seatsio.SubChart.prototype.redraw = function () {
    this.undraw()
    this.draw()
}

seatsio.SubChart.prototype.objects = function () {
    return [
        ...this.rows,
        ...this.generalAdmissionAreas.areas,
        ...this.shapes.shapes,
        ...this.tables.tables,
        ...this.booths.booths,
        ...this.icons.icons,
        ...this.textInputs,
        ...this.imageObjects.images,
        ...this.sections.sections
    ]
}

seatsio.SubChart.prototype.nonSeatLabelableObjects = function () {
    return this.tables.tables
        .concat(this.rows)
        .concat(this.booths.booths)
}

seatsio.SubChart.prototype.allObjectsWithSeats = function () {
    return this.objectsWithSeats()
}

seatsio.SubChart.prototype.allSeats = function () {
    return this.allObjectsWithSeats().flatMap(objectWithSeats => objectWithSeats.chairs)
}

seatsio.SubChart.prototype.allTables = function () {
    return this.tables.tables
}

seatsio.SubChart.prototype.objectsWithSeats = function () {
    return this.tables.tables.concat(this.rows)
}

seatsio.SubChart.prototype.chairs = function () {
    var chairs = []
    this.objectsWithSeats().forEach(function (row) {
        chairs = chairs.concat(row.getChairs())
    })
    return chairs
}

seatsio.SubChart.prototype.blur = function () {
    this.allObjects().forEach(function (object) {
        object.blur()
    })
}

seatsio.SubChart.prototype.unblur = function () {
    this.allObjects().forEach(function (object) {
        object.unblur()
    })
}

seatsio.SubChart.prototype.computeAutoSizedHeight = function () {
    if (!this.bbox) {
        return null
    }
    this.autoSizedHeight = roundTo2Places(this.getBBox().height)
    return this.autoSizedHeight
}

seatsio.SubChart.prototype.computeAutoSizedWidth = function () {
    if (!this.bbox) {
        return null
    }
    this.autoSizedWidth = roundTo2Places(this.getBBox().width)
    return this.autoSizedWidth
}

seatsio.SubChart.prototype.isActive = function () {
    return this.designer.activeSubChart() === this
}

seatsio.SubChart.prototype.seatsCount = function () {
    return this.rows.reduce((count, row) => count + row.chairs.length, 0)
}

seatsio.SubChart.prototype.totalPeopleCapacity = function () {
    return this.allBookableObjects().reduce((total, object) => {
        return total + object.totalPeopleCapacity()
    }, 0)
}

seatsio.SubChart.prototype.hasObjects = function () {
    return this.objects().length > 0
}

seatsio.SubChart.prototype._toJson = function (extra) {
    this.computeBbox()
    var height = this.computeAutoSizedHeight()
    var width = this.computeAutoSizedWidth()
    var json = {
        'height': height,
        'width': width,
        'tables': this.tables.tables.map(toJson),
        'texts': this.textInputs.map(toJson),
        'imageObjects': this.imageObjects.images.map(toJson),
        'rows': this.rows.map(toJson),
        'shapes': this.shapes.shapes.map(toJson),
        'booths': this.booths.booths.map(toJson),
        'icons': this.icons.icons.map(toJson),
        'generalAdmissionAreas': this.generalAdmissionAreas.areas.map(toJson)
    }
    if (extra) {
        extra(json)
    }
    return json
}

seatsio.SubChart._fromJson = function (json, subChart, extra) {
    subChart.autoSizedWidth = json.width
    subChart.autoSizedHeight = json.height
    subChart.rows = seatsio.SubChart.rowsFromJson(json.rows, subChart)
    subChart.textInputs = seatsio.SubChart.textsFromJson(json.texts, subChart)
    subChart.imageObjects = seatsio.ImageObjects.fromJson(json.imageObjects, subChart)
    subChart.tables = seatsio.Tables.fromJson(json.tables, subChart)
    subChart.booths = seatsio.Booths.fromJson(json.booths, subChart)
    subChart.icons = seatsio.Icons.fromJson(json.icons, subChart)
    subChart.shapes = seatsio.ShapedObjects.fromJson(json.shapes, subChart)
    subChart.generalAdmissionAreas = seatsio.GeneralAdmissionAreas.fromJson(json.generalAdmissionAreas, subChart)
    if (extra) {
        extra(subChart)
    }
    return subChart
}

seatsio.SubChart.rowsFromJson = function (rows, subChart) {
    return rows.map(function (row) {
        return subChart.loadRow(seatsio.Row.createFromModel(row, subChart))
    })
}

seatsio.SubChart.textsFromJson = function (texts, subChart) {
    return texts.map(function (text) {
        var textInput = seatsio.TextInput.fromJson(text, subChart)
        subChart.textInputs.push(textInput)
        return textInput
    })
}

seatsio.SectionSubChart = function (section, designer) {
    this.init(designer)
    this.section = section
    this.category = section.category
    this.backgroundSection = new seatsio.BackgroundSection(section, designer)
    this.backgroundImageForSection = new seatsio.BackgroundImageForSection(section, this.backgroundSection, designer)
    this.referenceChartForSection = new seatsio.ReferenceChartForSection(section, section.subChart.referenceChart, designer)
}

seatsio.SectionSubChart.prototype = new seatsio.SubChart()

seatsio.SectionSubChart.prototype.isMasterSubChart = function () {
    return false
}

seatsio.SectionSubChart.prototype.isSectionSubChart = function () {
    return !this.isMasterSubChart()
}

seatsio.SectionSubChart.prototype.getReferenceChart = function () {
    return this.referenceChartForSection
}

seatsio.SectionSubChart.prototype.floorIndex = function () {
    return this.designer.subChartFloors.indexOf(this.section.subChart)
}

seatsio.SectionSubChart.prototype.getFloorName = function () {
    return this.section.subChart.getFloorName()
}

seatsio.SectionSubChart.prototype.listUnsupportedObjectTypes = function (objects) {
    if (objects.some(o => o.type === 'section')) {
        return ['section']
    }
    return []
}

seatsio.SectionSubChart.prototype.toJson = function () {
    return this._toJson()
}

seatsio.SectionSubChart.prototype.clone = function (section) {
    var subChart = new seatsio.SectionSubChart(section, section.designer)
    subChart.rows = this.rows.map(function (row) {
        return row.clone(subChart)
    })
    subChart.tables = this.tables.clone(subChart)
    subChart.booths = this.booths.clone(subChart)
    subChart.textInputs = this.textInputs.map(function (textInput) {
        return textInput.clone(subChart)
    })
    subChart.imageObjects = this.imageObjects.clone(subChart)
    subChart.shapes = this.shapes.clone(subChart)
    subChart.generalAdmissionAreas = this.generalAdmissionAreas.clone(subChart)
    return subChart
}

seatsio.SectionSubChart.prototype.allObjects = function () {
    return this.allSelectableObjects()
        .concat(this.backgroundImageForSection)
        .concat(this.referenceChartForSection)
        .concat(this.backgroundSection)
}

seatsio.SectionSubChart.prototype.allBookableObjects = function () {
    return this.bookableObjects()
}

seatsio.SectionSubChart.prototype.allBooths = function () {
    return this.booths.booths
}

seatsio.SectionSubChart.prototype.allImageObjects = function () {
    return this.imageObjects.images
}

seatsio.SectionSubChart.prototype.allBookableParentObjects = function () {
    return this.bookableParentObjects()
}

seatsio.SectionSubChart.prototype.allNonSeatLabelableObjects = function () {
    return this.nonSeatLabelableObjects()
}

seatsio.SectionSubChart.prototype.allTables = function () {
    return this.tables.tables
}

seatsio.SectionSubChart.prototype.allRows = function () {
    return this.rows
}

seatsio.SectionSubChart.prototype.refreshOutOfBounds = function (refreshOnChange = false) {
    this.allSelectableObjects().forEach(object => object.refreshOutOfBounds(refreshOnChange))
}

seatsio.SectionSubChart.prototype.computeBbox = function () {
    this.bbox = this.backgroundSection.bbox().round()
}

seatsio.SectionSubChart.prototype.sectionScaleChanged = function () {
    if (!this.designer.loadingFromJson) {
        this.redraw()
    }
}

seatsio.SectionSubChart.prototype.rotated = function (angle) {
    this.allSelectableObjects().forEach(object => object.rotated(this.getBBox().center(), angle))

    let oldSectionBboxCenter = this.section.bbox().center()
    let newSectionBboxCenter = this.section.getShape().rotatedBbox(oldSectionBboxCenter, angle).center()
    let transformedNewSectionBboxCenter = new seatsio.Ray(oldSectionBboxCenter, newSectionBboxCenter)
        .enlargeByFactor(this.designer.sectionScaleFactor / 100)
        .end
    this.allSelectableObjects().forEach(object => object.moved(oldSectionBboxCenter.minus(transformedNewSectionBboxCenter)))
}

seatsio.SectionSubChart.prototype.pointFromJson = function (point) {
    var bbox = this.getBBox()
    return bbox.origin.add(point)
}

seatsio.SectionSubChart.fromJson = function (section, json, designer) {
    return seatsio.SubChart._fromJson(json, new seatsio.SectionSubChart(section, designer))
}

seatsio.SectionSubChart.prototype.flip = function (isHorizontal) {
    new seatsio.Flipper().flip(this.allSelectableObjects(), this.bbox.center(), isHorizontal)
}

seatsio.SectionSubChart.prototype.applyToDimension = function (dimension) {
    return dimension * (this.designer.sectionScaleFactor / 100)
}

seatsio.SectionSubChart.prototype.applyToPoint = function (point) {
    var distanceOfSectionToCanvasCenter = this.designer.canvasCenter.subtract(this.section.bbox().center())
    var pointMovedSameDistanceAsSectionToCanvasCenter = point.add(distanceOfSectionToCanvasCenter)
    return new seatsio.Ray(this.designer.canvasCenter, pointMovedSameDistanceAsSectionToCanvasCenter)
        .enlargeByFactor(this.designer.sectionScaleFactor / 100)
        .end
}

seatsio.MasterSubChart = function (designer) {
    this.init(designer)
    this.focalPoint = new seatsio.FocalPoint(this)
    this.backgroundImage = new seatsio.BackgroundImage(this)
    this.referenceChart = new seatsio.ReferenceChart(this)
}

seatsio.MasterSubChart.prototype = new seatsio.SubChart()

seatsio.MasterSubChart.prototype.isMasterSubChart = function () {
    return true
}

seatsio.MasterSubChart.prototype.isSectionSubChart = function () {
    return !this.isMasterSubChart()
}

seatsio.MasterSubChart.prototype.getReferenceChart = function () {
    return this.referenceChart
}

seatsio.MasterSubChart.prototype.floorIndex = function () {
    return this.designer.subChartFloors.indexOf(this)
}

seatsio.MasterSubChart.prototype.getFloorName = function () {
    return this.floorName
}

seatsio.MasterSubChart.prototype.getBBox = function () {
    return this.designer.subChartFloors.mergedBbox()
}

seatsio.MasterSubChart.prototype.isUnused = function () {
    return this.isEmpty() && !this.backgroundImage.isSet()
}

seatsio.MasterSubChart.prototype.listUnsupportedObjectTypes = function (objects) {
    if (this.designer.getVenueSettings().supportsSections) {
        return objects
            .filter(o =>
                o.type !== 'section' &&
                o.type !== 'generalAdmission' &&
                !(o instanceof seatsio.ShapedObject) &&
                !(o instanceof seatsio.TextInput) &&
                !(o instanceof seatsio.ImageObject) &&
                !(o instanceof seatsio.Icon)
            )
            .map(o => o.type)
            .uniques()
    } else {
        if (objects.some(o => o.type === 'section')) {
            return ['section']
        }
        return []
    }
}

seatsio.MasterSubChart.prototype.allObjects = function () {
    return this.allSelectableObjects().concat(this.backgroundImage).concat(this.referenceChart)
}

seatsio.MasterSubChart.prototype.allObjectsWithSeats = function () {
    return this.allSubCharts()
        .flatMap(function (subChart) {
            return subChart.objectsWithSeats()
        })
}

seatsio.MasterSubChart.prototype.allSubCharts = function () {
    return this.sectionSubCharts().concat([this])
}

seatsio.MasterSubChart.prototype.sectionSubCharts = function () {
    return this.sections.sections
        .map(function (section) {
            return section.sectionSubChart
        })
}

seatsio.MasterSubChart.prototype.hasSectionWithObjects = function () {
    return this.sectionSubCharts().some(sectionSubChart => sectionSubChart.hasObjects())
}

seatsio.MasterSubChart.prototype.allBookableObjects = function () {
    return this.allSubCharts()
        .flatMap(function (subChart) {
            return subChart.bookableObjects()
        })
}

seatsio.MasterSubChart.prototype.allBookableObjectsWithTables = function () {
    return this.allSubCharts().flatMap(subChart => subChart.bookableObjects().concat(subChart.tables.tables))
}

seatsio.MasterSubChart.prototype.allBooths = function () {
    return this.allSubCharts()
        .flatMap(function (subChart) {
            return subChart.booths.booths
        })
}

seatsio.MasterSubChart.prototype.allImageObjects = function () {
    return this.allSubCharts().flatMap(subChart => subChart.imageObjects.images)
}

seatsio.MasterSubChart.prototype.allBookableParentObjects = function () {
    return this.allSubCharts().flatMap(subChart => subChart.bookableParentObjects())
}

seatsio.MasterSubChart.prototype.allNonSeatLabelableObjects = function () {
    return this.allSubCharts()
        .flatMap(function (subChart) {
            return subChart.nonSeatLabelableObjects()
        })
}

seatsio.MasterSubChart.prototype.allTables = function () {
    return this.allSubCharts()
        .flatMap(function (subChart) {
            return subChart.tables.tables
        })
}

seatsio.MasterSubChart.prototype.allRows = function () {
    return this.allSubCharts()
        .flatMap(function (subChart) {
            return subChart.rows
        })
}

seatsio.MasterSubChart.prototype.setFloorDisplayName = function (name) {
    this.floorDisplayName = name || undefined
}

seatsio.MasterSubChart.prototype.setFloorName = function (name) {
    this.floorName = name || undefined
    this.designer.requestStatsUpdate()
}

seatsio.MasterSubChart.prototype.computeBbox = function () {
    let objectsOnRenderedChart = this.renderedObjects()
    if (objectsOnRenderedChart.length === 0) {
        this.bbox = new seatsio.Bbox(this.designer.canvasCenter, 0, 0)
    } else {
        this.bbox = seatsio.Bbox.mergedFromObjects(objectsOnRenderedChart)
    }
}

seatsio.MasterSubChart.prototype.renderedObjects = function () {
    var renderedObjects = seatsio.SubChart.prototype.objects.apply(this)

    if (this.backgroundImage.isSet() && this.backgroundImage.showOnRenderedCharts) {
        renderedObjects.push(this.backgroundImage)
    }
    return renderedObjects
}

seatsio.MasterSubChart.prototype.objects = function () {
    return [
        ...seatsio.SubChart.prototype.objects.apply(this),
        this.focalPoint,
        this.backgroundImage,
        this.referenceChart
    ]
}

seatsio.MasterSubChart.prototype.abstractDrawingObjects = function () {
    return this.shapes.shapes
        .concat(this.sections.sections)
        .concat(this.generalAdmissionAreas.areas)
}

seatsio.MasterSubChart.prototype.abstractDraw = function (color) {
    return this.abstractDrawingObjects().map(object => object.simpleDraw(color))
}

seatsio.MasterSubChart.prototype.toJson = function () {
    return this._toJson(function (json) {
        json.sections = this.sections.toJson()
        json.focalPoint = this.focalPoint.toJson()
        json.backgroundImage = this.backgroundImage.toJson()
        json.referenceChart = this.referenceChart.toJson()
        json.snapOffset = this.computeSnapOffset()
        json.floorDisplayName = this.floorDisplayName
        json.floorName = this.floorName
    }.bind(this))
}

seatsio.MasterSubChart.prototype.computeSnapOffset = function () {
    let bbox = this.getBBox()
    if (!bbox) {
        return { x: 0, y: 0 }
    }
    let snapX = bbox.origin.x % seatsio.Point.SNAP_PRECISION
    let snapY = bbox.origin.y % seatsio.Point.SNAP_PRECISION
    return { x: roundTo2Places(snapX), y: roundTo2Places(snapY) }
}

seatsio.MasterSubChart.prototype.pointFromJson = function (point) {
    let snappedPoint = point.add(this.snapOffset)
    return snappedPoint.add(this.distanceToViewCenterSnapped())
}

seatsio.MasterSubChart.prototype.distanceToViewCenterSnapped = function () {
    return new seatsio.Point(0, 0)
        .addToX((this.designer.width / 2) - (this.autoSizedWidth / 2))
        .addToY((this.designer.height / 2) - (this.autoSizedHeight / 2))
        .snapToGridEvenIfNotEnabled()
}

seatsio.MasterSubChart.prototype.categorisableParentObjects = function () {
    return seatsio.SubChart.prototype.categorisableParentObjects.apply(this).concat(this.sections.sections)
}

seatsio.MasterSubChart.prototype.categorisableObjects = function () {
    return seatsio.SubChart.prototype.categorisableObjects.apply(this).concat(this.sections.sections)
}

seatsio.MasterSubChart.prototype.zoneableObjects = function () {
    return [...this.generalAdmissionAreas.areas, ...this.sections.sections]
}

seatsio.MasterSubChart.prototype.duplicateObjectsDetected = function (duplicateObjects) {
    this.allBookableObjectsWithTables().forEach(object => {
        let isDuplicateObject = duplicateObjects[object.getFullLabel()]
        if (isDuplicateObject) {
            object.markAsDuplicate()
        } else {
            object.markAsNotDuplicate()
        }
    })
}

seatsio.MasterSubChart.prototype.scale = function (factor, onlyReferenceChart) {
    const center = this.getBBox().center()
    if (onlyReferenceChart) {
        this.referenceChart.scaleImmediately(factor, center)
    } else {
        this.objects().forEach(object => object.scaleImmediately(factor, center))
    }
    this.allSubCharts().forEach(subChart => subChart.computeBbox())
}

seatsio.MasterSubChart.fromJson = function (json, designer) {
    var masterSubChart = new seatsio.MasterSubChart(designer)
    masterSubChart.snapOffset = new seatsio.Point(json.snapOffset.x, json.snapOffset.y)
    return seatsio.SubChart._fromJson(json, masterSubChart, function (masterSubChart) {
        masterSubChart.focalPoint = json.focalPoint ? seatsio.FocalPoint.fromJson(json.focalPoint, masterSubChart) : masterSubChart.focalPoint
        masterSubChart.backgroundImage = seatsio.BackgroundImage.fromJson(json.backgroundImage, masterSubChart)
        masterSubChart.referenceChart = seatsio.ReferenceChart.fromJson(json.referenceChart, masterSubChart)
        masterSubChart.sections = seatsio.Sections.fromJson(json.sections, masterSubChart)
        masterSubChart.floorDisplayName = json.floorDisplayName
        masterSubChart.floorName = json.floorName
    })
}

seatsio.SubChartFloors = class SubChartFloors {
    constructor (designer, subCharts = []) {
        this.designer = designer
        this.subCharts = subCharts
        this.currentFloor = 0
    }

    init () {
        this.abstractFloors = seatsio.set()
        return this
    }

    newSubChart () {
        if (this.length() >= seatsio.SubChartFloors.MAX_FLOORS) {
            return
        }

        const newFloor = seatsio.MasterSubChart.fromJson(seatsio.VenueTypeSwitcher.createMasterDataStructure(this.designer, this.length()), this.designer)
        this.subCharts.push(newFloor)
        newFloor.setFloorName(this.length().toString())
        return _.last(this.subCharts)
    }

    push (subChart) {
        this.subCharts.push(subChart)
    }

    remove (subChart) {
        this.subCharts.remove(subChart)
    }

    deleteFloor (floorIndex) {
        this.subCharts.splice(floorIndex, 1)
        this.updateDefaultFloorNames(floorIndex)
    }

    updateDefaultFloorNames () {
        const numFloors = this.length()
        for (let i = 0; i < numFloors; i++) {
            const floorName = this.subCharts[i].floorName
            const regEx = /^[1-9]$/
            if (regEx.test(floorName) && floorName === (i + 2).toString()) {
                this.subCharts[i].setFloorName((i + 1).toString())
            }
        }
    }

    setFloorDisplayName (floorIndex, floorDisplayName) {
        this.subCharts[floorIndex].setFloorDisplayName(floorDisplayName)
    }

    setFloorName (floorIndex, floorName) {
        this.subCharts[floorIndex].setFloorName(floorName)
    }

    getCurrentMasterSubChart () {
        return this.subCharts[this.currentFloor]
    }

    getFloorDetails () {
        return this.subCharts.map(floor => ({
            floorDisplayName: floor.floorDisplayName,
            floorName: floor.floorName
        }))
    }

    getCurrentFloorIndex () {
        return this.currentFloor
    }

    subChartsBelowCurrent () {
        return this.subCharts.slice(0, this.currentFloor)
    }

    hasFloor (floorIndex) {
        return floorIndex < this.subCharts.length
    }

    setFloor (floorIndex) {
        if (floorIndex < this.subCharts.length) {
            this.currentFloor = floorIndex
        } else {
            this.currentFloor = this.subCharts.length - 1
        }
    }

    length () {
        return this.subCharts.length
    }

    mergedBbox () {
        return seatsio.Bbox.merged(this.subCharts.map(subChart => subChart.getContentsBBox()))
    }

    hasMultipleFloors () {
        return this.length() > 1
    }

    onFirstFloor () {
        return this.currentFloor === 0
    }

    hasUsedFloors () {
        return this.subCharts.some(masterSubChart => !masterSubChart.isUnused())
    }

    /* Abstract drawing */

    getFloorColor (floorIndex) {
        const baseLuminosity = this.designer.isDarkCanvas() ? 26 : 90
        const levelStep = this.designer.isDarkCanvas() ? -4 : 2
        const levelsBelowCurrent = Math.min(3, this.currentFloor - floorIndex)
        return `hsl(0, 0%, ${baseLuminosity + levelsBelowCurrent * levelStep}%)`
    }

    redrawAbstractFloors () {
        this.removeAbstractFloors()
        this.drawAbstractFloors()
    }

    drawAbstractFloors () {
        this.subChartsBelowCurrent().forEach((subChart, floorIndex) => {
            this.postProcessAbstractDraw(subChart.abstractDraw(this.getFloorColor(floorIndex)))
                .forEach(abstractDrawing => this.abstractFloors.push(abstractDrawing))
        })
    }

    postProcessAbstractDraw (elements) {
        const setPointerEventsNone = (element) => element.node.setAttribute('pointer-events', 'none')

        return elements.map(element => {
            if (element instanceof SvgElementSet) {
                element.items.forEach(setPointerEventsNone)
            } else {
                setPointerEventsNone(element)
            }
            element
                .toLayer('abstractFloorsLayer', this.designer)
                .applyZoom(this.designer)
            return element
        })
    }

    removeAbstractFloors () {
        this.abstractFloors.forEach(item => item.remove())
        this.abstractFloors.clear()
    }

    applyZoom () {
        this.abstractFloors.forEach(element => element.applyZoom(this.designer))
    }

    /* Sub Charts */

    firstFloorSubChart () {
        return this.subCharts[0]
    }

    indexOf (subChart) {
        return this.subCharts.indexOf(subChart)
    }

    allMasterSubCharts () {
        return this.subCharts
    }

    scale (factor, onlyReferenceChart) {
        this.allMasterSubCharts().forEach(subChart => subChart.scale(factor, onlyReferenceChart))
    }

    allBookableObjects () {
        return this.allMasterSubCharts().flatMap(subChart => subChart.allBookableObjects())
    }

    allBookableObjectsWithTables () {
        return this.allMasterSubCharts().flatMap(subChart => subChart.allBookableObjectsWithTables())
    }

    toJson () {
        return this.subCharts.map(subChart => subChart.toJson())
    }

    static fromJson (json, designer) {
        return new seatsio.SubChartFloors(designer, json.map(floorJson => seatsio.MasterSubChart.fromJson(floorJson, designer)))
    }
}

seatsio.SubChartFloors.MAX_FLOORS = 9

seatsio.Zoomer = function (zoomListener) {
    this.zoomListener = zoomListener
    this.reset()
}

seatsio.Zoomer.prototype.reset = function () {
    this.zoomLevel = 1
    this.transformationMatrix = this.previousTransformationMatrix = new SVG.Matrix()
}

seatsio.Zoomer.prototype.zoomIn = function (center) {
    this.zoom(center, this.zoomLevel * seatsio.Zoomer.zoomStep)
}

seatsio.Zoomer.prototype.zoomOut = function (center) {
    this.zoom(center, this.zoomLevel / seatsio.Zoomer.zoomStep)
}

seatsio.Zoomer.prototype.zoom = function (center, level) {
    this.zoomLevel = this.cap(level)
    this.transformationMatrix = seatsio.Zoomer.transformationMatrixToZoomTo(this.zoomLevel, center, this.previousTransformationMatrix)
    this.previousTransformationMatrix = this.transformationMatrix
    this.zoomListener()
}

seatsio.Zoomer.prototype.resetAndZoom = function (center, level) {
    this.reset()
    this.zoom(center, level)
}

seatsio.Zoomer.prototype.cap = function (zoomLevel) {
    return Math.max(seatsio.Zoomer.minZoomLevel, Math.min(zoomLevel, seatsio.Zoomer.maxZoomLevel))
}

seatsio.Zoomer.prototype.atInitialZoomLevel = function (fn) {
    const zoomLevel = this.zoomLevel
    const transformationMatrix = this.transformationMatrix
    const previousTransformationMatrix = this.previousTransformationMatrix

    this.zoomLevel = 1
    this.transformationMatrix = this.previousTransformationMatrix = new SVG.Matrix()

    try {
        return fn()
    } finally {
        this.zoomLevel = zoomLevel
        this.transformationMatrix = transformationMatrix
        this.previousTransformationMatrix = previousTransformationMatrix
    }
}

seatsio.Zoomer.prototype.applyToElement = function (element, zoomLevel = null, center = null) {
    let transformationMatrix = zoomLevel ? seatsio.Zoomer.transformationMatrixToZoomTo(zoomLevel, center, this.transformationMatrix) : this.transformationMatrix
    element.transform(transformationMatrix)
    if (!zoomLevel) zoomLevel = this.zoomLevel
    if (element.keepSize) {
        element.extraZoom = 1 / zoomLevel
    }
    if (element.extraZoom) {
        element.scale(element.extraZoom)
    }
    if (element.rotationAngle) {
        if (element.rotationCenter) {
            element.rotate(element.rotationAngle, element.rotationCenter.x, element.rotationCenter.y)
        } else {
            let bbox = element.bbox()
            element.rotate(element.rotationAngle, bbox.cx, bbox.cy)
        }
    }
}

seatsio.Zoomer.prototype.applyToPoint = function (point) {
    let transformedPoint = new SVG.Point(point.x, point.y).transform(this.transformationMatrix)
    return new seatsio.Point(transformedPoint.x, transformedPoint.y)
}

seatsio.Zoomer.prototype.zoomed = function (number) {
    return number * this.zoomLevel
}

seatsio.Zoomer.prototype.unzoom = function (number) {
    return number / this.zoomLevel
}

seatsio.Zoomer.prototype.serialize = function () {
    return {
        zoomLevel: this.zoomLevel,
        transformationMatrix: this.transformationMatrix,
        previousTransformationMatrix: this.previousTransformationMatrix
    }
}

seatsio.Zoomer.prototype.deserialize = function (data) {
    this.zoomLevel = data.zoomLevel
    this.transformationMatrix = data.transformationMatrix
    this.previousTransformationMatrix = data.previousTransformationMatrix
    this.zoomListener()
}

seatsio.Zoomer.transformationMatrixToZoomTo = function (newZoomLevel, newZoomCenter, previousTransformationMatrix) {
    let previousZoomLevel = previousTransformationMatrix.a
    let zoomDelta = newZoomLevel / previousZoomLevel
    let transformedPoint = new SVG.Point(newZoomCenter.x, newZoomCenter.y).transform(previousTransformationMatrix.inverse())
    return new SVG.Matrix()
        .scale(zoomDelta, zoomDelta, transformedPoint.x, transformedPoint.y)
        .transform(previousTransformationMatrix)
}

seatsio.Zoomer.zoomStep = 1.25
seatsio.Zoomer.maxZoomLevel = Math.pow(seatsio.Zoomer.zoomStep, 7)
seatsio.Zoomer.minZoomLevel = Math.pow(seatsio.Zoomer.zoomStep, -20)

seatsio.Panner = class {
    constructor () {
        this.lastEdgePanning = 0
        this.edgePanningDirection = new seatsio.Point(0, 0)
    }

    start () {
        this.animationFrame()
    }

    panBy (deltaX, deltaY) {
        let $container = $(window)
        this.panTo($container.scrollLeft() + deltaX, $container.scrollTop() + deltaY)
    }

    panTo (x, y) {
        $(window)
            .scrollLeft(x)
            .scrollTop(y)
    }

    panLevel () {
        let $container = $(window)
        return new seatsio.Point($container.scrollLeft(), $container.scrollTop())
    }

    serialize () {
        return this.panLevel()
    }

    deserialize (panLevel) {
        this.panTo(panLevel.x, panLevel.y)
    }

    refreshEdgePanning (cursorPosition) {
        this.lastEdgePanning = Date.now()
        this.edgePanningDirection = this.getEdgePanningDirection(cursorPosition)
    }

    stopEdgePanning () {
        this.edgePanningDirection = new seatsio.Point(0, 0)
    }

    getEdgePanningDirection (cursorPosition) {
        const padding = 40
        const direction = new seatsio.Point(0, 0)
        if (cursorPosition.x < seatsio.PANEL_DIMENSIONS.leftPanelWidth + padding) {
            direction.x = -1
        } else if (cursorPosition.x > window.innerWidth - seatsio.PANEL_DIMENSIONS.rightPanelWidth - padding) {
            direction.x = 1
        }
        if (cursorPosition.y < seatsio.PANEL_DIMENSIONS.topPanelHeight + padding) {
            direction.y = -1
        } else if (cursorPosition.y > window.innerHeight - seatsio.PANEL_DIMENSIONS.bottomPanelHeight - padding) {
            direction.y = 1
        }
        return direction
    }

    getSecondsSinceLastEdgePush () {
        return (Date.now() - this.lastEdgePanning) / 1000
    }

    animationFrame () {
        if (this.edgePanningDirection.length() > 0) {
            const slowdownLengthSeconds = 1.5
            const speed = 4 * Math.min(1, Math.max(0, slowdownLengthSeconds - this.getSecondsSinceLastEdgePush()))
            this.panBy(this.edgePanningDirection.x * speed, this.edgePanningDirection.y * speed)
        }
        requestAnimationFrame(() => this.animationFrame())
    }
}

seatsio.FocalPoint = function (subChart) {
    this.init(subChart.designer, true)
    this.subChart = subChart
    this.pointer = new seatsio.FocalPointPointer(this.designer)
    this.point = null
    this.focalPointShapes = null
}

seatsio.FocalPoint.prototype = new seatsio.Object()

seatsio.FocalPoint.prototype.canBeRotated = function () {
    return false
}

seatsio.FocalPoint.prototype.canShowSelectionRectangle = function () {
    return false
}

seatsio.FocalPoint.prototype.getInspectorSheets = function () {
    return Object.assign(seatsio.Object.prototype.getInspectorSheets.call(this), {
        'FocalPoint': null
    })
}

seatsio.FocalPoint.prototype.bbox = function () {
    return this.selectionIndicator().bbox()
}

seatsio.FocalPoint.prototype.selectionIndicator = function () {
    return new seatsio.CircleShape(this.point, this.designer.zoomer.unzoom(20))
}

seatsio.FocalPoint.prototype.draw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    if (!this.point) {
        return this
    }
    this.undraw()
    this.focalPointShapes = seatsio.FocalPoint.createShapes(this.designer, this.point)
    this.pulseAnimation()
    this.objectDrawn()
    return this
}

seatsio.FocalPoint.prototype.undraw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    if (this.focalPointShapes) {
        this.focalPointShapes.remove()
    }
    this.objectUndrawn()
    return this
}

seatsio.FocalPoint.prototype.redraw = function () {
    this.undraw()
    this.draw()
}

seatsio.FocalPoint.prototype.pulseAnimation = function () {
    const base = 50
    const delay = 150
    for (let i = this.focalPointShapes.length - 1; i >= 0; i--) {
        this.shapePulseAnimation(this.focalPointShapes.toArray()[i], base + (this.focalPointShapes.length - i) * delay)
    }
}

seatsio.FocalPoint.prototype.shapePulseAnimation = function (shape, timeout) {
    setTimeout(() => this.animateToHighlight(shape), timeout)
}

seatsio.FocalPoint.prototype.rotated = function (rotationCenter, angle) {
    this.point = this.point.rotateAround(rotationCenter, angle)
    this.draw()
}

seatsio.FocalPoint.prototype.remove = function () {
    this.stopAnimation()
    this.undraw()
    this.point = null
    this.designer.requestStatsUpdate()
}

seatsio.FocalPoint.prototype.set = function (point) {
    this.moveTo(point)
    this.designer.requestStatsUpdate()
}

seatsio.FocalPoint.prototype.moved = function (distance) {
    this.point = this.point.add(distance)
    this.draw()
}

seatsio.FocalPoint.prototype.visibleElementsSet = function () {
    if (!this.focalPointShapes) {
        return seatsio.set()
    }
    return this.focalPointShapes
}

seatsio.FocalPoint.prototype.visibleElementsSetWithoutChildren = function () {
    return seatsio.set()
}

seatsio.FocalPoint.prototype.isSet = function () {
    return this.point
}

seatsio.FocalPoint.prototype.toJson = function () {
    if (!this.isSet()) {
        return null
    }
    return this.point.toJson(this.subChart)
}

seatsio.FocalPoint.prototype.moveTo = function (point) {
    this.point = point
    this.draw()
    return this
}

seatsio.FocalPoint.prototype.allElementsSet = function () {
    return this.focalPointShapes
}

seatsio.FocalPoint.prototype.animateToHighlight = function (shape) {
    const initialStrokeColor = shape.initialStrokeColor
    const runner = new SVG.Runner(200)
        .element(shape)
        .attr({
            'stroke': '#0778fa'
        })
        .ease('<>')
    const timeline = new SVG.Timeline()
    timeline.schedule(runner)
    timeline.play()
    setTimeout(() => {
        timeline.stop()
        this.animateFromHighlight(shape, initialStrokeColor)
    }, 300)
}

seatsio.FocalPoint.prototype.animateFromHighlight = function (shape, strokeColor) {
    const runner = new SVG.Runner(400)
        .element(shape)
        .attr({
            'stroke': strokeColor
        })
        .ease('<>')
    const timeline = new SVG.Timeline()
    timeline.schedule(runner)
    timeline.play()
}

seatsio.FocalPoint.prototype.stopAnimation = function () {
    this.focalPointShapes.stop()
}

seatsio.FocalPoint.fromJson = function (json, subChart) {
    var focalPoint = new seatsio.FocalPoint(subChart)
    focalPoint.point = seatsio.Point.fromJson(json, subChart)
    return focalPoint
}

seatsio.FocalPoint.prototype.getColors = function () {
    return seatsio.FocalPoint.getColors(this.designer)
}

seatsio.FocalPoint.prototype.doScale = function (factor, center) {
    if (this.isSet()) {
        this.point = new seatsio.Ray(center, this.stateBeforeScaling.point).enlargeByFactor(factor).end
        this.redraw()
    }
}

seatsio.FocalPoint.getColors = function (designer) {
    return designer.getCanvasColorScheme() !== 'light'
        ? {
            circleStroke: '#ffffff',
            circleFill: 'black',
            glowCircleStroke: '#ffffff'
        }
        : {
            circleStroke: '#06111d',
            circleFill: 'white',
            glowCircleStroke: '#111111'
        }
}

seatsio.FocalPoint.createShapes = function (designer, point) {
    const size = designer.zoomer.unzoom(20)
    const colors = seatsio.FocalPoint.getColors(designer)

    let glowCircle1 = designer.drawer.circle(point.x, point.y, 9 * size).attr({
        'fill': 'transparent',
        'stroke-width': 0.1 * size,
        'stroke': colors.glowCircleStroke,
        'stroke-opacity': 0.07
    })
    glowCircle1.initialStrokeColor = colors.glowCircleStroke
    glowCircle1.node.setAttribute('pointer-events', 'none')

    let glowCircle2 = designer.drawer.circle(point.x, point.y, 6 * size).attr({
        'fill': 'transparent',
        'stroke-width': 0.1 * size,
        'stroke': colors.glowCircleStroke,
        'stroke-opacity': 0.12
    })
    glowCircle2.initialStrokeColor = colors.glowCircleStroke
    glowCircle2.node.setAttribute('pointer-events', 'none')

    let glowCircle3 = designer.drawer.circle(point.x, point.y, 3 * size).attr({
        'fill': 'transparent',
        'stroke-width': 0.1 * size,
        'stroke': colors.glowCircleStroke,
        'stroke-opacity': 0.15
    })
    glowCircle3.initialStrokeColor = colors.glowCircleStroke
    glowCircle3.node.setAttribute('pointer-events', 'none')

    let outerCircle = designer.drawer.circle(point.x, point.y, 1 * size).attr({
        'fill': colors.circleFill,
        'stroke-width': 0.1 * size,
        'stroke': colors.circleStroke
    })
    outerCircle.initialStrokeColor = colors.circleStroke
    outerCircle.node.setAttribute('pointer-events', 'none')

    let innerCircle = designer.drawer.circle(point.x, point.y, 0.5 * size).attr({
        'fill': colors.circleFill,
        'stroke-width': 0.25 * size,
        'stroke': colors.circleStroke
    })
    innerCircle.initialStrokeColor = colors.circleStroke
    innerCircle.node.setAttribute('pointer-events', 'none')

    return seatsio.set(glowCircle1, glowCircle2, glowCircle3, outerCircle, innerCircle).toLayer('tempDrawingsLayer', designer).applyZoom(designer)
}

seatsio.FocalPointPointer = function (designer) {
    this.designer = designer
    this.shapes = null
}

seatsio.FocalPointPointer.prototype.showAt = function (point) {
    this.hide()
    this.shapes = seatsio.FocalPoint.createShapes(this.designer, point)
    return this
}

seatsio.FocalPointPointer.prototype.hide = function () {
    if (this.shapes) {
        this.shapes.remove()
    }
}

seatsio.RowBlockDrawer = function (blockStartPoint, firstRowEndPoint, intertwined, designer) {
    this.blockStartPoint = blockStartPoint
    this.firstRowEndPoint = firstRowEndPoint
    this.intertwined = intertwined
    this.rows = []
    this.numberOfRowsAndChairs = new seatsio.NumberOfRowsAndChairs(designer)
    this.designer = designer
}

seatsio.RowBlockDrawer.prototype.initDraw = function () {
    this.undraw()
    this.drawRows(this.firstRowEndPoint || this.blockStartPoint)
}

seatsio.RowBlockDrawer.prototype.redrawTo = function (blockEndPoint, intertwined) {
    this.undraw()
    this.intertwined = intertwined
    this.drawRows(blockEndPoint)
    let centerOfLastChair = seatsio.Point.centerOfBBox(_.last(this.rows).last().rbox()).fromView(this.designer)
    this.drawNumberOfRowsAndChairs(centerOfLastChair)
}

seatsio.RowBlockDrawer.prototype.drawNumberOfRowsAndChairs = function (blockEndPoint) {
    const centerOfText = blockEndPoint.averageWith(this.blockStartPoint)
    this.numberOfRowsAndChairs.refresh(centerOfText, this.rows.length, this.rows[0].length)
}

seatsio.RowBlockDrawer.prototype.numberOfDrawnSeats = function () {
    return this.rows.length > 0 ? this.rows[0].length : 0
}

seatsio.RowBlockDrawer.prototype.drawRows = function (blockEndPoint) {
    if (this.firstRowEndPoint) {
        this.getRowPointsAtIndex()
        const snapAngle = this.extendingRowSnapAngle(blockEndPoint)
        const pullLength = this.pullLength(blockEndPoint, snapAngle)
        for (let i = 0; i < this.numRows(pullLength); ++i) {
            const direction = pullLength > 0 ? 1 : -1
            const [firstSeat, lastSeat] = this.getRowPointsAtIndex(i * direction, snapAngle)
            this.rows.push(seatsio.Row.drawShapes(firstSeat, lastSeat, this.designer))
        }
        this.rows.forEach((row, ri) => {
            row.forEach(chair => {
                if (ri === 0 || ri === this.rows.length - 1) {
                    chair.attr({ 'stroke': '#0784fa', 'stroke-width': 3 })
                } else {
                    chair.attr({ 'stroke': '#005cc5' })
                }
            })
        })
    } else {
        this.rows.push(seatsio.Row.drawShapes(this.blockStartPoint, blockEndPoint, this.designer))
        this.rows[0].forEach((chair, ci) => {
            if (ci === 0 || ci === this.rows[0].length - 1) {
                chair.attr({ 'stroke': '#0784fa', 'stroke-width': 3 })
            } else {
                chair.attr({ 'stroke': '#005cc5' })
            }
        })
    }
}

seatsio.RowBlockDrawer.prototype.getDrawnSeatCount = function () {
    return this.rows[0].length
}

seatsio.RowBlockDrawer.prototype.getRowPointsAtIndex = function (index, snapAngle = undefined) {
    const ray = new seatsio.Ray(this.blockStartPoint, this.firstRowEndPoint)
    const angle = snapAngle !== undefined ? snapAngle : ray.angle() + 90
    let firstSeat = new seatsio.RayFromOriginAndAngle(this.blockStartPoint, angle)
        .pointAtDistanceFromOrigin(index * seatsio.Row.height())
    let lastSeat = new seatsio.RayFromOriginAndAngle(this.firstRowEndPoint, angle)
        .pointAtDistanceFromOrigin(index * seatsio.Row.height())
    if (this.intertwined && index % 2 !== 0) {
        const newRay = new seatsio.Ray(firstSeat, lastSeat)
            .shrinkOnBothSides((seatsio.Chair.width + this.designer.rowChairSpacing) / 2)
        firstSeat = newRay.end
        lastSeat = newRay.origin
    }
    return [firstSeat, lastSeat]
}

seatsio.RowBlockDrawer.prototype.pullLength = function (blockEndPoint, snapAngle = undefined) {
    const firstRowRay = new seatsio.Ray(this.blockStartPoint, this.firstRowEndPoint)
    const firstRowAngle = firstRowRay.angle()
    const angle = snapAngle !== undefined ? snapAngle : firstRowAngle + 90
    const perpendicularRay = new seatsio.RayFromOriginAndAngle(this.firstRowEndPoint, angle)
    const perpendicularPullPoint = perpendicularRay.projectPoint(blockEndPoint)

    let direction = 1
    if (snapAngle === undefined) {
        const rayToPullPoint = new seatsio.Ray(this.blockStartPoint, perpendicularPullPoint)
        const angleFromRayToPullPoint = new seatsio.Angle(firstRowRay.angleBetween(rayToPullPoint))
        direction = angleFromRayToPullPoint.isQ1() || angleFromRayToPullPoint.isQ3() ? -1 : 1
    }

    return this.firstRowEndPoint.distanceToPoint(perpendicularPullPoint) * direction
}

seatsio.RowBlockDrawer.prototype.extendingRowSnapAngle = function (blockEndPoint) {
    if (!this.designer.shiftWasPressed) {
        return undefined
    }
    const angle = new seatsio.Ray(this.firstRowEndPoint, blockEndPoint).angle() / 180 * Math.PI
    const cos = Math.cos(angle)
    const sin = Math.sin(angle)
    const horizontalSnap = Math.abs(cos) > Math.abs(sin)

    return horizontalSnap
        ? (cos > 0 ? 0 : 180)
        : (sin > 0 ? 90 : 270)
}

seatsio.RowBlockDrawer.prototype.numRows = function (pullLength) {
    return Math.max(1, Math.ceil((Math.abs(pullLength) + seatsio.Row.height() / 2) / seatsio.Row.height()))
}

seatsio.RowBlockDrawer.prototype.undraw = function () {
    this.rows.forEach(function (row) {
        row.remove()
    })
    this.rows = []
    this.numberOfRowsAndChairs.undraw()
}

seatsio.RowBlockDrawer.prototype.createRowObjects = function () {
    const me = this
    return this.rows.map(function (chairShapes) {
        return seatsio.RowBlockDrawer.toRowObject(chairShapes, me.designer)
    })
}

seatsio.RowBlockDrawer.toRowObject = function (chairShapes, designer) {
    function toChairs () {
        return chairShapes.toArray().map(function (chairShape) {
            const center = new seatsio.Point(chairShape.attr('cx'), chairShape.attr('cy'))
            return new seatsio.Chair(center, null, designer.activeSubChart())
        })
    }

    return seatsio.Row.createFromChairs(toChairs(), designer)
}

seatsio.VenueTypeSwitcher = function (chartDesigner) {
    this.designer = chartDesigner
}

seatsio.VenueTypeSwitcher.createMasterDataStructure = function (designer) {
    return {
        backgroundImage: null,
        booths: [],
        generalAdmissionAreas: [],
        rows: [],
        sections: [],
        shapes: [],
        tables: [],
        texts: [],
        snapOffset: {
            x: 0,
            y: 0
        },
        width: 128,
        height: 128,
        floorName: '1'
    }
}
seatsio.VenueTypeSwitcher.prototype.createJson = function (venueType) {
    const data = {
        name: seatsio.ChartDesigner.defaultName(),
        categories: {
            list: [],
            maxCategoryKey: 0
        },
        sectionScaleFactor: 100,
        subChart: seatsio.VenueTypeSwitcher.createMasterDataStructure(this.designer),
        venueType,
        version: seatsio.version,
        tablesLabelCounter: 1,
        uuidCounter: 0,
        scannedOrCalibrated: false
    }
    if (this.getVenueSettings(venueType).supportsMultiFloor) {
        data.multiFloorView = 'isometric'
    }
    return data
}

seatsio.VenueTypeSwitcher.prototype.initBlank = function (venueType) {
    let data = this.createJson(venueType)
    this.designer.saver.save(JSON.stringify(data))
    this.designer.renderDrawing(data)
}

seatsio.VenueTypeSwitcher.prototype.getVenueSettings = function (venueType) {
    if (!venueType) {
        venueType = this.designer.venueType
    }
    return seatsio.determineVenueType(venueType)
}

seatsio.VenueTypeSwitcher.prototype.getFeatureStatus = function (feature) {
    var FT = seatsio.Features.Type
    var FS = seatsio.Features.Status
    if (this.designer.isReadOnly()) {
        if (feature === FT.BACKGROUND_IMAGE || feature === FT.REFERENCE_CHART || feature === FT.VIEW_FROM_YOUR_SEAT) { return FS.DISABLED }
    }
    return this.getVenueSettings().getFeatureStatus(feature, this.designer)
}

seatsio.ScaleSlider = function (container, initialValue, min = 20, max = 500) {
    this.min = min
    this.max = max
    this.container = container
    this.initialValue = initialValue
    this.editableValue = new seatsio.EditableValue(container, initialValue, '%', this.setValue.bind(this))
    this.editableValue.setMin(this.min).setMax(this.max)
    this.init()
}

seatsio.ScaleSlider.prototype.init = function () {
    var initialValue = this.initialValue ? this.initialValue : 100
    this.getSlider().slider({
        'min': this.min,
        'max': this.max,
        'step': 5,
        'value': initialValue,
        tooltip: 'hide',
        'formater': function (value) {
            return value + '%'
        }
    })
    this.updateEditableValue()
}

seatsio.ScaleSlider.prototype.updateEditableValue = function () {
    this.editableValue.setValue(this.getSlider().slider('getValue'))
}

seatsio.ScaleSlider.prototype.onValueChanged = function (callback) {
    this.getSlider().on('slide', function (e) {
        if (e.value instanceof Number) {
            callback(e.value)
        } else if (e.value instanceof Array) {
            callback(e.value[0])
        }
        this.updateEditableValue()
    }.bind(this))
    return this
}

seatsio.ScaleSlider.prototype.setValue = function (value) {
    this.getSlider().slider('setValue', value)
    this.updateEditableValue()
}

seatsio.ScaleSlider.prototype.getSlider = function () {
    return this.container.find('.sliderDiv')
}

seatsio.ScaleSlider.prototype.show = function () {
    this.container.show()
}

seatsio.ScaleSlider.prototype.hide = function () {
    this.container.hide()
}

seatsio.EditableValue = function (container, value, unit, parentSetValue) {
    PIXELS_FOR_UNIT_STEP = 3

    this.container = container
    this.unit = unit
    this.setValue(value)
    this.parentSetValue = parentSetValue

    this.moveStartValue = value
    this.moveStartX = null

    this.min = null
    this.max = null

    this.isScrubbing = false
    this.isTextInputActive = false

    this.appendListeners()
    this.refreshMode()
}

seatsio.EditableValue.prototype.element = function () {
    return this.container.find('.editableValue')
}

seatsio.EditableValue.prototype.updateValue = function (value) {
    if (this.value === value) return
    this.parentSetValue(value)
}

seatsio.EditableValue.prototype.onMouseMove = function (e) {
    var alphaX = e.screenX - this.moveStartX
    var valueAlpha = Math.round(alphaX / PIXELS_FOR_UNIT_STEP)
    var value = this.moveStartValue + valueAlpha

    if (Math.abs(valueAlpha) > 0) this.isScrubbing = true

    if (this.min && value <= this.min) {
        value = this.min
        $('#chartDesignerWrapper').addClass('scrubbing-minReached')
    } else {
        $('#chartDesignerWrapper').removeClass('scrubbing-minReached')
    }

    if (this.max && value >= this.max) {
        value = this.max
        $('#chartDesignerWrapper').addClass('scrubbing-maxReached')
    } else {
        $('#chartDesignerWrapper').removeClass('scrubbing-maxReached')
    }

    this.updateValue(value)
}

seatsio.EditableValue.prototype.activateTextInput = function () {
    this.isTextInputActive = true
    this.refreshMode()
    this.element().children('.valueInput').focus().select()
}

seatsio.EditableValue.prototype.deactivateTextInput = function () {
    this.isTextInputActive = false
    this.refreshMode()
}

seatsio.EditableValue.prototype.refreshMode = function () {
    if (this.isTextInputActive) {
        this.element().addClass('mode-valueInput').removeClass('mode-valueLabel')
    } else {
        this.element().removeClass('mode-valueInput').addClass('mode-valueLabel')
    }
}

seatsio.EditableValue.prototype.appendListeners = function () {
    var self = this
    var onMouseUp = function () {
        $(window).off('mousemove', self.onMouseMove.bind(self))
    }

    self.element()
        .on('mousedown', function (e) {
            if (self.isTextInputActive) return

            self.moveStartValue = self.value
            self.moveStartX = e.screenX
            self.isScrubbing = false
            $('#chartDesignerWrapper').addClass('scrubbingActive')
            $(window).on('mousemove', self.onMouseMove.bind(self))
        })
        .on('mouseup', function (e) {
            if (!self.isScrubbing && !self.isTextInputActive) {
                self.activateTextInput()
            }
        })

    $(window).on('mouseup', function (e) {
        $('#chartDesignerWrapper').removeClass('scrubbingActive', 'scrubbing-minReached', 'scrubbing-maxReached')
        $(window).off('mousemove')
        $(window).off('mouseup', onMouseUp)
    })

    self.element().children('.valueInput').on('blur', function (e) {
        self.deactivateTextInput()
    }).on('keydown', function (e) {
        if (e.keyCode === 13) self.deactivateTextInput()
    }).on('change', function (e) {
        var value = parseInt(e.target.value)
        if (isNaN(value)) {
            self.refreshElementValue()
        } else {
            self.updateValue(value)
        }
    })
}

seatsio.EditableValue.prototype.setValue = function (value) {
    this.value = value
    this.refreshElementValue()
    return this
}

seatsio.EditableValue.prototype.setMin = function (value) {
    this.min = value
    this.element().children('.valueInput').attr('min', this.min)
    return this
}

seatsio.EditableValue.prototype.setMax = function (value) {
    this.max = value
    this.element().children('.valueInput').attr('max', this.max)
    return this
}

seatsio.EditableValue.prototype.refreshElementValue = function () {
    this.element().children('.valueLabel').html(this.value + (this.unit ? this.unit : ''))
    this.element().children('.valueInput').val(this.value)
}

seatsio.History = function (activeStateChangedCallback) {
    this.states = []
    this.activeStateIndex = -1
    this.activeStateChangedCallback = activeStateChangedCallback
    this.stateLimit = 50
}

seatsio.History.prototype.changeState = function (state) {
    if (this.isSameAsActiveState(state)) {
        return false
    }
    this.states = this.states.slice(0, this.activeStateIndex + 1)
    this.states.push(state)
    if (this.states.length > this.stateLimit) {
        this.states.shift()
    } else {
        this.activeStateIndex++
    }
    this.activeStateChangedCallback(this)
    return true
}

seatsio.History.prototype.getActiveState = function () {
    this.checkForActiveState()
    return this.states[this.activeStateIndex]
}

seatsio.History.prototype.isSameAsActiveState = function (state) {
    if (this.noActiveState()) {
        return false
    }
    return this.getActiveState() === state
}

seatsio.History.prototype.noActiveState = function () {
    return this.activeStateIndex === -1
}

seatsio.History.prototype.checkForActiveState = function () {
    if (this.noActiveState()) {
        throw new Error('no active state')
    }
}

seatsio.History.prototype.goBack = function () {
    this.checkForActiveState()
    if (this.activeStateIndex === 0) {
        throw new Error('already at the start state')
    }
    --this.activeStateIndex
    this.activeStateChangedCallback(this)
    return this.states[this.activeStateIndex]
}

seatsio.History.prototype.canGoBack = function () {
    return this.activeStateIndex > 0
}

seatsio.History.prototype.goForward = function () {
    this.checkForActiveState()
    if (this.activeStateIndex === this.states.length - 1) {
        throw new Error('already at the end state')
    }
    ++this.activeStateIndex
    this.activeStateChangedCallback(this)
    return this.states[this.activeStateIndex]
}

seatsio.History.prototype.canGoForward = function () {
    return this.activeStateIndex < this.states.length - 1
}

seatsio.StatusChanger = function (designer) {
    this.designer = designer
}

seatsio.StatusChanger.prototype.publishDraft = function () {
    return this.designer.v2Client.publishDraft(this.designer.chartKey)
        .then(() => this.designer.onChartPublished())
}

seatsio.StatusChanger.prototype.discardDraft = function () {
    return this.designer.v2Client.discardDraft(this.designer.chartKey)
}

seatsio.StateChangeDetector = function (serializableObject, listeners) {
    this.serializableObject = serializableObject
    this.listeners = listeners
    this.previousState = null
    this.resultOfPreviousCycle = $.when()
    this.started = false
    this.paused = false
}

seatsio.StateChangeDetector.prototype.start = function (state) {
    this.previousState = state
    this.scheduleStateChangeCheck()
    this.started = true
}

seatsio.StateChangeDetector.prototype.pause = function () {
    this.paused = true
}

seatsio.StateChangeDetector.prototype.resume = function () {
    this.paused = false
}

seatsio.StateChangeDetector.prototype.scheduleStateChangeCheck = function (timeout) {
    if (!timeout) {
        timeout = 1000
    }
    setTimeout(() => {
        if (this.paused) {
            this.scheduleStateChangeCheck()
        } else {
            this.actOnStateChangeWhenPreviousCycleDone()
                .then(
                    () => this.scheduleStateChangeCheck(),
                    () => this.scheduleStateChangeCheck(10000)
                )
        }
    }, timeout)
}

seatsio.StateChangeDetector.prototype.actOnStateChangeWhenPreviousCycleDone = function () {
    return this.resultOfPreviousCycle.then(this._actOnStateChangeAndStoreResult.bind(this), this._actOnStateChangeAndStoreResult.bind(this))
}

seatsio.StateChangeDetector.prototype._actOnStateChangeAndStoreResult = function () {
    this.resultOfPreviousCycle = this._actOnStateChange()
    return this.resultOfPreviousCycle
}

seatsio.StateChangeDetector.prototype._actOnStateChange = function () {
    if (!this.started) {
        return $.when()
    }
    var currentState = this.serializableObject.serialize()
    if (this.previousState === currentState) {
        return $.when()
    }
    var deferreds = this.listeners.map(function (listener) {
        return listener(currentState)
    })
    var me = this
    return $.when.apply($, deferreds)
        .then(function () {
            me.previousState = currentState
        })
}

seatsio.TextsBboxCache = function (designer) {
    this.designer = designer
    this.cache = new LRUCache(5000)
}

seatsio.TextsBboxCache.prototype.getBboxDimensions = function (text, fontSize, bold, rotationAngle) {
    var parsedText = whitespaceToNonBreakingSpaces(text)
    var cacheKey = this.cacheKey(parsedText, fontSize, bold, rotationAngle)
    if (!this.cache.get(cacheKey)) {
        var bbox = this.computeBbox(parsedText, fontSize, bold, rotationAngle)
        this.cache.put(cacheKey, { width: bbox.width, height: bbox.height })
    }
    return this.cache.get(cacheKey)
}

seatsio.TextsBboxCache.prototype.cacheKey = function (text, fontSize, bold, rotationAngle) {
    return fontSize + '|' + (bold ? 'b' : '') + '|' + rotationAngle + '|' + text
}

seatsio.TextsBboxCache.prototype.computeBbox = function (text, fontSize, bold, rotationAngle) {
    var tmpText = this.designer.drawer.text(0, 0, text,
        {
            'font-size': fontSize,
            'font-family': seatsio.TextInput.defaultFontFamily,
            'font-weight': bold ? 'bold' : 'normal'
        })
    tmpText.rotate(rotationAngle)
    var bbox = tmpText.rbox()
    tmpText.remove()
    return bbox
}

seatsio.RowsUtil = {}

seatsio.RowsUtil.medianRotationAngle = function (rows) {
    const angles = rows
        .map(row => new seatsio.Ray(row.getCurveGhostPoint1(), row.getCurveGhostPoint2()).angle())
    return median(angles)
}

seatsio.RowsUtil.mostCommonAngle = function (rows) {
    let mostCommonAngles = {}
    rows.forEach(row => {
        let rotation = row.getRotation()
        mostCommonAngles[rotation] = (mostCommonAngles[rotation] || 0) + 1
    })
    let mostCommonAngle = Object.keys(mostCommonAngles).reduce((a, b) => mostCommonAngles[a] > mostCommonAngles[b] ? a : b)
    return {
        angle: mostCommonAngle,
        count: mostCommonAngles[mostCommonAngle]
    }
}

seatsio.RowsUtil.center = function (rows) {
    return seatsio.Bbox.mergedFromObjects(rows).center()
}

seatsio.RowsUtil.leftPoint = function (rows) {
    return rows.reduce((point, row) => {
        let firstCenter = row.firstChair().center()
        let lastCenter = row.lastChair().center()
        let chairCenter = firstCenter.x < lastCenter.x ? firstCenter : lastCenter
        return !point || chairCenter.x < point.x ? chairCenter : point
    }, null)
}

seatsio.RowsUtil.rightPoint = function (rows) {
    return rows.reduce((point, row) => {
        let firstCenter = row.firstChair().center()
        let lastCenter = row.lastChair().center()
        let chairCenter = firstCenter.x > lastCenter.x ? firstCenter : lastCenter
        return !point || chairCenter.x > point.x ? chairCenter : point
    }, null)
}

seatsio.RowsUtil.getRowSpacing = function (rows) {
    if (rows.length < 2) return
    const RC = seatsio.RowCurver
    const rowsMedianRotationAngle = seatsio.RowsUtil.medianRotationAngle(rows)
    const rowsCenter = seatsio.RowsUtil.center(rows)

    const horizontalDecomposedRows = rows
        .map(row => RC.decompose(row))
        .map(nonHorizontalDecomposedRow => RC.rotateBy(nonHorizontalDecomposedRow, -rowsMedianRotationAngle, rowsCenter))
        .map(quasiHorizontalDecomposedRow => RC.rotateUntilHorizontal(quasiHorizontalDecomposedRow))

    let orderedDecomposedRows = horizontalDecomposedRows.sort((a, b) => a.chairCenters[0].y - b.chairCenters[0].y)
    let firstDecomposedRow = orderedDecomposedRows[0]
    let lastDecomposedRow = orderedDecomposedRows[orderedDecomposedRows.length - 1]
    let distanceFromFirstToLastRow = lastDecomposedRow.chairCenters[0].y - firstDecomposedRow.chairCenters[0].y
    return distanceFromFirstToLastRow / (rows.length - 1) - seatsio.Chair.width
}

seatsio.RowCurver = function (rows) {
    this.rows = rows
}

seatsio.RowCurver.prototype.doCurve = function (amount) {
    const RC = seatsio.RowCurver
    const rowsMedianRotationAngle = seatsio.RowsUtil.medianRotationAngle(this.rows)
    const rowsCenter = seatsio.RowsUtil.center(this.rows)

    const horizontalDecomposedRows = this.rows
        .map(row => RC.decompose(row))
        .map(nonHorizontalDecomposedRow => RC.rotateBy(nonHorizontalDecomposedRow, -rowsMedianRotationAngle, rowsCenter))
        .map(quasiHorizontalDecomposedRow => RC.rotateUntilHorizontal(quasiHorizontalDecomposedRow))

    const rowsMinX = RC.minChairX(horizontalDecomposedRows)
    const rowsMaxX = RC.maxChairX(horizontalDecomposedRows)

    horizontalDecomposedRows
        .map(horizontalDecomposedRow => RC.updateCurveGhostPoints(horizontalDecomposedRow, rowsMinX, rowsMaxX))
        .map(horizontalDecomposedRow => RC.curve(horizontalDecomposedRow, amount))
        .map(horizontalCurvedDecomposedRow => RC.rotateBy(horizontalCurvedDecomposedRow, rowsMedianRotationAngle, rowsCenter))
        .forEach(curvedDecomposedRow => RC.applyCurving(curvedDecomposedRow, amount))
}

seatsio.RowCurver.decompose = function (row) {
    return {
        curveGhostPoint1: row.getCurveGhostPoint1(),
        curveGhostPoint2: row.getCurveGhostPoint2(),
        chairCenters: row.getChairs().map(chair => chair.center()),
        originalRow: row
    }
}

seatsio.RowCurver.rotateBy = function (decomposedRow, angle, rotationCenter) {
    decomposedRow.curveGhostPoint1 = decomposedRow.curveGhostPoint1.rotateAround(rotationCenter, angle)
    decomposedRow.curveGhostPoint2 = decomposedRow.curveGhostPoint2.rotateAround(rotationCenter, angle)
    decomposedRow.chairCenters = decomposedRow.chairCenters.map(center => center.rotateAround(rotationCenter, angle))
    return decomposedRow
}

seatsio.RowCurver.rotateUntilHorizontal = function (decomposedRow) {
    const angle = new seatsio.Ray(decomposedRow.curveGhostPoint1, decomposedRow.curveGhostPoint2).angle()
    const angleToBecomeHorizontal = 360 - angle
    const rotationCenter = decomposedRow.curveGhostPoint1.averageWith(decomposedRow.curveGhostPoint2)
    seatsio.RowCurver.rotateBy(decomposedRow, angleToBecomeHorizontal, rotationCenter)
    return decomposedRow
}

seatsio.RowCurver.minChairX = function (decomposedRows) {
    return decomposedRows
        .flatMap(decomposedRow => decomposedRow.chairCenters)
        .map(center => center.x)
        .reduce(function (minX, x) {
            if (x < minX) {
                return x
            }
            return minX
        }, Infinity)
}

seatsio.RowCurver.maxChairX = function (decomposedRows) {
    return decomposedRows
        .flatMap(decomposedRow => decomposedRow.chairCenters)
        .map(center => center.x)
        .reduce(function (maxX, x) {
            if (x > maxX) {
                return x
            }
            return maxX
        }, -Infinity)
}

seatsio.RowCurver.longestRowSeatCount = function (decomposedRows) {
    const seatCounts = decomposedRows.map(decomposedRow => decomposedRow.chairCenters.length)
    return Math.max(...seatCounts)
}

seatsio.RowCurver.updateCurveGhostPoints = function (horizontalDecomposedRow, minX, maxX) {
    horizontalDecomposedRow.curveGhostPoint1 = horizontalDecomposedRow.curveGhostPoint1.withX(minX)
    horizontalDecomposedRow.curveGhostPoint2 = horizontalDecomposedRow.curveGhostPoint2.withX(maxX)
    return horizontalDecomposedRow
}

seatsio.RowCurver.calculateCurveCenterPoint = function (horizontalDecomposedRow, amount) {
    return {
        x: (horizontalDecomposedRow.curveGhostPoint1.x + horizontalDecomposedRow.curveGhostPoint2.x) / 2,
        y: horizontalDecomposedRow.curveGhostPoint1.y + (-amount * 8)
    }
}

seatsio.RowCurver.curve = function (horizontalDecomposedRow, amount) {
    const leftGhostPoint = horizontalDecomposedRow.curveGhostPoint1
    const rightGhostPoint = horizontalDecomposedRow.curveGhostPoint2
    const centerCurvePoint = seatsio.RowCurver.calculateCurveCenterPoint(horizontalDecomposedRow, amount)
    const leftCurvePoint = horizontalDecomposedRow.chairCenters[0]
    const rightCurvePoint = horizontalDecomposedRow.chairCenters.slice(-1)[0]
    const calculateChordPercentage = function (point) {
        return (point.x - leftGhostPoint.x) / (rightGhostPoint.x - leftGhostPoint.x)
    }
    const leftCurvePointPercentage = calculateChordPercentage(leftCurvePoint)
    const rightCurvePointPercentage = calculateChordPercentage(rightCurvePoint)

    const curvePath = SVG().path('M' + leftGhostPoint.x + ',' + leftGhostPoint.y + 'Q' + centerCurvePoint.x + ',' + centerCurvePoint.y + ' ' + rightGhostPoint.x + ', ' + rightGhostPoint.y)
    const curve = new Bezier(leftGhostPoint.x, leftGhostPoint.y, centerCurvePoint.x, centerCurvePoint.y, rightGhostPoint.x, rightGhostPoint.y)

    const leftGhostCurveLength = curve.split(leftCurvePointPercentage).left.length()
    const segmentLength = seatsio.RowCurver.segmentLength(horizontalDecomposedRow, leftCurvePointPercentage, rightCurvePointPercentage, curve)

    horizontalDecomposedRow.chairCenters = horizontalDecomposedRow.chairCenters.map((chairCenter, index) => {
        const point = curvePath.pointAt(leftGhostCurveLength + segmentLength * index)
        return chairCenter.withX(point.x).withY(point.y)
    })
    return horizontalDecomposedRow
}

seatsio.RowCurver.segmentLength = function (horizontalDecomposedRow, leftCurvePointPercentage, rightCurvePointPercentage, curve) {
    if (horizontalDecomposedRow.chairCenters.length === 1) {
        return 0
    }

    const curveLength = curve.split(leftCurvePointPercentage, rightCurvePointPercentage).length()
    const numberOfSegments = horizontalDecomposedRow.chairCenters.length - 1
    return curveLength / numberOfSegments
}

seatsio.RowCurver.applyCurving = function (curvedDecomposedRow, amount) {
    curvedDecomposedRow.originalRow.applyCurving(
        amount,
        curvedDecomposedRow.curveGhostPoint1,
        curvedDecomposedRow.curveGhostPoint2,
        curvedDecomposedRow.chairCenters
    )
}

seatsio.RowSmoothener = function (rows, designer) {
    this.rows = rows
    this.designer = designer
}

seatsio.RowSmoothener.prototype.smoothen = function (smoothness, preview = false) {
    this.rows.forEach(row => {
        let flattenedOriginalPoints = this.flatten(row.points)
        if (smoothness == null) {
            smoothness = row.smoothness || seatsio.Row.DEFAULT_SMOOTHNESS
        }
        let newPoints = this.unflatten(this.calculateCurvePoints(flattenedOriginalPoints, smoothness))
        row.smoothen(newPoints, smoothness, preview)
    })
}

seatsio.RowSmoothener.prototype.unsmoothen = function () {
    this.rows.forEach(row => {
        row.unsmoothen()
    })
}

seatsio.RowSmoothener.prototype.flatten = function (points) {
    return points.flatMap(p => [p.x, p.y])
}

seatsio.RowSmoothener.prototype.unflatten = function (points) {
    let result = []
    for (let i = 0; i < points.length; i++) {
        result.push(new seatsio.Point(points[i], points[i + 1]))
        i++
    }
    return result
}

seatsio.RowSmoothener.prototype.calculateCurvePoints = function (originalPoints, smoothness) {
    // from https://github.com/088haizi/cardinal-spline-js/blob/master/src/curve_calc.js
    const numberOfSegments = 12
    const tension = smoothness / 100

    let i = 1
    let l = originalPoints.length
    let rPos = 0
    let rLen = (l - 2) * numberOfSegments + 2
    let result = new Float32Array(rLen)
    let cache = new Float32Array((numberOfSegments + 2) * 4)
    let cachePtr = 4

    let points
    points = originalPoints.slice(0)
    points.unshift(originalPoints[1]) // copy 1. point and insert at beginning
    points.unshift(originalPoints[0])
    points.push(originalPoints[l - 2], originalPoints[l - 1]) // duplicate end-points

    // cache inner-loop calculations as they are based on t alone
    cache[0] = 1 // 1,0,0,0

    for (; i < numberOfSegments; i++) {
        let st = i / numberOfSegments
        let st2 = st * st
        let st3 = st2 * st
        let st23 = st3 * 2
        let st32 = st2 * 3

        cache[cachePtr++] = st23 - st32 + 1 // c1
        cache[cachePtr++] = st32 - st23 // c2
        cache[cachePtr++] = st3 - 2 * st2 + st // c3
        cache[cachePtr++] = st3 - st2 // c4
    }

    cache[++cachePtr] = 1// 0,1,0,0

    parse(points, cache, l)

    function parse (pts, cache, l) {
        for (let i = 2, t; i < l; i += 2) {
            let pt1 = pts[i]
            let pt2 = pts[i + 1]
            let pt3 = pts[i + 2]
            let pt4 = pts[i + 3]

            let t1x = (pt3 - pts[i - 2]) * tension
            let t1y = (pt4 - pts[i - 1]) * tension
            let t2x = (pts[i + 4] - pt1) * tension
            let t2y = (pts[i + 5] - pt2) * tension

            for (t = 0; t < numberOfSegments; t++) {
                let c = t << 2 // t * 4;

                let c1 = cache[c]
                let c2 = cache[c + 1]
                let c3 = cache[c + 2]
                let c4 = cache[c + 3]

                result[rPos++] = c1 * pt1 + c2 * pt3 + c3 * t1x + c4 * t2x
                result[rPos++] = c1 * pt2 + c2 * pt4 + c3 * t1y + c4 * t2y
            }
        }
    }

    // add last point
    l = originalPoints.length - 2
    result[rPos++] = originalPoints[l]
    result[rPos] = originalPoints[l + 1]

    return result
}

seatsio.RowSorter = function () {
}

seatsio.RowSorter.prototype.sort = function (rows) {
    let rowsMedianRotationAngle = seatsio.RowsUtil.medianRotationAngle(rows)
    let rowsCenter = seatsio.RowsUtil.center(rows)

    let horizontalDecomposedRows = rows
        .map(row => seatsio.RowSorter.decompose(row))
        .map(nonHorizontalDecomposedRow => seatsio.RowSorter.rotateBy(nonHorizontalDecomposedRow, -rowsMedianRotationAngle, rowsCenter))

    let sortedRows = _.sortBy(horizontalDecomposedRows, decomposedRow => decomposedRow.center.y)
        .map(decomposedRow => decomposedRow.originalRow)

    if (rowsMedianRotationAngle >= 90 && rowsMedianRotationAngle < 270) {
        return _.reverse(sortedRows)
    }
    return sortedRows
}

seatsio.RowSorter.decompose = function (row) {
    return {
        center: row.getCenter(),
        originalRow: row
    }
}

seatsio.RowSorter.rotateBy = function (decomposedRow, angle, rotationCenter) {
    decomposedRow.center = decomposedRow.center.rotateAround(rotationCenter, angle)
    return decomposedRow
}

seatsio.PolygonDrawingSnapper = function (designer, flags = []) {
    this.designer = designer
    this.flags = flags
}

seatsio.PolygonDrawingSnapper.prototype.snap = function (previousPoint, point, points) {
    // lastCornerPoint is currently only used for lines, whereas firstCorner checks are used for closed shapes
    if (this.flags.includes('lastCornerPoint')) {
        if (points && this.closeToLastPoint(point, points)) {
            return this.snapped(previousPoint, 'lastCorner')
        }
    } else if (points && this.closeToFirstPoint(point, points)) {
        return this.snapped(points.first(), 'firstCorner')
    }
    if (this.flags.includes('closestCornerPoint')) {
        let closestCornerPoint = this.closeEnoughCornerPoint(point)
        if (closestCornerPoint && !this.designer.altWasPressed) {
            return this.snapped(closestCornerPoint, 'closestCorner')
        }
    }
    if (previousPoint && this.designer.shiftWasPressed) {
        let ray = new seatsio.Ray(previousPoint, point).snapToAngle(45, 0)
        if (seatsio.ChartDesigner.snapToGridEnabled) {
            ray = ray.snapLengthToMultipleOf(seatsio.Point.SNAP_PRECISION)
        }
        return this.snapped(ray.end, 'angle')
    }
    if (!this.designer.altWasPressed) {
        let [doubleAlignedPoint, firstAlignedRay, secondAlignedRay] = this.alignedRayDoubleIntersectingPoint(point, this.getAllRaysGrouped(point))
        if (doubleAlignedPoint) {
            return this.snapped(doubleAlignedPoint, 'fullyAligned', firstAlignedRay, secondAlignedRay)
        }

        let verticallyAlignedPoint = this.verticallyAlignedPoint(point, points)
        let horizontallyAlignedPoint = this.horizontallyAlignedPoint(point, points)

        let [alignedPoint, alignedRay] = this.alignedRayIntersectingPoint(point, this.getAllRays(point))
        if (alignedPoint) {
            if (verticallyAlignedPoint) {
                return this.snapped(verticallyAlignedPoint.withY(alignedPoint.y), 'rayAlignedAndVertical', alignedRay)
            }
            if (horizontallyAlignedPoint) {
                return this.snapped(horizontallyAlignedPoint.withX(alignedPoint.x), 'rayAlignedAndHorizontal', alignedRay)
            }
            return this.snapped(alignedPoint, 'rayAligned', alignedRay)
        }

        if (points && points.length > 2) {
            let [alignedToStartPoint, alignedToStartRay] = this.alignedSidesToStartingPoint(point, points)
            if (alignedToStartPoint) {
                return this.snapped(alignedToStartPoint, 'rayAligned', alignedToStartRay)
            }
        }

        if (verticallyAlignedPoint && horizontallyAlignedPoint) {
            return this.snapped(verticallyAlignedPoint.withY(horizontallyAlignedPoint.y), 'fullyAligned')
        } else if (verticallyAlignedPoint) {
            return this.snapped(verticallyAlignedPoint.withY(point.y), 'verticallyAligned')
        } else if (horizontallyAlignedPoint) {
            return this.snapped(horizontallyAlignedPoint.withX(point.x), 'horizontallyAligned')
        }
    }
    return this.snapped(seatsio.ChartDesigner.snapToGridEnabled ? point.snapToGrid() : point)
}

seatsio.PolygonDrawingSnapper.prototype.getAllRays = function (point) {
    return this.designer.activeSubChart().sections.closestTo(point)
        .flatMap(seatsio.Section.toRays)
}

seatsio.PolygonDrawingSnapper.prototype.getAllRaysGrouped = function (point) {
    return this.designer.activeSubChart().sections.closestTo(point)
        .map(seatsio.Section.toRays)
}

seatsio.PolygonDrawingSnapper.prototype.snapThreshold = function () {
    return this.designer.zoomer.unzoom(7)
}

seatsio.PolygonDrawingSnapper.prototype.closeEnoughCornerPoint = function (point) {
    var closestOtherPolygonPoint = this.designer.activeSubChart().sections.cornerPointClosestTo(point, this.snapThreshold())
    if (closestOtherPolygonPoint && closestOtherPolygonPoint.point.distanceToPoint(point) < this.snapThreshold()) {
        return closestOtherPolygonPoint
    }
}

seatsio.PolygonDrawingSnapper.prototype.horizontallyAlignedPoint = function (point, points) {
    return this.alignedPoint(point, false, points)
}

seatsio.PolygonDrawingSnapper.prototype.verticallyAlignedPoint = function (point, points) {
    return this.alignedPoint(point, true, points)
}

seatsio.PolygonDrawingSnapper.prototype.alignedPoint = function (point, vertical = false, points = []) {
    return this.findAlignedPoint(point, vertical, points, this.designer.zoomer.unzoom(500))
}

seatsio.PolygonDrawingSnapper.prototype.findAlignedPoint = function (point, vertical, points, maxDistance) {
    return points.reduce((alignedPoint, comparisonPoint) => {
        let axisAlpha = vertical ? comparisonPoint.verticalDistanceTo(point) : comparisonPoint.horizontalDistanceTo(point)
        if (axisAlpha < this.snapThreshold() && comparisonPoint.distanceToPoint(point) < maxDistance) {
            return comparisonPoint
        }
        return alignedPoint
    }, null)
}

seatsio.PolygonDrawingSnapper.prototype.alignedRayDoubleIntersectingPoint = function (point, groupedRays) {
    const snapTreshold = this.designer.zoomer.unzoom(6)
    const rayEnlargement = this.designer.zoomer.unzoom(400)
    groupedRays = groupedRays.map(group => group.map(ray => ray.enlargeOnBothSides(rayEnlargement)))

    let intersectingRays = groupedRays
        .flatMap(group => {
            let otherRays = groupedRays.filter(g => g !== group).flatMap(g => g)
            return this.getIntersectingRaysAndPoint(group, otherRays)
        })

    if (intersectingRays.length === 0) {
        return [null, null, null]
    }

    intersectingRays.forEach(intersectingRayData => {
        intersectingRayData.closestIntersection = intersectingRayData.intersections.reduce((r, intersection) =>
            intersection.point.distanceToPoint(point) < r.point.distanceToPoint(point) ? intersection : r,
        intersectingRayData.intersections[0]
        )
    })
    let closestIntersectingRay = intersectingRays.reduce((r, intersection) =>
        intersection.closestIntersection.point.distanceToPoint(point) < r.closestIntersection.point.distanceToPoint(point) ? intersection : r,
    intersectingRays[0]
    )

    let intersectingRay = closestIntersectingRay.ray
    let intersectingPoint = closestIntersectingRay.closestIntersection.point
    if (!intersectingRay || point.distanceToPoint(intersectingPoint) > snapTreshold) {
        return [null, null, null]
    }

    let intersectingSecondRay = closestIntersectingRay.closestIntersection.targetRay
    return [intersectingPoint, intersectingRay.enlargeOnBothSides(-rayEnlargement), intersectingSecondRay.enlargeOnBothSides(-rayEnlargement)]
}

seatsio.PolygonDrawingSnapper.prototype.alignedRayIntersectingPoint = function (point, rays) {
    const snapTreshold = this.designer.zoomer.unzoom(6)
    const rayEnlargement = this.designer.zoomer.unzoom(800)
    let cursorRays = [
        new seatsio.Ray(point.addToX(-snapTreshold), point.addToX(snapTreshold)),
        new seatsio.Ray(point.addToY(-snapTreshold), point.addToY(snapTreshold))
    ]
    rays = rays.map(ray => ray.enlargeOnBothSides(rayEnlargement))

    let intersectingRays = rays
        .filter(ray => this.findIntersectingRayInRayArray(cursorRays, ray))
        .sort((rayA, rayB) => rayA.distanceFromCenterToPoint(point) - rayB.distanceFromCenterToPoint(point))
    let intersectingRay = intersectingRays[0]
    if (!intersectingRay) {
        return [null, null]
    }

    let intersectingPoint = this.findIntersectionPointInRayArray(cursorRays, intersectingRay)
    return [intersectingPoint, intersectingRay.enlargeOnBothSides(-rayEnlargement)]
}

seatsio.PolygonDrawingSnapper.prototype.alignedSidesToStartingPoint = function (point, points) {
    const snapTreshold = this.designer.zoomer.unzoom(6)
    const rayEnlargement = this.designer.zoomer.unzoom(400)
    let cursorRays = [
        new seatsio.Ray(point.addToX(-snapTreshold), point.addToX(snapTreshold)),
        new seatsio.Ray(point.addToY(-snapTreshold), point.addToY(snapTreshold))
    ]
    let rays = points.map((point, i) => points[i + 1] ? new seatsio.Ray(point, points[i + 1]) : null)
        .nonFalsies()
        .map(ray => ray.add(points[0].subtract(ray.origin)))
        .map(ray => ray.enlargeOnBothSides(rayEnlargement))

    let intersectingRays = rays.filter(ray => this.findIntersectingRayInRayArray(cursorRays, ray))

    let intersectingRay = intersectingRays[0]
    if (!intersectingRay) {
        return [null, null]
    }

    let intersectingPoint = this.findIntersectionPointInRayArray(cursorRays, intersectingRay)
    if (point.distanceToPoint(intersectingPoint) > snapTreshold) {
        return [null, null]
    }

    return [intersectingPoint, intersectingRay.enlargeOnBothSides(-rayEnlargement)]
}

seatsio.PolygonDrawingSnapper.prototype.findIntersectingRayInRayArray = function (sourceRays, targetRay) {
    return sourceRays.find(ray => ray.intersectionWithRay(targetRay))
}

seatsio.PolygonDrawingSnapper.prototype.getIntersectingRaysAndPoint = function (sourceRays, targetRays) {
    return sourceRays.map(ray => {
        return {
            ray,
            intersections: targetRays.map(targetRay => {
                let point = ray.intersectionWithRay(targetRay)
                return point ? { targetRay, point } : null
            }).filter(intersection => intersection)
        }
    }).filter(intersectionData => intersectionData.intersections.length > 0)
}

seatsio.PolygonDrawingSnapper.prototype.findIntersectionPointInRayArray = function (rays, targetRay) {
    return rays.reduce((r, ray) => r || ray.intersectionWithRay(targetRay), null)
}

seatsio.PolygonDrawingSnapper.prototype.closeToFirstPoint = function (point, points) {
    if (points.length < 3) {
        return false
    }
    return points.first().distanceToPoint(point) < this.snapThreshold()
}

seatsio.PolygonDrawingSnapper.prototype.closeToLastPoint = function (point, points) {
    if (points.length < 2) {
        return false
    }
    return points.last().distanceToPoint(point) < this.snapThreshold()
}

seatsio.PolygonDrawingSnapper.prototype.snapped = function (point, snapType, snapRay, snapSecondRay) {
    return {
        snapCorner: point.type !== 'Point' ? point : null,
        snapPoint: point.type === 'Point' ? point : point.point,
        snapType,
        snapRay,
        snapSecondRay
    }
}

seatsio.PolygonDrawingSnapper.snapColors = {
    firstCorner: '#FF0BA6',
    closestCorner: '#FF0BA6',
    rayAligned: seatsio.PositionGuidesSupport.GUIDE_COLORS.magenta,
    rayAlignedAndVertical: seatsio.PositionGuidesSupport.GUIDE_COLORS.magenta,
    rayAlignedAndHorizontal: seatsio.PositionGuidesSupport.GUIDE_COLORS.magenta,
    verticallyAligned: seatsio.PositionGuidesSupport.GUIDE_COLORS.green,
    horizontallyAligned: seatsio.PositionGuidesSupport.GUIDE_COLORS.green,
    fullyAligned: seatsio.PositionGuidesSupport.GUIDE_COLORS.magenta,
    angle: '#FFA700',
    default: '#0087FF'
}

class Drawer {
    constructor (designer) {
        this.designer = designer
    }

    circle (cx, cy, r, attrs) {
        let circle = this.designer.svg.circle(r * 2)
            .attr({
                cx: cx,
                cy: cy,
                ...attrs
            })
        circle.raphaelElement = this.designer.paper.circleElement(circle.node, cx, cy, r)
        return circle
    }

    image (url, width, height, attrs) {
        let image = this.designer.svg.image(url)
            .size(width, height)
            .attr(attrs || {})
        image.raphaelElement = this.designer.paper.imageElement(image.node, url, attrs.x, attrs.y, width, height)
        return image
    }

    text (x, y, text, attrs) {
        let t = this.designer.svg
            .plain(text)
            .rebuild(false) // performance
            .attr({
                x: x,
                y: y,
                'text-anchor': 'middle',
                'dominant-baseline': 'central',
                ...attrs
            })
        t.raphaelElement = this.designer.paper.textElement(t.node, x, y, text)
        return t
    }

    rect (x, y, width, height, cornerRadius, attrs) {
        let rect = this.designer.svg.rect(width, height)
            .attr({
                rx: cornerRadius,
                ry: cornerRadius,
                r: cornerRadius,
                fill: 'none',
                stroke: '#000',
                x,
                y,
                ...attrs
            })
        rect.raphaelElement = this.designer.paper.pathElement(rect.node, rect)
        return rect
    }

    path (p, attrs) {
        let path = this.designer.svg.path(p)
            .attr({
                fill: 'none',
                stroke: '#000',
                ...attrs
            })
        path.raphaelElement = this.designer.paper.pathElement(path.node, p)
        return path
    }

    ellipse (x, y, radius1, radius2, attrs) {
        let ellipse = this.designer.svg.ellipse(radius1 * 2, radius2 * 2)
            .attr({
                cx: x,
                cy: y,
                fill: 'none',
                stroke: '#000',
                ...attrs
            })
        ellipse.raphaelElement = this.designer.paper.ellipseElement(ellipse.node, x, y, radius1, radius1)
        return ellipse
    }

    group () {
        const group = this.designer.svg.group()
        group.raphaelElement = this.designer.paper.set()
        return group
    }
}

seatsio.TableMousePointer = function (designer) {
    this.designer = designer
    this.table = null
    this.startPoint = null
}

seatsio.TableMousePointer.prototype.showAt = function (point, f) {
    if (!this.table) {
        this.startPoint = point
        this.table = f(point, this.designer.activeSubChart()).draw().disableSelection().hideLabelAndChildLabels().drawPositionGuides().allElementsSet().startTransformation()
    } else {
        this.table.transform(this.startPoint.vectorTo(point, this.designer).asTranslation())
    }
}

seatsio.TableMousePointer.prototype.hide = function () {
    if (this.table) {
        this.table.remove()
        this.table = null
        this.startPoint = null
    }
}

seatsio.Tables = function (subChart) {
    this.subChart = subChart
    this.designer = subChart.designer
    this.tables = []
}

seatsio.Tables.prototype.add = function (table) {
    this.tables.push(table)
    table.refreshOutOfBounds(true)
    this.designer.requestStatsUpdate()
    return table
}

seatsio.Tables.prototype.clone = function (subChart) {
    var tables = new seatsio.Tables(subChart)
    tables.tables = this.tables.map(function (table) {
        return table.clone(subChart)
    })
    return tables
}

seatsio.Tables.prototype.draw = function (center, f) {
    var table = f(center, this.subChart)
    table.label = seatsio.Tables.generateLabel()
    table.draw()
    table.playFlash()
    return this.add(table)
}

seatsio.Tables.prototype.remove = function (table) {
    table.undraw()
    this.tables.remove(table)
    this.designer.requestStatsUpdate()
}

seatsio.Tables.prototype.allElementsSet = function () {
    return this.tables.map(function (table) {
        return table.allElementsSet()
    })
}

seatsio.Tables.labelCounter = 1

seatsio.Tables.generateLabel = function () {
    return (seatsio.Tables.labelCounter++).toString()
}

seatsio.Tables.chairWidth = 20
seatsio.Tables.chairRadius = seatsio.Tables.chairWidth / 2
seatsio.Tables.awayFromTableOffset = seatsio.Tables.chairRadius * 0.7

seatsio.Tables.fromJson = function (tablesJson, subChart) {
    var tables = new seatsio.Tables(subChart)
    tables.tables = tablesJson.map(function (jsonTable) {
        if (jsonTable.type === 'rectangular') {
            return seatsio.RectTable.fromJson(jsonTable, subChart)
        } else {
            return seatsio.RoundTable.fromJson(jsonTable, subChart)
        }
    })
    return tables
}

seatsio.Tables.createRoundTable = function (center, subChart) {
    const designer = subChart.designer
    let table = new seatsio.RoundTable(center, undefined, subChart)
    table.isOutOfBounds = false
    table.setNumberOfChairs(designer.getToolProperty('RoundTable.chairs'))
    table.applySeatLabeling('SimpleNumbers', 0, false)
    return table
}

seatsio.Tables.createRoundTableMousePointer = function (center, subChart) {
    let table = new seatsio.RoundTable(center, undefined, subChart, true)
    table.setNumberOfChairs(subChart.designer.getToolProperty('RoundTable.chairs'))
    return table
}

seatsio.Tables.createRectTable = function (center, subChart) {
    const designer = subChart.designer
    let table = new seatsio.RectTable(center, designer.getToolProperty('RectTable.width'), designer.getToolProperty('RectTable.height'), subChart)
    table.isOutOfBounds = false
    table.setDistribution(Object.assign({}, designer.getToolProperty('RectTable.chairs')))
    table.applySeatLabeling('SimpleNumbers', 0, false)
    return table
}

seatsio.Tables.createRectTableMousePointer = function (center, subChart) {
    const designer = subChart.designer
    let table = new seatsio.RectTable(center, designer.getToolProperty('RectTable.width'), designer.getToolProperty('RectTable.height'), subChart, true)
    table.setDistribution(Object.assign({}, designer.getToolProperty('RectTable.chairs')))
    return table
}

seatsio.Table = function () {
    this.table = null
    this.chairs = []
    this.label = null
    this.displayLabel = null
    this.center = null
    this.designer = null
    this.subChart = null
    this.rotationAngle = 0
    this.seatLabeling = seatsio.SeatLabeling.createDefaultSeatLabeling()
    this.objectLabeling = seatsio.ObjectLabeling.createDefaultTableLabeling()
    this.sectionLabel = null
    this.sectionDisplayedLabel = null
    this.dummy = false
    this.labelShown = false
    this.bookAsAWhole = false
    this.variableOccupancy = false
    this.viewFromYourSeatImage = null
    this.minOccupancy = 1
    this.published = false
}

seatsio.Table.prototype = new seatsio.Object()

seatsio.Table.prototype.type = 'table'

seatsio.Table.prototype.getInspectorSheets = function () {
    let source = seatsio.Object.prototype.getInspectorSheets.call(this)
    const disabled = source.disabled || []
    if (this.disabledEditingBySafeMode()) {
        disabled.push('ObjectLabeling.label')
        disabled.push('SectionLabeling.sectionLabel')
        disabled.push('SeatLabeling')
        disabled.push('Misc.tableType')
    }
    if (this.anyChairsDisabledEditingBySafeMode()) {
        disabled.push('SeatLabeling.label')
    }
    return Object.assign(source, {
        'SectionLabeling.sectionLabel': this.sectionLabel,
        'SectionLabeling.sectionDisplayedLabel': this.sectionDisplayedLabel,
        'SectionLabeling.isNewObject': !this.published,
        'ObjectLabeling.label': this.hasLabel() ? this.label : null,
        'ObjectLabeling.displayLabel': this.displayLabel,
        'ObjectLabeling.visible': this.labelShown,
        'ObjectLabeling.isNewObject': !this.published,
        'ObjectLabeling.sequence': this.objectLabeling.algoName,
        'ObjectLabeling.prefix': this.objectLabeling.prefix,
        'ObjectLabeling.start': this.objectLabeling.startAtIndex + 1,
        'SeatLabeling.label': this.getAllChildrenLabels(),
        'SeatLabeling.isNewObject': !this.published,
        'SeatLabeling.displayObjectType': this.getSeatDisplayObjectTypes(),
        'SeatLabeling.sequence': this.seatLabeling.algoName,
        'SeatLabeling.inverted': this.seatLabeling.isInverted === true,
        'SeatLabeling.start': this.seatLabeling.startAtIndex + 1,
        'SeatLabeling.useEndAt': this.seatLabeling.useEndAt,
        'Misc.bookAsAWhole': this.bookAsAWhole,
        'Misc.variableOccupancy': this.variableOccupancy,
        'Misc.minOccupancy': this.minOccupancy,
        'Misc.numberOfSeats': this.numberOfChairs(),
        'ViewFromSeat.type': 'table',
        'ViewFromSeat.url': seatsio.Object.viewFromSeatsUrl(this.designer, this.viewFromYourSeatImage),
        'Misc.entrance': this.entrance,
        'Misc.sectionEntrance': this.getSectionEntrance(),
        disabled
    })
}

seatsio.Table.prototype.initTable = function (center, subChart, dummy = false) {
    this.designer = subChart.designer
    this.subChart = subChart
    this.center = center
    this.dummy = dummy
    this.labeler = new seatsio.TableLabel(this, subChart.designer)
    this.overlayIcon = new seatsio.OverlayIcon(this)
    this.init(subChart.designer, true, undefined, dummy)
}

seatsio.Table.prototype.children = seatsio.SeatParent.prototype.children
seatsio.Table.prototype.getChairs = seatsio.SeatParent.prototype.getChairs
seatsio.Table.prototype.getChairsCategoryKeys = seatsio.SeatParent.prototype.getChairsCategoryKeys
seatsio.Table.prototype.getChairsCategories = seatsio.SeatParent.prototype.getChairsCategories
seatsio.Table.prototype.uncategorizedChildren = seatsio.SeatParent.prototype.uncategorizedChildren
seatsio.Table.prototype.numberOfLabeledSeats = seatsio.SeatParent.prototype.numberOfLabeledSeats
seatsio.Table.prototype.applyCategory = seatsio.SeatParent.prototype.applyCategory
seatsio.Table.prototype.removeCategory = seatsio.SeatParent.prototype.removeCategory
seatsio.Table.prototype.enter = seatsio.SeatParent.prototype.enter
seatsio.Table.prototype.applyElementAttributes = seatsio.SeatParent.prototype.applyElementAttributes
seatsio.Table.prototype.anyChairsDisabledEditingBySafeMode = seatsio.SeatParent.prototype.anyChairsDisabledEditingBySafeMode
seatsio.Table.prototype.getAllChildrenLabels = seatsio.SeatParent.prototype.getAllChildrenLabels
seatsio.Table.prototype.applySeatLabeling = seatsio.SeatParent.prototype.applySeatLabeling
seatsio.Table.prototype.applyObjectLabeling = seatsio.SeatParent.prototype.applyObjectLabeling
seatsio.Table.prototype.setSeatLabelingEndAt = seatsio.SeatParent.prototype.setSeatLabelingEndAt
seatsio.Table.prototype.setSeatDisplayObjectType = seatsio.SeatParent.prototype.setSeatDisplayObjectType
seatsio.Table.prototype.getSeatDisplayObjectTypes = seatsio.SeatParent.prototype.getSeatDisplayObjectTypes

seatsio.Table.prototype.setLabelShown = function (labelShown) {
    if (this.labelShown === labelShown) return
    this.labelShown = labelShown
    this.labeler.redraw()
}

seatsio.Table.prototype.getRotation = function () {
    return this.rotationAngle
}

seatsio.Table.prototype.getLabelRotation = function () {
    return 0
}

seatsio.Table.prototype.setRotationAngle = function (val) {
    var me = this
    this.rotationAngle = wrapRotationAround(val)
    this.redrawIfNeeded(function () {
        me.repositionChairs()
    })
}

seatsio.Table.prototype.isBookBySeat = function () {
    return !this.bookAsAWhole && !this.variableOccupancy
}

seatsio.Table.prototype.setBookAsAWhole = function (bookAsAWhole) {
    this.bookAsAWhole = bookAsAWhole
    this.redraw()
}

seatsio.Table.prototype.setSelectionVariableOccupancy = function (variableOccupancy) {
    this.variableOccupancy = variableOccupancy
}

seatsio.Table.prototype.setMinOccupancy = function (minOccupancy) {
    this.minOccupancy = minOccupancy
}

seatsio.Table.prototype.getCenter = function () {
    return this.center
}

seatsio.Table.prototype.setViewFromSeats = function (key) {
    seatsio.Object.prototype.setViewFromSeats.apply(this, [key])
    this.setOverlayIcon()
    this.toggleOverlayIcon()
    this.hideTableLabelWhenVFSIsShown()
}

seatsio.Table.prototype.removeViewFromSeats = function () {
    seatsio.Object.prototype.removeViewFromSeats.apply(this)
    this.toggleOverlayIcon()
    this.showTableLabelWhenVFSIsNotShown()
}

seatsio.Table.prototype.showVFS = function () {
    this.toggleOverlayIcon()
    this.hideTableLabelWhenVFSIsShown()
}

seatsio.Table.prototype.hideVFS = function () {
    this.toggleOverlayIcon()
    this.showTableLabelWhenVFSIsNotShown()
}

seatsio.Table.prototype.toggleOverlayIcon = function () {
    if (!this.subChart.isActive()) return
    if (this.designer.viewFromSeatsShown && this.viewFromYourSeatImage) this.overlayIcon.show()
    else this.overlayIcon.hide()
}

seatsio.Table.prototype.hideTableLabelWhenVFSIsShown = function () {
    if (this.designer.viewFromSeatsShown && this.viewFromYourSeatImage) this.hideLabel()
}

seatsio.Table.prototype.showTableLabelWhenVFSIsNotShown = function () {
    if (!(this.designer.viewFromSeatsShown && this.viewFromYourSeatImage) && this.designer.labelsShown) this.showLabel()
}

seatsio.Table.prototype.setOverlayIcon = function () {
    this.overlayIcon.setIcon('view-from-seats', 'chair-highlight', () => this.designer.uiEvents.showObjectInspectorSheet(this, 'ViewFromSeat'), this.getDisplayLabelOrLabel())
}

seatsio.Table.prototype.centroid = function () {
    return this.center
}

seatsio.Table.prototype.animatedObject = function () {
    return this.table
}

seatsio.Table.prototype.clearSeatLabels = function () {
    this.children().forEach(function (s) {
        s.clearLabel()
    })
}

seatsio.Table.prototype.drawn = function () {
    return this.table
}

seatsio.Table.prototype.determineDrawZIndex = function () {
    if (this.bookAsAWhole) {
        return this.chairs.reduce((zIndex, seat) => Math.max(zIndex, seat.zIndex + 1), this.zIndex)
    }
    return this.zIndex
}

seatsio.Table.prototype.draw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    this.chairs.forEach(chair => chair.draw())
    this.table = this.drawTable()
    if (this.isOutOfBounds) this.applyElementAttributes()
    if (this.viewFromYourSeatImage) {
        this.setOverlayIcon()
        this.overlayIcon.redraw()
        this.toggleOverlayIcon()
        this.hideTableLabelWhenVFSIsShown()
    }
    this.objectDrawn()
    return this
}

seatsio.Table.prototype.undraw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    if (this.table) {
        this.table.remove()
        this.table = null
    }
    this.chairs.forEach(function (chair) {
        chair.undraw()
    })
    this.objectUndrawn()
}

seatsio.Table.prototype.redraw = function () {
    this.undraw()
    this.draw()
}

seatsio.Table.prototype.redrawIfNeeded = function (fn) {
    var wasDrawn = this.drawn()
    if (wasDrawn) {
        this.undraw()
    }
    fn()
    if (wasDrawn) {
        this.draw()
    }
}

seatsio.Table.prototype.positionGuideBBox = function () {
    return seatsio.Bbox.fromView(this.table.rbox(), this.designer)
}

seatsio.Table.prototype.getPositionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRect

seatsio.Table.prototype.moved = function (distance) {
    this.center = this.center.add(distance)
    this.chairs.forEach(function (chair) {
        chair.moved(distance)
    })
    this.refreshOutOfBounds()
    this.redraw()
}

seatsio.Table.prototype.rotated = function (rotationCenter, angle) {
    this.center = this.center.rotateAround(rotationCenter, angle)
    this.chairs.forEach(function (chair) {
        chair.rotated(rotationCenter, angle)
    })
    this.setRotationAngle(this.rotationAngle + angle)
}

seatsio.Table.prototype.labelPosition = function () {
    return this.center
}

seatsio.Table.prototype.determineLabelColor = function () {
    if (this.bookAsAWhole) {
        return seatsio.Color.create(this.determineBaseColor()).increaseContrastBy(5, this.isDarkCanvas()).toCSS()
    } else {
        const intensifyAmount = this.isDarkCanvas() ? 100 : 50
        return seatsio.Color.create(this.determineBaseColor()).intensifyBy(intensifyAmount, this.isDarkCanvas()).toCSS()
    }
}

seatsio.Table.prototype.numberOfUnlabeledSeats = function () {
    return this.numberOfChairs() - this.numberOfLabeledSeats()
}

seatsio.Table.prototype.setNumberOfChairs = function (num) {
    if (num > 0) {
        let category = this.getChairsCategories()[0]
        this.redrawIfNeeded(() => {
            this.chairs = this.chairs.splice(0, num)
            while (this.chairs.length < num) {
                let newChair = new seatsio.Chair(new seatsio.Point(0, 0), this, this.subChart, this.dummy)
                newChair.applyCategory(category)
                newChair.isHighlighted = this.isHighlighted
                this.chairs.push(newChair)
            }
            this.repositionChairs()
            this.applySeatLabeling()
            this.fixMinOccupancyIfNeeded()
        })
    }
    return this
}

seatsio.Table.prototype.visibleElementsSet = function () {
    let set = seatsio.set(this.table, this.positionGuides, this.chairs.map(chair => chair.svgElement()), this.chairs.map(chair => chair.overlayIcon.visibleElementsSet()), this.labeler.asSet())
    if (this.overlayIcon) {
        pushAll(set, this.overlayIcon.visibleElementsSet())
    }
    return set
}

seatsio.Table.prototype.visibleElementsSetWithoutChildren = function () {
    return seatsio.set(this.table)
}

seatsio.Table.prototype.remove = function () {
    this.subChart.tables.remove(this)
}

seatsio.Table.prototype.canBeRemoved = function () {
    return !this.disabledDeletingBySafeMode()
}

seatsio.Table.prototype.removeChair = function (chair) {
}

seatsio.Table.prototype.numberOfChairs = function () {
    return this.chairs.length
}

seatsio.Table.prototype.totalPeopleCapacity = function () {
    return this.numberOfChairs()
}

seatsio.Table.prototype.chairsToJson = function () {
    return this.chairs.map(function (chair) {
        return chair.toJson()
    })
}

seatsio.Table.prototype.determineFlashColor = function () {
    return seatsio.Color.SELECTED_LIGHT.toCSS()
}

seatsio.Table.prototype.determineDefaultColor = function () {
    const chairs = this.getChairs()
    if (this.bookAsAWhole && chairs.length !== 0) {
        const aChair = chairs[0]
        if (aChair.category) {
            return aChair.category.color
        }
    }
    return this.getNonSelectableColor()
}

seatsio.Table.prototype.determineFillColor = function (baseColor = undefined) {
    if (baseColor === undefined) {
        baseColor = this.determineBaseColor()
    }
    if (this.bookAsAWhole) {
        return seatsio.Object.prototype.determineFillColor.apply(this, [baseColor])
    } else {
        return baseColor
    }
}

seatsio.Table.prototype.determineStrokeColor = function () {
    if (this.bookAsAWhole) {
        return seatsio.Object.prototype.determineStrokeColor.apply(this)
    } else {
        return seatsio.Color.create(this.determineBaseColor()).softenedBy(this.isDarkCanvas() ? 35 : 50, this.isDarkCanvas()).toCSS()
    }
}

seatsio.Table.prototype.determineStrokeWidth = function () {
    if (this.bookAsAWhole) {
        return seatsio.Object.prototype.determineStrokeWidth.apply(this)
    } else {
        return 4
    }
}

seatsio.Table.prototype.getNonSelectableColor = function () {
    if (this.bookAsAWhole) {
        return seatsio.Object.NO_CATEGORY_COLOR[this.designer.getCanvasColorScheme()]
    } else {
        return seatsio.Table.NON_BOOKABLE_TABLE_COLOR[this.designer.getCanvasColorScheme()]
    }
}

seatsio.Table.prototype.determineNonHighlightedColor = function () {
    return this.determineDefaultColor()
}

seatsio.Table.prototype.fixMinOccupancyIfNeeded = function () {
    if (this.variableOccupancy && this.minOccupancy > this.numberOfChairs()) {
        this.setMinOccupancy(this.numberOfChairs())
    }
}

seatsio.Table.STROKE_WIDTH = 1
seatsio.Table.NON_BOOKABLE_TABLE_COLOR = {
    light: 'hsl(0, 0%, 82%)',
    dark: 'hsl(0, 0%, 30%)'
}

seatsio.RoundTable = function (center, radius, subChart, dummy = false) {
    this.center = center
    this.radius = radius
    this.autoRadius = !radius
    this.openSpaces = 0
    this.rotationAngle = 0
    this.initTable(center, subChart, dummy)
}

seatsio.RoundTable.prototype = new seatsio.Table()

seatsio.RoundTable.prototype.shapeType = 'round'

seatsio.RoundTable.prototype.getInspectorSheets = function () {
    return Object.assign({
        'Category.category': this.getChairsCategoryKeys(),
        'RoundTable.chairs': this.chairs.length,
        'RoundTable.minChairs': this.minSeatCount(),
        'RoundTable.openSpaces': this.openSpaces,
        'RoundTable.radius': Math.round(this.radius),
        'RoundTable.autoRadius': !this.radius || this.autoRadius,
        'Shape.rotation': this.rotationAngle
    }, seatsio.Table.prototype.getInspectorSheets.call(this))
}

seatsio.RoundTable.prototype.minSeatCount = function () {
    return this.disabledEditingBySafeMode()
        ? this.chairs.reduce((totalPublished, chair) => totalPublished + (chair.published ? 1 : 0), 0)
        : 1
}

seatsio.RoundTable.prototype.flip = function (ray) {
    this.center = ray.mirror(this.getCenter())
    this.rotationAngle = wrapRotationAround(ray.mirrorAngle(this.rotationAngle))
    this.repositionChairs()
    this.redraw()
    return this
}

seatsio.RoundTable.prototype.duplicate = function (subChart) {
    return this.subChart.tables.add(this.clone(subChart))
}

seatsio.RoundTable.prototype.clone = function (subChart) {
    var table = new seatsio.RoundTable(this.center, this.radius, subChart)
    table.chairs = this.chairs.map(function (chair) {
        return chair.clone(table)
    })
    table.openSpaces = this.openSpaces
    table.rotationAngle = this.rotationAngle
    table.label = this.label
    table.labelShown = this.labelShown
    table.sectionLabel = this.sectionLabel
    table.sectionDisplayedLabel = this.sectionDisplayedLabel
    table.seatLabeling = this.seatLabeling.clone()
    table.objectLabeling = this.objectLabeling.clone()
    table.bookAsAWhole = this.bookAsAWhole
    table.variableOccupancy = this.variableOccupancy
    table.minOccupancy = this.minOccupancy
    table.entrance = this.entrance
    return table
}

seatsio.RoundTable.prototype.setNumberOfOpenSpaces = function (num) {
    this.openSpaces = num
    this.repositionChairs()
    return this
}

seatsio.RoundTable.prototype.numberOfOpenSpaces = function () {
    return this.openSpaces
}

seatsio.RoundTable.prototype.repositionChairs = function () {
    for (var i = 0; i < this.chairs.length; ++i) {
        this.chairs[i].move(this.computeChairCenter(i))
    }
}

seatsio.RoundTable.prototype.simpleDraw = function (color) {
    let center = this.subChart.section.correctSectionContentsPosition(this.center)
    let element = this.designer.drawer.circle(center.x, center.y, this.tableRadius(),
        {
            'stroke-width': 0,
            'fill': color
        })
    element.rotationAngle = this.rotationAngle
    return element
}

seatsio.RoundTable.prototype.drawTable = function () {
    return this.designer.drawer.circle(this.center.x, this.center.y, this.tableRadius(), this.determineStyle())
        .toLayer('objectsLayer', this.designer, this.determineDrawZIndex())
        .applyZoom(this.designer)
}

seatsio.RoundTable.prototype.getShortestSide = function () {
    return this.tableRadius() * 2
}

seatsio.RoundTable.prototype.tableRadius = function () {
    if (this.autoRadius) {
        return this.optimalTableRadius()
    } else {
        return this.radius
    }
}

seatsio.RoundTable.prototype.optimalTableRadius = function () {
    var computedRadius = (this.chairs.length * seatsio.Tables.chairWidth * 1.25) / (2 * Math.PI)
    return Math.max(computedRadius, seatsio.RoundTable.defaultRadius)
}

seatsio.RoundTable.prototype.getRadius = seatsio.RoundTable.prototype.tableRadius

seatsio.RoundTable.prototype.setRadius = function (val) {
    var me = this
    this.radius = val
    this.redrawIfNeeded(function () {
        me.repositionChairs()
    })
}

seatsio.RoundTable.prototype.setAutoRadius = function (autoRadius) {
    this.autoRadius = autoRadius
    this.setRadius(this.autoRadius ? 0 : this.optimalTableRadius())
}

seatsio.RoundTable.prototype.computeChairCenter = function (chairIndex) {
    var rotation = (chairIndex / (this.chairs.length + this.openSpaces) * 360) + this.rotationAngle
    return this.center.addToY(this.tableRadius() + seatsio.Tables.awayFromTableOffset).rotateAround(this.center, rotation)
}

seatsio.RoundTable.prototype.toJson = function () {
    return {
        'center': this.center.toJson(this.subChart),
        'radius': this.tableRadius(),
        'autoRadius': this.autoRadius,
        'seats': this.chairsToJson(),
        'rotationAngle': this.rotationAngle,
        'openSpaces': this.openSpaces,
        'label': this.label,
        'displayLabel': this.displayLabel,
        'labelShown': this.labelShown,
        'sectionLabel': this.sectionLabel,
        'sectionDisplayedLabel': this.sectionDisplayedLabel,
        'seatLabeling': this.seatLabeling.toJson(),
        'objectLabeling': this.objectLabeling.toJson(),
        'type': 'round',
        'objectType': 'table',
        'uuid': this.uuid,
        'bookAsAWhole': this.bookAsAWhole,
        'variableOccupancy': this.variableOccupancy,
        'minOccupancy': this.minOccupancy,
        'published': this.published,
        'viewFromYourSeatImage': this.viewFromYourSeatImage,
        'entrance': this.entrance
    }
}

seatsio.RoundTable.prototype.coreBbox = function () {
    return new seatsio.CircleShape(this.center, this.tableRadius())
        .bbox()
        .enlarge(seatsio.Table.STROKE_WIDTH)
}

seatsio.RoundTable.prototype.bbox = function () {
    let tableBbox = this.coreBbox()
    let chairBboxes = this.chairs.map(chair => chair.bbox())
    return seatsio.Bbox.merged(chairBboxes.concat([tableBbox]))
}

seatsio.RoundTable.prototype.selectionIndicator = function () {
    const thickening = this.chairs.length > 0 ? seatsio.Chair.width : 0
    return new seatsio.CircleShape(this.center, this.tableRadius() + thickening)
}

seatsio.RoundTable.defaultNumberOfChairs = 6
seatsio.RoundTable.defaultRadius = 15

seatsio.RoundTable.prototype.getObjectTypeName = function () {
    return 'roundTable'
}

seatsio.RoundTable.fromJson = function (tableJson, subChart) {
    var table = new seatsio.RoundTable(seatsio.Point.fromJson(tableJson.center, subChart), tableJson.radius, subChart)
    table.chairs = tableJson.seats.map(function (chair) {
        return seatsio.Chair.fromJson(chair, table, subChart)
    })
    table.openSpaces = tableJson.openSpaces ? tableJson.openSpaces : 0
    table.autoRadius = tableJson.autoRadius
    table.rotationAngle = tableJson.rotationAngle
    table.label = tableJson.label
    table.displayLabel = tableJson.displayLabel
    table.labelShown = tableJson.labelShown || false
    table.sectionLabel = tableJson.sectionLabel || null
    table.sectionDisplayedLabel = tableJson.sectionDisplayedLabel || null
    table.seatLabeling = seatsio.SeatLabeling.fromJson(tableJson.seatLabeling)
    table.objectLabeling = seatsio.ObjectLabeling.fromJson(tableJson.objectLabeling) || seatsio.ObjectLabeling.createDefaultTableLabeling()
    table.uuid = tableJson.uuid
    table.bookAsAWhole = tableJson.bookAsAWhole || false
    table.variableOccupancy = tableJson.variableOccupancy || false
    table.minOccupancy = tableJson.minOccupancy || 1
    table.published = tableJson.published !== undefined ? tableJson.published : subChart.designer.isPublished()
    table.viewFromYourSeatImage = tableJson.viewFromYourSeatImage
    table.entrance = tableJson.entrance || null
    return table
}

seatsio.RectTable = function (center, width, height, subChart, dummy = false) {
    this.height = height
    this.width = width
    this.layout = null
    this.chairs = []
    this.distribution = {
        top: 0,
        right: 0,
        bottom: 0,
        left: 0
    }
    this.initTable(center, subChart, dummy)
}

seatsio.RectTable.prototype = new seatsio.Table()

seatsio.RectTable.prototype.shapeType = 'rectangular'

seatsio.RectTable.prototype.getInspectorSheets = function () {
    return Object.assign({
        'Category.category': this.getChairsCategoryKeys(),
        'RectangularTable.chairsTop': this.distribution.top,
        'RectangularTable.chairsBottom': this.distribution.bottom,
        'RectangularTable.chairsLeft': this.distribution.left,
        'RectangularTable.chairsRight': this.distribution.right,
        'RectangularTable.minChairsTop': this.minSeatCount('top'),
        'RectangularTable.minChairsBottom': this.minSeatCount('bottom'),
        'RectangularTable.minChairsLeft': this.minSeatCount('left'),
        'RectangularTable.minChairsRight': this.minSeatCount('right'),
        'Shape.width': this.width,
        'Shape.height': this.height,
        'Shape.rotation': this.rotationAngle
    }, seatsio.Table.prototype.getInspectorSheets.call(this))
}

seatsio.RectTable.prototype.minSeatCount = function (side) {
    if (!this.disabledEditingBySafeMode()) {
        return 0
    }
    const totalChairsOnSide = this.getChairsOnSide(side).length
    const totalChairs = this.chairs.length
    const totalPublishedChairs = this.chairs.reduce((totalPublished, chair) => totalPublished + (chair.published ? 1 : 0), 0)
    return totalChairs > totalPublishedChairs
        ? Math.max(0, totalChairsOnSide - (totalChairs - totalPublishedChairs))
        : totalChairsOnSide
}

seatsio.RectTable.prototype.setHeight = function (height) {
    var me = this
    this.height = height
    this.redrawIfNeeded(function () {
        me.repositionChairs()
    })
}

seatsio.RectTable.prototype.setWidth = function (width) {
    var me = this
    this.width = width
    this.redrawIfNeeded(function () {
        me.repositionChairs()
    })
}

seatsio.RectTable.prototype.simpleDraw = function (color) {
    let topLeft = this.subChart.section.correctSectionContentsPosition(this.topLeft())
    let element = this.designer.drawer.rect(topLeft.x, topLeft.y, this.width, this.height, 0,
        {
            'stroke-width': 0,
            'fill': color
        })
    element.rotationAngle = this.rotationAngle
    return element
}

seatsio.RectTable.prototype.drawTable = function () {
    const topLeft = this.topLeft()
    return this.designer.drawer.rect(topLeft.x, topLeft.y, this.width, this.height, 6, this.determineStyle())
        .toLayer('objectsLayer', this.designer, this.determineDrawZIndex())
        .zoomAndRotateAround(this.rotationAngle, this.getCenter(), this.designer)
}

seatsio.RectTable.prototype.getShortestSide = function () {
    return Math.min(this.width, this.height)
}

seatsio.RectTable.prototype.flip = function (ray) {
    this.distribution = {
        top: this.distribution.top,
        right: this.distribution.left,
        bottom: this.distribution.bottom,
        left: this.distribution.right
    }
    this.center = ray.mirror(this.getCenter())
    this.rotationAngle = wrapRotationAround(ray.mirrorAngle(this.rotationAngle))
    this.repositionChairs()
    this.redraw()
    return this
}

seatsio.RectTable.prototype.duplicate = function (subChart) {
    return this.subChart.tables.add(this.clone(subChart))
}

seatsio.RectTable.prototype.clone = function (subChart) {
    var table = new seatsio.RectTable(this.center, this.width, this.height, subChart)
    table.distribution = Object.assign({}, this.distribution)
    table.chairs = this.chairs.map(function (chair) {
        return chair.clone(table)
    })
    table.rotationAngle = this.rotationAngle
    table.label = this.label
    table.labelShown = this.labelShown
    table.sectionLabel = this.sectionLabel
    table.sectionDisplayedLabel = this.sectionDisplayedLabel
    table.seatLabeling = this.seatLabeling.clone()
    table.objectLabeling = this.objectLabeling.clone()
    table.bookAsAWhole = this.bookAsAWhole
    table.variableOccupancy = this.variableOccupancy
    table.minOccupancy = this.minOccupancy
    table.entrance = this.entrance
    return table
}

seatsio.RectTable.prototype.calculateNewChairTotal = function (num, side) {
    if (side) {
        return this.getDistributionTotal() - this.distribution[side] + num
    } else {
        return num
    }
}

seatsio.RectTable.prototype.setNumberOfChairs = function (num, side) {
    let newChairTotal = this.calculateNewChairTotal(num, side)
    if (newChairTotal <= 0) {
        num = 1
        newChairTotal = 1
    }
    if (side) {
        this.distribution[side] = num
    }
    return seatsio.Table.prototype.setNumberOfChairs.call(this, newChairTotal)
}

seatsio.RectTable.prototype.getDistributionTotal = function () {
    return Object.keys(this.distribution).reduce((total, side) => total + this.distribution[side], 0)
}

seatsio.RectTable.prototype.setDistribution = function (distribution) {
    this.distribution = Object.assign({}, distribution)
    this.setNumberOfChairs(this.getDistributionTotal())
}

seatsio.RectTable.prototype.upgradeLayout = function () {
    switch (this.layout) {
        case 'oneSide':
            this.distribution = {
                top: 0,
                right: 0,
                bottom: this.chairs.length,
                left: 0
            }
            break
        case 'twoSides':
            this.distribution = {
                top: Math.ceil(this.chairs.length / 2),
                right: 0,
                bottom: Math.floor(this.chairs.length / 2),
                left: 0
            }
            break
        case 'bothHeads':
            this.distribution = {
                top: Math.ceil((this.chairs.length - 2) / 2),
                right: 1,
                bottom: Math.floor((this.chairs.length - 2) / 2),
                left: 1
            }
            break
        default:
            return
    }
    this.layout = null
}

seatsio.RectTable.prototype.repositionChairs = function () {
    this.chairs.forEach((chair, i) => chair.move(this.calculateLayoutPoint(i).rotateAround(this.center, this.rotationAngle)))
}

seatsio.RectTable.prototype.topLeft = function () {
    return new seatsio.Point(this.center.x - this.width / 2, this.center.y - this.height / 2)
}

seatsio.RectTable.prototype.determineSeatSide = function (i) {
    const distribution = this.distribution
    const leftLimit = distribution.left
    const topLimit = leftLimit + distribution.top
    const rightLimit = topLimit + distribution.right
    const bottomLimit = rightLimit + distribution.bottom

    if (i < leftLimit && distribution.left > 0) {
        return 'left'
    } else if (i < topLimit && distribution.top > 0) {
        return 'top'
    } else if (i < rightLimit && distribution.right > 0) {
        return 'right'
    } else if (i < bottomLimit && distribution.bottom > 0) {
        return 'bottom'
    }
    return null
}

seatsio.RectTable.prototype.calculateLayoutPoint = function (i) {
    const topLeft = this.topLeft()
    const width = this.width
    const height = this.height
    const distribution = this.distribution
    const leftLimit = distribution.left
    const topLimit = leftLimit + distribution.top
    const rightLimit = topLimit + distribution.right
    const side = this.determineSeatSide(i)
    let partLength

    switch (side) {
        case 'left':
            partLength = height / distribution[side]
            return topLeft.addToX(-1 * seatsio.Tables.awayFromTableOffset).addToY(height - partLength * i - partLength / 2)
        case 'top':
            partLength = width / distribution[side]
            return topLeft.addToY(-1 * seatsio.Tables.awayFromTableOffset).addToX(partLength * (i - leftLimit) + partLength / 2)
        case 'right':
            partLength = height / distribution[side]
            return topLeft.addToX(width + seatsio.Tables.awayFromTableOffset).addToY(partLength * (i - topLimit) + partLength / 2)
        case 'bottom':
            partLength = width / distribution[side]
            return topLeft.addToY(height + seatsio.Tables.awayFromTableOffset).addToX(width - partLength * (i - rightLimit) - partLength / 2)
        default:
            return topLeft
    }
}

seatsio.RectTable.prototype.getChairsOnSide = function (side) {
    return this.chairs.filter((chair, i) => this.determineSeatSide(i) === side)
}

seatsio.RectTable.prototype.toJson = function () {
    return {
        'center': this.center.toJson(this.subChart),
        'height': this.height,
        'width': this.width,
        'seats': this.chairsToJson(),
        'rotationAngle': this.rotationAngle,
        'label': this.label,
        'displayLabel': this.displayLabel,
        'labelShown': this.labelShown,
        'sectionLabel': this.sectionLabel,
        'sectionDisplayedLabel': this.sectionDisplayedLabel,
        'seatLabeling': this.seatLabeling.toJson(),
        'objectLabeling': this.objectLabeling.toJson(),
        'type': 'rectangular',
        'objectType': 'table',
        'layout': this.layout,
        'distribution': this.distribution,
        'uuid': this.uuid,
        'bookAsAWhole': this.bookAsAWhole,
        'variableOccupancy': this.variableOccupancy,
        'minOccupancy': this.minOccupancy,
        'published': this.published,
        'viewFromYourSeatImage': this.viewFromYourSeatImage,
        'entrance': this.entrance
    }
}

seatsio.RectTable.prototype.coreBbox = function () {
    return new seatsio.RectangleShape(this.center, this.width, this.height, this.rotationAngle)
        .bbox()
        .enlarge(seatsio.Table.STROKE_WIDTH)
}

seatsio.RectTable.prototype.bbox = function () {
    let tableBbox = this.coreBbox()
    let chairBboxes = this.chairs.map(chair => chair.bbox())
    return seatsio.Bbox.merged(chairBboxes.concat([tableBbox]))
}

seatsio.RectTable.prototype.selectionIndicator = function () {
    const thickening = {
        horizontal: this.distribution.left > 0 || this.distribution.right > 0 ? seatsio.Chair.width * 2 : 0,
        vertical: this.distribution.top > 0 || this.distribution.bottom > 0 ? seatsio.Chair.width * 2 : 0
    }
    let width = this.width + thickening.horizontal
    let height = this.height + thickening.vertical
    return new seatsio.RectangleShape(this.center, width, height, this.rotationAngle).toPolygon()
}

seatsio.RectTable.defaultHeight = 36
seatsio.RectTable.defaultWidth = 120
seatsio.RectTable.defaultLayout = null
seatsio.RectTable.defaultDistribution = {
    top: 4,
    right: 0,
    bottom: 4,
    left: 0
}

seatsio.RectTable.prototype.getObjectTypeName = function () {
    return 'rectangularTable'
}

seatsio.RectTable.fromJson = function (tableJson, subChart) {
    var table = new seatsio.RectTable(seatsio.Point.fromJson(tableJson.center, subChart), tableJson.width, tableJson.height, subChart)
    table.distribution = tableJson.distribution
    table.chairs = tableJson.seats.map(chair => seatsio.Chair.fromJson(chair, table, subChart))
    table.layout = tableJson.layout
    table.upgradeLayout()
    table.rotationAngle = tableJson.rotationAngle
    table.label = tableJson.label
    table.displayLabel = tableJson.displayLabel
    table.labelShown = tableJson.labelShown || false
    table.sectionLabel = tableJson.sectionLabel || null
    table.sectionDisplayedLabel = tableJson.sectionDisplayedLabel || null
    table.seatLabeling = seatsio.SeatLabeling.fromJson(tableJson.seatLabeling)
    table.objectLabeling = seatsio.ObjectLabeling.fromJson(tableJson.objectLabeling) || seatsio.ObjectLabeling.createDefaultTableLabeling()
    table.uuid = tableJson.uuid
    table.bookAsAWhole = tableJson.bookAsAWhole || false
    table.variableOccupancy = tableJson.variableOccupancy || false
    table.minOccupancy = tableJson.minOccupancy || 1
    table.published = tableJson.published !== undefined ? tableJson.published : subChart.designer.isPublished()
    table.viewFromYourSeatImage = tableJson.viewFromYourSeatImage
    table.entrance = tableJson.entrance || null
    return table
}

seatsio.Booths = function (subChart) {
    this.subChart = subChart
    this.designer = subChart.designer
    this.booths = []
}

seatsio.Booths.prototype.draw = function (booth) {
    booth.label = seatsio.Booths.generateLabel()
    booth.draw()
    booth.playFlash()
    return this.add(booth)
}

seatsio.Booths.prototype.add = function (booth) {
    booth.published = false
    this.booths.push(booth)
    booth.refreshOutOfBounds()
    this.designer.requestStatsUpdate()
    return booth
}

seatsio.Booths.prototype.clone = function (subChart) {
    var booths = new seatsio.Booths(subChart)
    booths.booths = this.booths.map(function (booth) {
        return booth.clone(subChart)
    })
    return booths
}

seatsio.Booths.prototype.remove = function (booth) {
    booth.undraw()
    this.booths.remove(booth)
    this.designer.requestStatsUpdate()
}

seatsio.Booths.prototype.allElementsSet = function () {
    return this.booths.map(function (booth) {
        return booth.allElementsSet()
    })
}

seatsio.Booths.prototype.toJson = function () {
    return this.booths.map(function (booth) {
        return booth.toJson()
    })
}

seatsio.Booths.labelCounter = 1

seatsio.Booths.generateLabel = function () {
    return (seatsio.Booths.labelCounter++).toString()
}

seatsio.Booths.fromJson = function (json, subChart) {
    var booths = new seatsio.Booths(subChart)
    if (json) {
        booths.booths = json.map(function (boothJson) {
            return seatsio.Booth.fromJson(boothJson, subChart)
        })
    }
    return booths
}

seatsio.BoothMousePointer = function (designer) {
    this.designer = designer
    this.boothShapesSet = null
    this.startPoint = null
}

seatsio.BoothMousePointer.prototype.showAt = function (point, width, height) {
    if (!this.booth) {
        this.startPoint = point
        let booth = seatsio.Booth.createDummyBoothForMousePointer(point, width, height, this.designer.activeSubChart())
        this.booth = booth.draw().disableSelection().hideLabelAndChildLabels().drawPositionGuides().allElementsSet().startTransformation()
    } else {
        this.booth.transform(this.startPoint.vectorTo(point, this.designer).asTranslation())
    }
}

seatsio.BoothMousePointer.prototype.hide = function () {
    if (this.booth) {
        this.booth.remove()
        this.booth = null
        this.startPoint = null
    }
}

seatsio.Booth = function (center, width, height, subChart, dummy = false) {
    this.subChart = subChart
    this.designer = subChart.designer
    this.center = center
    this.width = width
    this.height = height
    this.booth = null
    this.line1 = null
    this.line2 = null
    this.centerPunchHole = null
    this.rotationAngle = 0
    this.category = null
    this.label = seatsio.LabelingTextInput.emptyLabel
    this.displayLabel = null
    this.objectLabeling = seatsio.ObjectLabeling.createDefaultBoothLabeling()
    this.sectionLabel = null
    this.sectionDisplayedLabel = null
    this.published = false
    this.init(this.designer, undefined, undefined, dummy)
}

seatsio.Booth.prototype = new seatsio.Object()

seatsio.Booth.prototype.type = 'booth'

seatsio.Booth.prototype.getInspectorSheets = function () {
    const source = seatsio.Object.prototype.getInspectorSheets.call(this)
    const disabled = source.disabled || []
    if (this.disabledEditingBySafeMode()) {
        disabled.push('ObjectLabeling.label')
        disabled.push('SectionLabeling.sectionLabel')
    }
    return Object.assign(source, {
        'Category.category': this.category && this.category.key,
        // 'Shape.width': this.width,
        // 'Shape.height': this.height,
        // 'Shape.rotation': Math.round(this.rotationAngle),
        // 'Transform': null,
        // 'Transform.cutoffAngle': null,
        // 'SectionLabeling.sectionLabel': this.sectionLabel,
        // 'SectionLabeling.sectionDisplayedLabel': this.sectionDisplayedLabel,
        // 'SectionLabeling.isNewObject': !this.published,
        // 'ObjectLabeling.label': this.hasLabel() ? this.label : null,
        // 'ObjectLabeling.displayLabel': this.displayLabel,
        // 'ObjectLabeling.isNewObject': !this.published,
        // 'ObjectLabeling.sequence': this.objectLabeling.algoName,
        // 'ObjectLabeling.prefix': this.objectLabeling.prefix,
        // 'ObjectLabeling.start': this.objectLabeling.startAtIndex + 1,
        // 'Misc.entrance': this.entrance,
        // 'Misc.sectionEntrance': this.getSectionEntrance(),
        disabled
    })
}

seatsio.Booth.prototype.getCenter = function () {
    return this.center
}

seatsio.Booth.prototype.totalPeopleCapacity = function () {
    return 0
}

seatsio.Booth.prototype.drawn = function () {
    return this.booth
}

seatsio.Booth.prototype.svgElement = function () {
    return this.booth
}

seatsio.Booth.prototype.applyCategory = function (category) {
    this.category = category
}

seatsio.Booth.prototype.hasBookableCapabilities = function () {
    return true
}

seatsio.Booth.prototype.removeCategory = function () {
    this.category = null
}

seatsio.Booth.prototype.simpleDraw = function (color) {
    let topLeft = this.subChart.section.correctSectionContentsPosition(this.center.addToX(-this.width / 2).addToY(-this.height / 2))
    let centerWithinSection = this.subChart.section.correctSectionContentsPosition(this.center)
    return this.designer.drawer.rect(topLeft.x, topLeft.y, this.width, this.height, 0, { 'opacity': 1, 'stroke-width': 0, 'fill': color })
        .zoomAndRotateAround(this.rotationAngle, centerWithinSection, this.designer)
}

seatsio.Booth.prototype.draw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    var shapes = seatsio.Booth.createShapes(this.center, this.width, this.height, this.determineBaseColor(), this.rotationAngle, this.zIndex, this.designer)
    this.booth = shapes.booth
    this.line1 = shapes.line1
    this.line2 = shapes.line2
    this.centerPunchHole = shapes.centerPunchHole
    this.applyElementAttributes()
    this.objectDrawn()
    return this
}

seatsio.Booth.prototype.determineDashesStrokeColor = function () {
    const dashesColor = this.determineStrokeColor()
    if (this.designer.labelsShown) {
        return seatsio.Color.create(dashesColor).alpha(0.4).toCSS()
    }
    return dashesColor
}

seatsio.Booth.prototype.applyElementAttributes = function () {
    if (this.booth) {
        this.booth.attr(this.determineStyle())
    }
    if (this.line1 && this.line2) {
        [this.line1, this.line2].forEach(line => line.attr({
            'stroke': this.determineDashesStrokeColor()
        }))
    }
    if (this.centerPunchHole) {
        this.centerPunchHole.attr({ 'fill': this.determineFillColor() })
    }
}

seatsio.Booth.prototype.flip = function (ray) {
    this.center = ray.mirror(this.getCenter())
    this.rotationAngle = wrapRotationAround(ray.mirrorAngle(this.rotationAngle))
    this.redraw()
    return this
}

seatsio.Booth.prototype.duplicate = function (subChart) {
    return this.subChart.booths.add(this.clone(subChart))
}

seatsio.Booth.prototype.clone = function (subChart) {
    var booth = new seatsio.Booth(this.center, this.width, this.height, subChart)
    booth.category = this.category
    booth.sectionLabel = this.sectionLabel
    booth.sectionDisplayedLabel = this.sectionDisplayedLabel
    booth.objectLabeling = this.objectLabeling.clone()
    booth.label = this.label
    booth.displayLabel = this.displayLabel
    booth.rotationAngle = this.rotationAngle
    booth.entrance = this.entrance
    return booth
}

seatsio.Booth.prototype.canBeRemoved = function () {
    return !this.disabledDeletingBySafeMode()
}

seatsio.Booth.prototype.moved = function (distance) {
    this.center = this.center.add(distance)
    this.refreshOutOfBounds()
    this.redraw()
}

seatsio.Booth.prototype.rotated = function (rotationCenter, angle) {
    this.center = this.center.rotateAround(rotationCenter, angle)
    this.rotationAngle = wrapRotationAround(this.rotationAngle + angle)
    this.redraw()
}

seatsio.Booth.prototype.setWidth = function (width) {
    this.width = width
    this.redraw()
}

seatsio.Booth.prototype.setHeight = function (height) {
    this.height = height
    this.redraw()
}

seatsio.Booth.prototype.setRotationAngle = function (val) {
    this.rotationAngle = wrapRotationAround(val)
    this.redraw()
}

seatsio.Booth.prototype.undraw = function () {
    if (!this.subChart.isActive()) {
        return
    }
    this.objectUndrawn()
    this.selector.undraw()
    if (this.booth) {
        this.booth.remove()
        this.booth = null
        this.line1.remove()
        this.line1 = null
        this.line2.remove()
        this.line2 = null
        this.centerPunchHole.remove()
        this.centerPunchHole = null
    }
}

seatsio.Booth.prototype.redraw = function () {
    if (this.drawn()) {
        this.undraw()
        this.draw()
    }
}

seatsio.Booth.prototype.getPositionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRect

seatsio.Booth.prototype.animatedObject = function () {
    return this.booth
}

seatsio.Booth.prototype.visibleElementsSet = function () {
    return seatsio.set(this.booth, this.line1, this.line2, this.centerPunchHole, this.positionGuides)
}

seatsio.Booth.prototype.remove = function () {
    this.subChart.booths.remove(this)
}

