seatsio.Booth.fromJson = function (json, subChart) {
    var booth = new seatsio.Booth(seatsio.Point.fromJson(json.center, subChart), json.width, json.height, subChart)
    booth.applyCategory(subChart.designer.categories.getCategory(json.categoryKey))
    booth.label = json.label
    booth.displayLabel = json.displayLabel
    booth.sectionLabel = json.sectionLabel || null
    booth.sectionDisplayedLabel = json.sectionDisplayedLabel || null
    booth.objectLabeling = seatsio.ObjectLabeling.fromJson(json.objectLabeling) || seatsio.ObjectLabeling.createDefaultBoothLabeling()
    booth.rotationAngle = json.rotationAngle
    booth.uuid = json.uuid
    booth.published = json.published !== undefined ? json.published : subChart.designer.isPublished()
    booth.entrance = json.entrance || null
    return booth
}

