seatsio.Zones = class Zones {
    constructor (designer, zones = []) {
        this.designer = designer
        this.zones = zones
        this.currentZoneKey = undefined
        this.undrawTimeout = undefined
    }

    initFromJson (json = {}) {
        if (!json.list) {
            return
        }
        this.zones = json.list.map(zone => seatsio.Zone.fromJson(zone, this.designer))
    }

    all () {
        return this.zones
    }

    count () {
        return this.zones.length
    }

    createZone () {
        const key = this.fetchNewZoneKey()
        var newZone = new seatsio.Zone(
            key,
            null,
            new seatsio.FocalPoint(this.designer.masterSubChart),
            this.designer
        )
        this.zones.push(newZone)
        this.designer.requestStatsUpdate()
        this.designer.renderUI()
        return newZone
    }

    deleteZone (zoneKey) {
        this.zones = this.zones.filter(zone => zone.key !== zoneKey)
        this.designer.requestStatsUpdate()
        this.designer.renderUI()
    }

    setCurrentZone (zoneKey) {
        if (!zoneKey) {
            zoneKey = undefined
        }
        if (this.currentZoneKey === zoneKey) {
            return
        }
        this.currentZoneKey = zoneKey
        this.flashCurrentZone()
    }

    flashCurrentZone () {
        this.temporarilyDrawCurrentZone()
        this.designer.renderUI()
        this.designer.getState().onZoneChange()
    }

    hasCurrentZone () {
        return this.currentZoneKey !== undefined
    }

    setZoneKey (zoneKey, nextKey) {
        if (!nextKey || this.hasZone(nextKey)) {
            return
        }

        const zone = this.getZone(zoneKey)
        if (zone) {
            zone.changeKey(nextKey)
            this.applyZoneToObjects(zone.getObjectsInZone(), nextKey)
            this.setCurrentZone(nextKey)
        } else {
            console.warn(`Zone with key ${zoneKey} not found.`)
        }
    }

    setZoneLabel (zoneKey, label) {
        const zone = this.getZone(zoneKey)
        if (zone) {
            zone.setLabel(label.trim())
            this.designer.renderUI()
        }
    }

    getCurrentZoneKeyForNewObject () {
        if (this.designer.atMasterSubChart() && this.designer.isVenueWithZones()) {
            return this.currentZoneKey
        }
        return undefined
    }

    applyZoneToObjects (objects, zoneKey) {
        this.getZone(zoneKey).applyZoneToObjects(objects)
    }

    fetchNewZoneKey () {
        let i = 0
        let testingZoneKey
        while (!testingZoneKey || this.hasZone(testingZoneKey)) {
            i += 1
            testingZoneKey = `${d('new-zone')} ${i}`
        }
        return testingZoneKey
    }

    hasZone (zoneKey) {
        return this.zones.some(zone => zone.isZoneKey(zoneKey))
    }

    getZone (zoneKey) {
        return this.zones.find(zone => zone.isZoneKey(zoneKey))
    }

    getCurrentZone () {
        if (!this.hasCurrentZone()) {
            return undefined
        }
        return this.getZone(this.currentZoneKey)
    }

    getFocalPoint () {
        const currentZone = this.getCurrentZone()
        return currentZone
            ? currentZone.focalPoint
            : undefined
    }

    canZoneBeDeleted (zoneKey) {
        const zone = this.getZone(zoneKey)
        return Boolean(zone && zone.canZoneBeDeleted())
    }

    getZonesMissingFocalPoint () {
        return this.zones.filter(zone => !zone.hasFocalPointSet())
    }

    getFeatureStatus (feature) {
        const FT = seatsio.Features.Type
        const FS = seatsio.Features.Status
        if (this.designer.atMasterSubChart()) {
            if (feature === FT.SECTIONS || feature === FT.AREAS || feature === FT.FOCAL_POINT) {
                if (this.designer.isVenueWithZones() && !this.currentZoneKey) {
                    return FS.DISABLED
                }
            }
        }
        return undefined
    }

    canPlaceObject (object) {
        if (!this.designer.isVenueWithZones()) {
            return true
        }
        if (object.requiresZone()) {
            return this.hasCurrentZone()
        }
        return true
    }

    temporarilyDrawCurrentZone () {
        if (this.undrawTimeout) {
            clearTimeout(this.undrawTimeout)
        }
        this.drawZones()
        this.undrawTimeout = setTimeout(() => {
            this.undrawZones()
            this.undrawTimeout = undefined
        }, 2000)
    }

    undrawZones () {
        this.zones.forEach(zone => zone.undraw())
    }

    drawZones () {
        this.undrawZones()
        const currentZone = this.getCurrentZone()
        if (currentZone) {
            currentZone.draw()
        }
    }

    toJson () {
        return {
            list: this.zones.map(zone => {
                return {
                    key: zone.key,
                    label: zone.label,
                    focalPoint: zone.focalPoint.toJson()
                }
            })
        }
    }
}

seatsio.Zone = class Zone {
    constructor (key, label, focalPoint, designer) {
        this.key = key
        this.label = label
        this.focalPoint = focalPoint
        this.designer = designer
        this.shape = undefined
    }

    changeKey (nextKey) {
        const prevKey = this.key
        this.key = nextKey
        return prevKey
    }

    setLabel (label) {
        this.label = label
    }

    isZoneKey (zoneKey) {
        return this.key === zoneKey
    }

    getDisplayedLabel () {
        return this.label || this.key
    }

    applyZoneToObjects (objects) {
        objects.forEach(object => object.setZone(this.key))
        this.designer.renderUI()
    }

    canZoneBeDeleted () {
        return this.getObjectsInZone().length === 0
    }

    getObjectsInZone () {
        return this.designer.masterSubChart.zoneableObjects().filter(object => object.isInZone(this.key))
    }

    hasFocalPointSet () {
        return this.focalPoint.isSet()
    }

    undraw () {
        if (this.shape) {
            this.shape.remove()
            this.shape = undefined
        }
    }

    draw () {
        this.undraw()
        const bbox = this.getBBox()
        if (!bbox.isEmpty()) {
            this.shape = this.createShapes(bbox)
            this.animateFadeOut(this.shape)
        }
        return this
    }

    allElementsSet () {
        return this.shape
    }

    getBBox () {
        const objects = this.getObjectsInZone(this.key)
        return seatsio.Bbox.mergedFromObjectsSelectionIndicator(objects)
    }

    createShapes (bbox) {
        const zoomer = this.designer.zoomer
        const drawer = this.designer.drawer
        const drawBBox = bbox.enlarge(zoomer.unzoom(seatsio.Zone.RECTANGLE_PADDING))

        const rectangle = drawer.rect(drawBBox.origin.x, drawBBox.origin.y, drawBBox.width, drawBBox.height, zoomer.unzoom(10), {
            'stroke-width': zoomer.unzoom(3),
            'stroke': 'hsla(328, 100%, 49%, 0.5)',
            'fill': 'hsla(328, 100%, 49%, 0.05)'
        })
        rectangle.node.setAttribute('pointer-events', 'none')

        return rectangle.toLayer('tempDrawingsLayer', this.designer).applyZoom(this.designer)
    }

    animateFadeOut (shape) {
        const runner = new SVG.Runner(2000)
            .element(shape)
            .attr({
                'opacity': 0
            })
            .ease('>')
        const timeline = new SVG.Timeline()
        timeline.schedule(runner)
        timeline.play()
    }

    static fromJson (json, designer) {
        const focalPoint = json.focalPoint ? seatsio.FocalPoint.fromJson(json.focalPoint, designer.masterSubChart) : new seatsio.FocalPoint(designer.masterSubChart)
        return new seatsio.Zone(json.key, json.label, focalPoint, designer)
    }
}

seatsio.Zone.RECTANGLE_PADDING = 20

