seatsio.Category.getLabel = function (category) {
    if (!category) {
        return null
    }
    return category.label
}

seatsio.Category.prototype.setLabel = function (label) {
    if (label) {
        this.label = label.trim()
    } else {
        this.label = ''
    }
}

seatsio.Category.getKey = function (category) {
    if (!category) {
        return null
    }
    return category.key
}

seatsio.Category.prototype.setKey = function (key) {
    this.key = key
}

seatsio.Category.getAccessible = function (category) {
    if (!category) {
        return null
    }
    return category.accessible
}

seatsio.Categories = function (designer) {
    this.designer = designer
    this.categories = []
    this.maxCategoryKey = null
}

seatsio.Categories.prototype.all = function () {
    return this.categories ? this.categories : []
}

seatsio.Categories.prototype.setCategories = function (maxCategoryKey, newCategories) {
    this.maxCategoryKey = maxCategoryKey
    this.categories = newCategories
}

seatsio.Categories.prototype.getCategory = function (key) {
    // eslint-disable-next-line eqeqeq
    return this.categories.findOne(category => category.key == key) || null
}

seatsio.Categories.prototype.removeCategory = function (category) {
    this.categories.splice(this.categories.indexOf(category), 1)
    var objects = this.itemsWithCategory(category)
    objects.forEach(function (object) {
        object.removeCategory()
    })
    this.redrawParents(objects)
    this.designer.renderUI()
}

seatsio.Categories.prototype.reorderCategory = function (fromIndex, toIndex) {
    let category = this.categories.splice(fromIndex, 1)[0]
    this.categories.splice(toIndex, 0, category)
    this.designer.renderUI()
}

seatsio.Categories.prototype.removeCategoryByKey = function (key) {
    this.removeCategory(this.getCategory(key))
}

seatsio.Categories.prototype.changeKey = function (prevKey, newKey) {
    if (this.getCategory(newKey)) {
        return false
    }
    this.getCategory(prevKey).setKey(newKey)
    this.updateMaxCategoryKey()
    this.designer.renderUI()
    return true
}

seatsio.Categories.prototype.itemsWithCategory = function (category) {
    return this.designer.activeSubChart().categorisableObjects().filter(object => {
        return object.category === category || (category && this.designer.activeSubChart().category === category && !object.category)
    })
}

seatsio.Categories.prototype.parentItemsWithCategory = function (category) {
    return this.designer.activeSubChart().categorisableParentObjects().filter(function (object) {
        return object.hasCategory(category)
    })
}

seatsio.Categories.prototype.colorChanged = function (category) {
    this.parentItemsWithCategory(category).concat(this.itemsWithCategory(category)).forEach(item => {
        item.applyElementAttributes()
        if (item.labeler) item.labeler.redraw()
    })
    this.designer.renderUI()
}

seatsio.Categories.prototype.accessibleChanged = function (category) {
    this.redrawParents(this.itemsWithCategory(category))
    this.designer.renderUI()
}

seatsio.Categories.prototype.toggleAccessibleByKey = function (key) {
    let category = this.getCategory(key)
    category.accessible = !category.accessible
    this.accessibleChanged(category)
}

seatsio.Categories.prototype.setColorByKey = function (key, color) {
    let category = this.getCategory(key)
    category.color = color
    this.colorChanged(category)
}

seatsio.Categories.prototype.setNameByKey = function (key, label) {
    let category = this.getCategory(key)
    category.setLabel(label)
    this.colorChanged(category)
}

seatsio.Categories.prototype.applyCategoryToItems = function (items, category) {
    items.forEach(function (item) {
        item.applyCategory(category)
    })
    this.redrawParents(items)
    this.designer.updateCategoriesStats()
    this.designer.updateGlobalOnlyStats()
}

seatsio.Categories.prototype.applyCategoryToItemsByKey = function (items, key) {
    this.applyCategoryToItems(items, this.getCategory(key))
}

seatsio.Categories.prototype.removeCategoryToItems = function (items) {
    items.forEach(function (item) {
        item.removeCategory()
    })
    this.redrawParents(items)
    this.designer.updateCategoriesStats()
    this.designer.updateGlobalOnlyStats()
}

seatsio.Categories.prototype.redrawParents = function (items) {
    this.parents(items).forEach(function (parent) {
        parent.redraw()
    })
}

seatsio.Categories.prototype.refreshAttributesForParents = function (items) {
    this.parents(items).forEach(function (parent) {
        parent.applyElementAttributes()
    })
}

seatsio.Categories.prototype.parents = function (items) {
    return items.map(function (item) {
        if (item.parent) return item.parent
        else return item
    }).uniques()
}

seatsio.Categories.prototype.getNewPaletteColor = function () {
    const colorScheme = this.designer.getCanvasColorScheme()
    const categoryPalettes = seatsio.ColorPalettes.sets.category
    const takenColors = this.all().map(category => category.color.toUpperCase())
    const lastUsedPalette = this.lastUsedPalette() || categoryPalettes[0]
    const freeColors = [lastUsedPalette]
        .concat(categoryPalettes.filter(palette => palette.name !== lastUsedPalette.name))
        .map(palette => palette.colors[colorScheme].filter(color => !takenColors.includes(color)))
        .flat()

    return freeColors[0] || this.getRandomHexColor()
}

seatsio.Categories.prototype.lastUsedPalette = function () {
    let availablePalettes = seatsio.ColorPalettes.sets.category
    let lastTakenColors = this.all().map(category => category.color.toUpperCase()).reverse()
    let lastPalette = null
    lastTakenColors.forEach(takenColor => {
        availablePalettes.forEach(palette => {
            if (!lastPalette && palette.colors[this.designer.getCanvasColorScheme()].includes(takenColor)) {
                lastPalette = palette
            }
        })
    })
    return lastPalette
}

seatsio.Categories.prototype.getRandomHexColor = function () {
    var letters = '0123456789ABCDEF'.split('')
    var color = '#'
    for (var i = 0; i < 6; i++) {
        color += letters[Math.round(Math.random() * 15)]
    }
    return color
}

seatsio.Categories.prototype.createCategory = function () {
    var newCategory = new seatsio.Category(d('new-category'), this.getNewPaletteColor(), false, ++this.maxCategoryKey)
    this.categories.push(newCategory)
    this.designer.renderUI()
    return newCategory
}

seatsio.Categories.prototype.updateMaxCategoryKey = function () {
    const maxCategoryKeyOnCategories = this.categories.reduce((v, category) => {
        return isPositiveInteger(category.key) ? Math.max(v, category.key) : v
    }, 0)
    this.maxCategoryKey = Math.max(maxCategoryKeyOnCategories, this.maxCategoryKey)
}

seatsio.Categories.prototype.toJson = function () {
    return {
        list: this.categories,
        maxCategoryKey: this.maxCategoryKey
    }
}

seatsio.ShapedObject = class ShapedObject extends seatsio.Object {
    constructor (subChart, shape) {
        super(subChart, shape)
        if (subChart) {
            this.doInit(subChart.designer, shape, true)
            this.subChart = subChart
            seatsio.ObjectLabelSupport.prototype.init.apply(this)
        }
        this.smartType = seatsio.ShapedObject.SMART_TYPES[0]
        this.smartTypeVariation = null
        this.label = ''
        if (this.shape && this.shape.type !== 'line') {
            this.fillColor = seatsio.ColorPalettes.defaults.SHAPE_FILL[this.designer ? this.designer.getCanvasColorScheme() : 'light']
        }
        this.autoStroke = false
        this.strokeWidth = seatsio.ShapedObject.DEFAULT_STROKE_WIDTH
        this.refreshStrokeColor()
        this.icon = this.smartType
        this.labelSize = 16
        this.type = 'shape'
    }

    shouldSelect (selectionBbox) {
        return this.shape.shouldSelect(selectionBbox)
    }

    doInit (designer, shape, noLabel) {
        this.shape = shape
        this.shapeType = shape.type
        this.shape.setParent(this)
        this.init(designer, noLabel, false)
    }

    iconSizeMultiplier () {
        return 1.8
    }

    isMultiShape () {
        return this.shapeType === 'multishape'
    }

    getInspectorSheets () {
        let bbox = this.bbox()
        let properties = Object.assign(seatsio.Object.prototype.getInspectorSheets.call(this), {
            'objectType': 'shape',
            'Shape.strokeColor': this.strokeColor,
            'Shape.strokeWidth': this.strokeWidth,
            'Shape.minStrokeWidth': this.shape.minStrokeWidth,
            'Shape.maxStrokeWidth': this.shape.maxStrokeWidth,
            'Transform': null,
            'Transform.cutoffAngle': this.shape.type === 'polygon' ? this.shape.cutoffAngle : null
        })

        if (this.shape.type !== 'line') {
            properties = Object.assign(properties, {
                'Shape.rotation': this.shape.rotationAngle,
                'Shape.cornerRadius': this.shape.cornerRadius,
                'Shape.fillColor': this.fillColor,
                'Shape.autoStroke': this.autoStroke,
                'SmartLabel.smartType': this.smartType,
                'SmartLabel.smartTypeVariation': this.smartTypeVariation,
                'SmartLabel.caption': this.label,
                'SmartLabel.positionX': Math.round(this.labelHorizontalOffset / bbox.width * 100),
                'SmartLabel.positionY': Math.round(this.labelVerticalOffset / bbox.height * 100),
                'SmartLabel.size': this.labelSize
            })

            if (this.shape.width !== undefined || this.shape.radius1 !== undefined) {
                properties = Object.assign(properties, {
                    'Shape.width': this.shape.width || this.shape.radius1 * 2,
                    'Shape.height': this.shape.height || this.shape.radius2 * 2
                })
            }
        } else {
            properties = Object.assign(properties, {
                'Shape.lineCap': this.shape.lineCap,
                'Shape.lineJoin': this.shape.lineJoin
            })
        }

        if (this.shape.foreground !== undefined) {
            properties = Object.assign(properties, {
                'Shape.foreground': this.shape.foreground
            })
        }
        return properties
    }

    refreshIcon () {
        this.setIcon(this.smartType.length > 0 ? (this.smartTypeVariation ? [this.smartType, this.smartTypeVariation].join('-') : this.smartType) : null)
    }

    setSmartType (value) {
        if (this.label === d(this.smartType)) this.changeLabel(d(value))
        this.smartType = value
        const variations = seatsio.ShapedObject.SMART_TYPES_VARIATIONS[this.smartType]
        this.smartTypeVariation = variations ? variations[0] : null
        this.redraw()
        this.refreshIcon()
    }

    setSmartTypeVariation (value) {
        this.smartTypeVariation = value
        this.redraw()
        this.refreshIcon()
    }

    setWidth (value) {
        this.shape.setWidth(value)
        this.redraw()
    }

    setHeight (value) {
        this.shape.setHeight(value)
        this.redraw()
    }

    setRotationAngle (value) {
        this.shape.setRotationAngle(value)
        this.redraw()
    }

    setAutoStroke (value) {
        this.autoStroke = value
        if (this.autoStroke) {
            this.refreshStrokeColor()
        }
        this.redraw()
    }

    setStrokeWidth (value) {
        this.strokeWidth = value
        this.redraw()
        return this
    }

    setLineCap (value) {
        this.shape.setLineCap(value)
        this.redraw()
    }

    setLineJoin (value) {
        this.shape.setLineJoin(value)
        this.redraw()
    }

    setStrokeColor (value) {
        this.strokeColor = value
        this.applyElementAttributes()
        return this
    }

    setFillColor (value) {
        if (this.autoStroke) this.refreshStrokeColor(value)
        let prevColor = new seatsio.Color(this.fillColor)
        let nextColor = new seatsio.Color(value)
        this.fillColor = value
        if (prevColor.isDark() !== nextColor.isDark()) {
            this.redraw()
        } else {
            this.applyElementAttributes()
        }
        return this
    }

    setCornerRadius (value) {
        if (this.shape.setCornerRadius) {
            this.shape.setCornerRadius(value)
            this.redraw()
        }
        return this
    }

    refreshStrokeColor (value = this.fillColor) {
        const baseColor = new seatsio.Color(value)
        const darkCanvas = this.designer && this.designer.getCanvasColorScheme() !== 'light'
        this.strokeColor = baseColor.softened(darkCanvas).cssString
    }

    enter () {
        if (this.shapeType === 'line') {
            this.shape.enter()
        }
    }

    duplicate () {
        return this.designer.activeSubChart().shapes.add(this.clone(this.subChart))
    }

    selectionElements () {
        return this.shape.selectionElements()
    }

    determineMinScaledStrokeWidth () {
        return 0
    }

    determineMaxScaledStrokeWidth () {
        return this.shapeType === 'line' ? 300 : 100
    }

    determineStrokeWidthWithoutScaling () {
        return this.autoStroke ? 3 : this.strokeWidth
    }

    determineStrokeWidth () {
        const strokeWidthWithoutScaling = this.determineStrokeWidthWithoutScaling()
        const targetStrokeWidth = this.autoStroke ? this.applyScale(strokeWidthWithoutScaling) : strokeWidthWithoutScaling
        return Math.max(this.determineMinScaledStrokeWidth(), Math.min(this.determineMaxScaledStrokeWidth(), targetStrokeWidth))
    }

    clone (subChart) {
        const shapedObject = new seatsio.ShapedObject(subChart, this.shape.clone())
        seatsio.ShapedObject.properties.forEach(prop => shapedObject[prop] = this[prop])
        return shapedObject
    }

    remove () {
        this.designer.activeSubChart().shapes.remove(this)
        this.undraw()
    }

    polygonSupport () {
        return this.shape.type === 'polygon' || this.shape.type === 'line'
    }

    center () {
        return this.shape.getCenter()
    }

    getCenter () {
        return this.center()
    }

    centroid (distanceFromEdge) {
        return this.shape.getCentroid(distanceFromEdge)
    }

    verticallyOriented () {
        let shape = this.getShape()
        if (shape.rotationAngle) {
            return shape.width < shape.height
        } else {
            let bbox = this.bbox()
            return bbox.width < bbox.height
        }
    }

    moved (distance) {
        this.shape.move(distance)
        this.refreshOutOfBounds()
        this.redraw()
        this.refreshStrokeSelector()
        this.refreshNodes()
        this.refreshNodesSides()
    }

    rotated (rotationCenter, angle) {
        this.shape.rotated(rotationCenter, angle)
        this.redraw()
    }

    doScale (factor, center) {
        this.shape.scale(factor, center, this.stateBeforeScaling.shape)
        this.redraw()
    }

    svgElement () {
        return this.shape.shapeElement
    }

    flip (ray) {
        this.getShape().flip(ray)
        this.redraw()
        this.refreshStrokeSelector()
        this.refreshNodes()
        this.refreshNodesSides()
        return this
    }

    applyZoomToElements () {
        if (this.isMultiShape()) {
            this.shape.childrenShapesElements.forEach(shape => shape.applyZoom(this.designer))
            this.selector.allElementsSet().applyZoom(this.designer)
        } else {
            super.applyZoomToElements()
        }
    }

    visibleElementsSet () {
        let set = pushAll(seatsio.set(this.shape.visibleElementsSet(), this.positionGuides), this.objectLabel.visibleElementsSet())
        if (this.overlayIcon) {
            pushAll(set, this.overlayIcon.visibleElementsSet())
        }
        return set
    }

    visibleElementsSetWithoutChildren () {
        return seatsio.set(this.shape.visibleElementsSet())
    }

    redraw () {
        this.undraw()
        this.draw()
    }

    draw () {
        if (!this.subChart.isActive()) {
            return
        }
        this.drawShape()
        this.objectLabel.redraw()
        if (this.overlayIcon) {
            this.overlayIcon.redraw()
            this.refreshOverlayIcon()
        }
        this.objectDrawn()
        return this
    }

    drawShape () {
        const style = Object.assign(this.determineStyle())
        this.shape.draw(style, this.getLayer(), this.zIndex)
    }

    determineFillColor () {
        if (this.shape.type === 'line') {
            return undefined
        }
        if (this.fillColor !== undefined) {
            return this.fillColor
        }
        return super.determineFillColor()
    }

    getLayer () {
        if (this.type !== 'section' && this.type !== 'generalAdmission') {
            this.layer = this.shape.foreground ? 'shapesForegroundLayer' : 'shapesBackgroundLayer'
        }
        return this.layer
    }

    setForeground (foreground) {
        this.shape.foreground = foreground
        this.redraw()
    }

    undraw () {
        if (!this.subChart.isActive()) {
            return
        }
        this.objectLabel.undraw()
        this.shape.undraw()
        if (this.overlayIcon) {
            this.overlayIcon.undraw()
        }
        this.objectUndrawn()
        return this
    }

    getLabelText () {
        return this.displayLabel ? this.displayLabel : (this.sectionLabel ? `${this.sectionLabel}-` : '') + this.label
    }

    getShape () {
        return this.shape
    }

    determineBaseColor () {
        return this.fillColor
    }

    createSelectionRectangles () {
        if (this.isMultiShape()) {
            return this.shape.shapes.map(shape => this.applySelectionRectangleStyling(shape.makeShape(), shape))
        }

        return [
            this.applySelectionRectangleStyling(this.shape.makeShape())
        ]
    }

    getSelectionRectangleStyleOverrides () {
        switch (this.shape.type) {
            case 'line':
                return {
                    'stroke-width': Math.max(this.strokeWidth, seatsio.ShapedObjects.Line.MINIMUM_SELECTION_WIDTH),
                    'line-join': this.shape.lineJoin,
                    'line-cap': this.shape.lineCap,
                    'pointer-events': 'stroke',
                    // Workaround for Safari not selecting stroke outside of bounding box
                    'stroke': 'black'
                }
            default:
                return {}
        }
    }

    applySelectionRectangleStyling (shape, ownerObject = this.shape) {
        super.applySelectionRectangleStyling(shape, this.getSelectionRectangleStyleOverrides())
        shape.zoomAndRotateAround(ownerObject.rotationAngle || 0, ownerObject.getCenter(), this.designer)
        return shape
    }

    determineLabelColor () {
        if (this.isCategorisable()) {
            return super.determineLabelColor()
        }
        const isBackgroundDark = new seatsio.Color(this.determineNonHighlightedColor()).brehaut().getLuminance() < 0.7
        return isBackgroundDark ? 'white' : seatsio.Color.create(this.determineFillColor()).muchBolder().toCSS()
    }

    determineDefaultColor () {
        return this.fillColor || super.determineDefaultColor()
    }

    determineStrokeColor () {
        let color = seatsio.Color.create(this.determineBaseStrokeColor())
        if (this.isPressed) {
            return color.muchDarkened().cssString
        }
        if (this.isPainted) {
            return color.selected().cssString
        }
        return color.cssString
    }

    determineBaseStrokeColor () {
        if (this.isOutOfBounds) {
            return seatsio.Object.ERROR_COLOR
        }
        if (this.isCategorisable()) {
            return this.determineNonHighlightedColor()
        }
        return this.autoStroke ? seatsio.Color.create(this.determineNonHighlightedColor()).darkened().cssString : this.strokeColor
    }

    bbox () {
        return this.shape.bbox().enlarge(this.determineStrokeWidthWithoutScaling() / 2)
    }

    selectionIndicator () {
        return this.shape.selectionIndicator()
    }

    selectionIndicatorStyle () {
        if (this.shape.selectionIndicatorStyle) {
            return this.shape.selectionIndicatorStyle()
        }
        return undefined
    }

    pointsAsPoints () {
        return this.getPoints().map(seatsio.PolygonCornerPoint.toPoint)
    }

    smoothenedPointsAsPoints () {
        if (this.shape.cutoffAngle) {
            return new seatsio.PolygonSmoothener(this.pointsAsPoints()).smoothen(this.cutoffAngle, 3)
        } else {
            return this.pointsAsPoints()
        }
    }

    previewCutoffAngle (angle) {
        this.shape.setCutoffAngle(angle)
        this.undraw()
        this.drawShape()
    }

    setCutoffAngle (angle) {
        this.shape.setCutoffAngle(angle)
        this.redraw()
    }

    simpleDraw (color, offset = null) {
        return this.shape.simpleDraw(color, offset)
    }

    changeLabel (label) {
        seatsio.ObjectLabelSupport.prototype.changeLabel.apply(this, [label])
        seatsio.ObjectLabelSupport.prototype.refreshLabel.apply(this)
        if (this.overlayIcon) {
            this.overlayIcon.setLabel(this.getDisplayLabelOrLabel())
        }
    }

    changeDisplayLabel (displayLabel) {
        seatsio.ObjectLabelSupport.prototype.changeDisplayLabel.apply(this, [displayLabel])
        if (this.overlayIcon) {
            this.overlayIcon.setLabel(this.getDisplayLabelOrLabel())
        }
    }

    static toCornerPoints (object) {
        return object.getPoints()
    }

    static toPoints (object) {
        return object.pointsAsPoints()
    }

    toJson () {
        let json = {
            'uuid': this.uuid,
            'objectType': seatsio.ShapedObject.type
        }
        seatsio.ShapedObject.properties.forEach(prop => json[prop] = this[prop])
        this.shape.extendJson(json)
        return json
    }

    static fromJson (json, subChart) {
        let shapedObject = new seatsio.ShapedObject(subChart, seatsio.ShapeFromJson(json, subChart))
        seatsio.ShapedObject.properties.forEach(prop => {
            if (json[prop] !== undefined) shapedObject[prop] = json[prop]
        })
        if (json.autoStroke === undefined) shapedObject.autoStroke = false
        return shapedObject
    }
}

seatsio.ShapedObject.prototype.getObjectTypeName = function () {
    return 'shapedObject'
}

seatsio.ShapedObject.prototype.showVFS = function () {
    this.refreshOverlayIcon()
}

seatsio.ShapedObject.prototype.hideVFS = function () {
    this.refreshOverlayIcon()
}

seatsio.ShapedObject.prototype.refreshOverlayIcon = function () {
    if (!this.overlayIcon) {
        return
    }

    if (this.designer.viewFromSeatsShown) {
        if (this.viewFromYourSeatImage) {
            this.overlayIcon.showIcon('view-from-seats', 'highlight', () => this.designer.uiEvents.showObjectInspectorSheet(this, 'ViewFromSeat'), this.getDisplayLabelOrLabel())
        } else {
            this.overlayIcon.showIcon('view-from-seats', 'blur', () => this.designer.uiEvents.showObjectInspectorSheet(this, 'ViewFromSeat'), this.getDisplayLabelOrLabel())
        }
        this.objectLabel.hide()
    } else {
        this.overlayIcon.hide()
        this.objectLabel.show()
    }
}

seatsio.ShapeFromJson = function (json, subChart) {
    var type = json.type
    if (type === 'line') {
        return seatsio.ShapedObjects.Line.fromJson(json, subChart)
    } else if (type === 'circle') {
        return seatsio.ShapedObjects.Circle.fromJson(json, subChart)
    } else if (type === 'rectangle') {
        return seatsio.ShapedObjects.Rectangle.fromJson(json, subChart)
    } else if (type === 'polygon') {
        return seatsio.ShapedObjects.Polygon.fromJson(json, subChart)
    } else if (type === 'multishape') {
        return seatsio.ShapedObjects.MultiShape.fromJson(json, subChart)
    }
    throw new Error('Unkown shape type: ' + json.type)
}

seatsio.ShapedObject.prototype.refreshLabel = seatsio.ObjectLabelSupport.prototype.refreshLabel
seatsio.ShapedObject.prototype.redrawLabel = seatsio.ObjectLabelSupport.prototype.redrawLabel
