seatsio.ShapedObject.prototype.showLabel = seatsio.ObjectLabelSupport.prototype.showLabel
seatsio.ShapedObject.prototype.hideLabel = seatsio.ObjectLabelSupport.prototype.hideLabel
seatsio.ShapedObject.prototype.labelPosition = seatsio.ObjectLabelSupport.prototype.labelPosition
