seatsio.ShapedObject.prototype.setLabelHorizontalOffset = seatsio.ObjectLabelSupport.prototype.setLabelHorizontalOffset
seatsio.ShapedObject.prototype.setLabelVerticalOffset = seatsio.ObjectLabelSupport.prototype.setLabelVerticalOffset
seatsio.ShapedObject.prototype.setLabelHorizontalOffsetPerc = seatsio.ObjectLabelSupport.prototype.setLabelHorizontalOffsetPerc
