seatsio.ShapedObject.prototype.removePoint = seatsio.PolygonSupport.removePoint
seatsio.ShapedObject.prototype.showNodes = seatsio.PolygonSupport.showNodes
seatsio.ShapedObject.prototype.hideNodes = seatsio.PolygonSupport.hideNodes
seatsio.ShapedObject.prototype.refreshNodes = seatsio.PolygonSupport.refreshNodes
seatsio.ShapedObject.prototype.refreshNodesSides = seatsio.PolygonSupport.refreshNodesSides
seatsio.ShapedObject.prototype.showNodesSides = seatsio.PolygonSupport.showNodesSides
seatsio.ShapedObject.prototype.shouldUseClosedNodeSides = seatsio.PolygonSupport.shouldUseClosedNodeSides
seatsio.ShapedObject.prototype.hideNodesSides = seatsio.PolygonSupport.hideNodesSides
seatsio.ShapedObject.prototype.canShowStrokeSelectorOutline = seatsio.PolygonSupport.canShowStrokeSelectorOutline
seatsio.ShapedObject.prototype.showStrokeSelector = seatsio.PolygonSupport.showStrokeSelector
seatsio.ShapedObject.prototype.hideStrokeSelector = seatsio.PolygonSupport.hideStrokeSelector
seatsio.ShapedObject.prototype.refreshStrokeSelector = seatsio.PolygonSupport.refreshStrokeSelector
seatsio.ShapedObject.prototype.showNodePlaceholders = seatsio.PolygonSupport.showNodePlaceholders
seatsio.ShapedObject.prototype.hideNodePlaceholders = seatsio.PolygonSupport.hideNodePlaceholders
seatsio.ShapedObject.prototype.refreshNodePlaceholders = seatsio.PolygonSupport.refreshNodePlaceholders
seatsio.ShapedObject.prototype.pathString = seatsio.PolygonSupport.pathString
seatsio.ShapedObject.prototype.hideOverlays = seatsio.PolygonSupport.hideOverlays
seatsio.ShapedObject.prototype.restoreOverlays = seatsio.PolygonSupport.restoreOverlays

seatsio.ShapedObject.prototype.getPositionGuides = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForRect
