seatsio.ShapedObjects.MultiShape = class MultiShape extends seatsio.ShapedObjects.AbstractShape {
    constructor (subChart, shapes) {
        super()
        this.subChart = subChart
        this.designer = subChart.designer
        this.shapes = shapes
        this.childrenShapesElements = []
    }

    makeShape (childrenShapes = undefined) {
        if (!childrenShapes) {
            childrenShapes = this.makeChildrenShapes()
        }
        const group = this.designer.drawer.group()
        childrenShapes.forEach(shape => {
            group.add(shape)
            group.raphaelElement.push(shape.raphaelElement)
        })
        return group
    }

    makeChildrenShapes () {
        return this.shapes.map(shape => shape.makeShape())
    }

    scale (factor, center, stateBeforeScaling) {
        this.shapes.forEach((shape, i) => shape.scale(factor, center, stateBeforeScaling.shapes[i]))
    }

    clone () {
        let clone = new seatsio.ShapedObjects.MultiShape(this.subChart, this.shapes.map(shape => shape.clone()))
        clone.parent = this.parent
        return clone
    }

    getCenter () {
        return this.bbox().center()
    }

    getCentroid () {
        return this.getCenter()
    }

    move (distance) {
        this.shapes.forEach(shape => shape.move(distance))
    }

    moveTo (point) {
        this.shapes.forEach(shape => shape.moveTo(point))
    }

    extendJson (json) {
        json.type = 'multishape'
        json.shapes = this.shapes.map(shape => {
            const shapeJson = {}
            shape.extendJson(shapeJson)
            return shapeJson
        })
    }

    pathString () {
        var pointsSvg = this.bbox().toPoints()
            .map(point => point.x + ',' + point.y)
            .join(' L')
        return 'M' + pointsSvg + ' Z'
    }

    bbox () {
        return seatsio.Bbox.mergedFromObjects(this.shapes)
    }

    allBboxes () {
        return this.shapes.map(shape => shape.bbox())
    }

    selectionIndicator () {
        return this.bbox().toPolygon()
    }

    simpleDraw (color, offset = null) {
        return seatsio.set(this.shapes.map(shape => shape.simpleDraw(color, offset)))
    }

    draw (options, layer, zIndex) {
        this.childrenShapesElements = this.makeChildrenShapes()
        this.shapeElement = this.makeShape(this.childrenShapesElements)
        this.childrenShapesElements.forEach((element, i) => {
            const childShape = this.shapes[i]
            element
                .attr(options)
                .zoomAndRotateAround(childShape.rotationAngle || 0, childShape.getCenter(), this.designer)
        })
        this.shapeElement.toLayer(layer, this.designer, zIndex)
    }

    undraw () {
        if (this.shapeElement) {
            this.shapeElement.remove()
        }
        this.childrenShapesElements.forEach(childShapeElement => childShapeElement.remove())
    }

    applyElementAttr (attributes) {
        this.childrenShapesElements.forEach(childElement => childElement.attr(attributes))
    }

    setParent (parent) {
        super.setParent(parent)
        this.shapes.forEach(shape => shape.setParent(parent))
    }

    static fromJson (json, subChart) {
        return new seatsio.ShapedObjects.MultiShape(
            subChart,
            (json.shapes || []).map(shapeJson => seatsio.ShapeFromJson(shapeJson, subChart))
        )
    }
}

seatsio.ShapedObjects.MultiShape.prototype.type = 'multishape'

