seatsio.ShapedObjects.Circle.prototype.extendJson = function (json) {
    json.type = 'circle'
    json.center = this.center.toJson(this.subChart)
    json.rotationAngle = this.rotationAngle
    json.radius1 = this.radius1
    json.radius2 = this.radius2
    json.foreground = this.foreground
}

seatsio.ShapedObjects.Circle.prototype.pathString = function () {
    var rx = this.radius1
    var ry = this.radius2

    var output = 'M' + (this.center.x - rx).toString() + ',' + this.center.y.toString()
    output += 'a' + rx.toString() + ',' + ry.toString() + ' 0 1,0 ' + (2 * rx).toString() + ',0'
    output += 'a' + rx.toString() + ',' + ry.toString() + ' 0 1,0 ' + (-2 * rx).toString() + ',0'
    return output
}

seatsio.ShapedObjects.Circle.prototype.bbox = function () {
    return new seatsio.EllipseShape(this.center, this.radius1, this.radius2, this.rotationAngle).bbox()
}

seatsio.ShapedObjects.Circle.prototype.toPoints = function (sides = 8) {
    let points = []
    for (let side = 0; side < sides; side++) {
        let angleRad = 2 * Math.PI * side / sides
        points.push(new seatsio.Point(this.center.x + Math.cos(angleRad) * this.radius1, this.center.y + Math.sin(angleRad) * this.radius2).rotateAround(this.center, this.rotationAngle))
    }
    return points
}

seatsio.ShapedObjects.Circle.prototype.toPolygon = function () {
    return new seatsio.PolygonShape(this.toPoints())
}

seatsio.ShapedObjects.Circle.prototype.selectionIndicator = function () {
    const PADDING_TO_NOT_OVERLAP_WITH_OUTLINE_TOO_MUCH = 0.5
    return new seatsio.EllipseShape(this.center, this.radius1, this.radius2, this.rotationAngle)
        .enlargeByAmount(this.parent.determineStrokeWidth() / 2 + PADDING_TO_NOT_OVERLAP_WITH_OUTLINE_TOO_MUCH)
}

seatsio.ShapedObjects.Circle.prototype.selectionIndicatorStyle = function () {
    return 'shape'
}

seatsio.ShapedObjects.Circle.prototype.simpleDraw = function (color, offset = null) {
    let center = offset ? this.center.add(offset) : this.center
    return this.designer.drawer.ellipse(center.x, center.y, this.radius1, this.radius2,
        {
            'stroke-width': 0,
            'fill': color
        })
}

seatsio.ShapedObjects.Circle.prototype.scale = function (factor, center, stateBeforeScaling) {
    this.radius1 = Math.round(stateBeforeScaling.radius1 * factor)
    this.radius2 = Math.round(stateBeforeScaling.radius2 * factor)
    this.center = new seatsio.Ray(center, stateBeforeScaling.center).enlargeByFactor(factor).end
}

seatsio.ShapedObjects.Circle.createShape = function (subChart, shiftWasPressed, fromPosition, toPosition) {
    let inverseX = fromPosition.x > toPosition.x ? -1 : 1
    let inverseY = fromPosition.y > toPosition.y ? -1 : 1
    let radius1 = Math.max(2, Math.abs(toPosition.x - fromPosition.x)) / 2
    let radius2 = shiftWasPressed ? radius1 : Math.max(2, Math.abs(toPosition.y - fromPosition.y)) / 2
    let center = fromPosition.addToX(radius1 * inverseX).addToY(radius2 * inverseY)
    return new seatsio.ShapedObjects.Circle(subChart, center, radius1, radius2)
}

seatsio.ShapedObjects.Circle.drawShapes = function (subChart, shiftWasPressed, fromPosition, toPosition) {
    return seatsio.ShapedObjects.Circle.createShape(subChart, shiftWasPressed, fromPosition, toPosition).makeShape()
}

seatsio.ShapedObjects.Circle.fromJson = function (json, subChart) {
    return new seatsio.ShapedObjects.Circle(
        subChart,
        seatsio.Point.fromJson(json.center, subChart),
        json.radius1,
        json.radius2,
        json.rotationAngle,
        json.foreground
    )
}

