seatsio.GeneralAdmissionArea.fromJson = function (json, subChart) {
    let area = new seatsio.GeneralAdmissionArea(subChart, seatsio.ShapeFromJson(json, subChart))
    area.capacity = json.capacity
    area.label = json.label
    area.displayLabel = json.displayLabel
    area.labelHorizontalOffset = json.labelHorizontalOffset
    area.labelVerticalOffset = json.labelVerticalOffset
    area.applyCategory(subChart.designer.categories.getCategory(json.categoryKey))
    area.zone = json.zone
    area.objectLabeling = seatsio.ObjectLabeling.fromJson(json.objectLabeling)
    area.uuid = json.uuid
    area.entrance = json.entrance
    area.translucent = json.translucent || false
    area.viewFromYourSeatImage = json.viewFromYourSeatImage
    area.labelSize = json.labelSize
    area.labelShown = json.labelShown
    area.cutoffAngle = json.cutoffAngle
    area.bookAsAWhole = json.bookAsAWhole || false
    area.variableOccupancy = json.variableOccupancy || false
    area.minOccupancy = json.minOccupancy || 1
    area.published = json.published !== undefined ? json.published : subChart.designer.isPublished()
    return area
}

seatsio.GeneralAdmissionArea.prototype.minScaleFactor = function () {
    if (this.stateBeforeScaling.shape.getWidth() !== null) {
        return Math.max(seatsio.GeneralAdmissionArea.getMinSize() / this.stateBeforeScaling.shape.getWidth(), seatsio.GeneralAdmissionArea.getMinSize() / this.stateBeforeScaling.shape.getHeight())
    }
    return seatsio.Object.prototype.minScaleFactor.apply(this)
}

seatsio.GeneralAdmissionArea.prototype.getMinimumBboxSideLength = function () {
    return seatsio.GeneralAdmissionArea.getMinSize()
}

