seatsio.Layers = function (designer) {
    this.designer = designer
    this.layers = []
}

seatsio.Layers.prototype.createLayer = function (name) {
    var previousLayer = this.layers.length === 0 ? null : this.layers[this.layers.length - 1]
    this.layers.push(new seatsio.Layer(name, previousLayer))
    return this
}

seatsio.Layers.prototype.get = function (name) {
    return this.layers.findOne(function (layer) {
        return layer.name === name
    })
}

seatsio.Layers.prototype.add = function (el, layerName, zIndex) {
    this.layers
        .filter(function (layer) {
            return layer.name !== layerName
        })
        .forEach(function (layer) {
            layer.remove(el)
        })
    this.get(layerName).add(el, zIndex)
}

seatsio.Layer = function (name, previousLayer) {
    this.name = name
    this.previousLayer = previousLayer
    this.objects = new SortedArray(seatsio.Layer.compareObjects)
}

seatsio.Layer.compareObjects = (a, b) => {
    return a.seatsioZIndex - b.seatsioZIndex
}

seatsio.Layer.prototype.add = function (object, zIndex = Number.POSITIVE_INFINITY) {
    object.seatsioLayer = this
    object.seatsioZIndex = zIndex
    let position = this.objects.insert(object)

    var objectToInsertAfter = this.findObjectToInsertAfter(position)
    if (objectToInsertAfter) {
        object.insertAfter(objectToInsertAfter)
    } else {
        object.back()
    }
}

seatsio.Layer.prototype.findFirstObjectInPreviousLayer = function () {
    if (!this.previousLayer) {
        return
    }
    if (this.previousLayer.objects.length === 0) {
        return this.previousLayer.findFirstObjectInPreviousLayer()
    }
    return this.previousLayer.objects[this.previousLayer.objects.length - 1]
}

seatsio.Layer.prototype.findObjectToInsertAfter = function (position) {
    if (position === 0) {
        return this.findFirstObjectInPreviousLayer()
    }
    return this.objects[position - 1]
}

seatsio.Layer.prototype.remove = function (el) {
    this.objects.remove(el)
    el.seatsioLayer = undefined
    el.seatsioZIndex = undefined
}

