seatsio.SectionPolygonState = function (designer) {
    this.designer = designer
    this.name = 'sectionPolygonState'
    this.snapper = new seatsio.PolygonDrawingSnapper(this.designer, ['closestCornerPoint'])
    this.toolName = 'section-polygon'
    this.toolHint = 'nodesWithModifiers-hint'
    this.cursor = 'precision-drawing'
}

seatsio.SectionPolygonState.prototype = new seatsio.ToolState()

seatsio.SectionPolygonState.prototype.init = function () {
    this.positionGuidesSet = new seatsio.PositionGuidesSet(this.designer)
}

seatsio.SectionPolygonState.prototype.onCanvasMouseMove = function (e) {
    let fromPosition = seatsio.Point.fromEvent(e, this.designer)
    let { snapCorner, snapPoint, snapType, snapRay, snapSecondRay } = this.snap(fromPosition)
    if (snapType === 'closestCorner') {
        this.snapCorner(snapCorner, snapType)
    } else {
        this.unsnapCorner()
    }
    if (snapPoint) {
        this.positionGuidesSet.refresh(seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint(this.designer, snapPoint, snapType, snapRay, snapSecondRay))
    } else {
        this.positionGuidesSet.undraw()
    }
}

seatsio.SectionPolygonState.prototype.onCanvasMouseDown = function (e) {
    this.toDrawingState(e)
}

seatsio.SectionPolygonState.prototype.onObjectClicked = function (object, e) {
    this.onCanvasMouseDown(e)
}

seatsio.SectionPolygonState.prototype.toDrawingState = function (e) {
    this.designer.setState(new seatsio.SectionPolygonDrawingState(this.designer, this.snap(seatsio.Point.fromEvent(e, this.designer)).snapPoint))
}

seatsio.SectionPolygonState.prototype.onEscapePressed = function () {
    this.cancel()
}

seatsio.SectionPolygonState.prototype.onCanvasRightMouseButtonDown = function () {
    this.reenter()
}

seatsio.SectionPolygonState.prototype.snap = function (point) {
    return this.snapper.snap(null, point)
}

seatsio.SectionPolygonState.prototype.cancel = function () {
    this.designer.uiEvents.toolSelectCursor()
}

seatsio.SectionPolygonState.prototype.reenter = function () {
    this.designer.setState(new seatsio.SectionPolygonState(this.designer))
}

seatsio.SectionPolygonState.prototype.snapCorner = function (snapCorner, snapType) {
    if (this.lastSnapCorner === snapCorner) return
    this.unsnapCorner()
    this.lastSnapCorner = snapCorner
    this.lastSnapCorner.snap(snapType)
}

seatsio.SectionPolygonState.prototype.unsnapCorner = function () {
    if (this.lastSnapCorner) {
        this.lastSnapCorner.unsnap()
        this.lastSnapCorner = null
    }
}

seatsio.SectionPolygonState.prototype.exit = function () {
    this.unsnapCorner()
    this.positionGuidesSet.undraw()
}

seatsio.SectionPolygonDrawingState = function (designer, lastPoint, enableSmoothing = true) {
    this.designer = designer
    this.name = 'sectionPolygonDrawingState'
    this.line = new seatsio.PolygonDrawingLine(designer, enableSmoothing)
    this.points = [lastPoint]
    this.pointsAnchors = []
    this.tempSectionShape = null
    this.snapper = new seatsio.PolygonDrawingSnapper(designer, ['closestCornerPoint'])
    this.toolName = 'section-polygon'
    this.toolHint = 'nodesWithModifiers-hint'
    this.cursor = 'precision-drawing'
    this.cutoffAngle = seatsio.PolygonSmoothener.DEFAULT_CUTOFF_ANGLE
    this.enableSmoothing = enableSmoothing
}

seatsio.SectionPolygonDrawingState.prototype = new seatsio.ToolState()

seatsio.SectionPolygonDrawingState.prototype.init = function () {
    this.pointsAnchors.push(seatsio.PolygonCornerPoint.drawCorner(this.points.last(), this.designer))
    const positionGuidesForPoint = seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint(this.designer, this.points.last())
    this.positionGuidesSet = new seatsio.PositionGuidesSet(this.designer, positionGuidesForPoint).draw()
}

seatsio.SectionPolygonDrawingState.prototype.getLinePositionSnapSettings = function () {
    return this.snapper.snap(this.points.last(), this.lastMousePointerPosition, this.points)
}

seatsio.SectionPolygonDrawingState.prototype.refreshLinePosition = function () {
    let { snapPoint, snapType, snapRay, snapSecondRay } = this.getLinePositionSnapSettings()
    this.line.draw(this.points.beforeLast(), this.points.last(), snapPoint, snapType, this.cutoffAngle)
    seatsio.PolygonCornerPoint.applyElementAttributes(this.line.corner, this.line.toPosition, snapType)
    this.positionGuidesSet.refresh(seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint(this.designer, snapPoint, snapType, snapRay, snapSecondRay))
}

seatsio.SectionPolygonDrawingState.prototype.onModifierChange = function () {
    this.refreshLinePosition()
}

seatsio.SectionPolygonDrawingState.prototype.onCanvasMouseMove = function (e) {
    this.lastMousePointerPosition = seatsio.Point.fromEvent(e, this.designer)
    this.refreshLinePosition()
}

seatsio.SectionPolygonDrawingState.prototype.onCanvasMouseUp = function (e) {
    this.lastMousePointerPosition = seatsio.Point.fromEvent(e, this.designer)
}

seatsio.SectionPolygonDrawingState.prototype.onCanvasMouseDown = function (e) {
    this.addPoint(e)
}

seatsio.SectionPolygonDrawingState.prototype.onObjectClicked = function (object, e) {
    this.onCanvasMouseDown(e)
}

seatsio.SectionPolygonDrawingState.prototype.addPoint = function (e) {
    let { snapPoint } = this.snapper.snap(this.points.last(), seatsio.Point.fromEvent(e, this.designer), this.points)
    if (this.points.first().equals(snapPoint)) {
        this.createPolygonShapedObjectAndAddToChart()
    } else {
        this.points.push(snapPoint)
        this.pointsAnchors.push(seatsio.PolygonCornerPoint.drawCorner(snapPoint, this.designer))
        this.extendTempSectionShape()
        this.refreshLinePosition()
    }
}

seatsio.SectionPolygonDrawingState.prototype.removePoint = function () {
    this.points.pop()
    let lastAnchor = this.pointsAnchors.pop()
    lastAnchor.remove()
    this.extendTempSectionShape()
    this.refreshLinePosition()
}

seatsio.SectionPolygonDrawingState.prototype.createPolygonShapedObjectAndAddToChart = function () {
    if (!new seatsio.PolygonShape(this.points).isAreaLargeEnoughOnScreen(this.designer.zoomer.zoomLevel)) {
        return
    }
    let section = seatsio.Section.fromPoints(this.points, this.cutoffAngle, this.designer)
    this.designer.activeSubChart().sections.add(section)
    section.draw()
    this.positionGuidesSet.undraw()
    this.designer.setState(new seatsio.SectionPolygonState(this.designer))
}

seatsio.SectionPolygonDrawingState.prototype.extendTempSectionShape = function () {
    if (this.tempSectionShape) {
        this.tempSectionShape.remove()
    }
    const points = this.enableSmoothing
        ? new seatsio.LineSmoothener(this.points).smoothen(this.cutoffAngle, 3)
        : this.points
    this.tempSectionShape = this.designer.drawer.path(seatsio.Section.pathString(points),
        {
            'stroke': '#005cc5',
            'stroke-width': this.designer.zoomer.unzoom(1),
            'stroke-linejoin': 'round'
        })
        .toLayer(seatsio.Section.LAYER, this.designer)
        .applyZoom(this.designer)
}

seatsio.SectionPolygonDrawingState.prototype.onEscapePressed = function () {
    this.reenter()
}

seatsio.SectionPolygonDrawingState.prototype.onCanvasRightMouseButtonDown = function () {
    if (this.points.length > 1) {
        this.removePoint()
    } else {
        this.reenter()
    }
}

seatsio.SectionPolygonDrawingState.prototype.cancel = function () {
    this.designer.uiEvents.toolSelectCursor()
}

seatsio.SectionPolygonDrawingState.prototype.reenter = function () {
    this.designer.setState(new seatsio.SectionPolygonState(this.designer))
}

seatsio.SectionPolygonDrawingState.prototype.exit = function () {
    if (this.tempSectionShape) {
        this.tempSectionShape.remove()
    }
    if (this.positionGuidesSet) {
        this.positionGuidesSet.undraw()
    }
    this.line.undraw()
    this.pointsAnchors.forEach(polygonCornerPoint => polygonCornerPoint.remove())
}

