seatsio.SectionRectangleDrawingState = function (designer, fromPosition) {
    this.designer = designer
    this.fromPosition = fromPosition
    this.lines = this.createLines(designer)
    this.points = this.createPoints(fromPosition)
    this.snapper = new seatsio.PolygonDrawingSnapper(designer, ['closestCornerPoint'])
    this.toolName = 'section-rectangle'
    this.toolHint = 'clickDragToDraw-hint'
    this.cursor = 'precision-drawing'
}

seatsio.SectionRectangleDrawingState.prototype = new seatsio.ToolState()

seatsio.SectionRectangleDrawingState.prototype.init = function () {
    this.positionGuidesSet = new seatsio.PositionGuidesSet(this.designer, seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint(this.designer, this.fromPosition))
        .draw()
}

seatsio.SectionRectangleDrawingState.prototype.createLines = function (designer) {
    return [new seatsio.PolygonDrawingLine(designer), new seatsio.PolygonDrawingLine(designer), new seatsio.PolygonDrawingLine(designer), new seatsio.PolygonDrawingLine(designer)]
}

seatsio.SectionRectangleDrawingState.prototype.createPoints = function (fromPosition) {
    return [fromPosition, fromPosition.addToX(1), fromPosition.addToXAndY(1, 1), fromPosition.addToY(1)]
}

seatsio.SectionRectangleDrawingState.prototype.refreshPoints = function (toPosition) {
    let [_topLeft, topRight, bottomRight, bottomLeft] = this.points
    topRight.x = toPosition.x
    bottomRight.x = toPosition.x
    bottomRight.y = toPosition.y
    bottomLeft.y = toPosition.y
}

seatsio.SectionRectangleDrawingState.prototype.refreshRectangle = function () {
    let { snapPoint, snapType, snapRay, snapSecondRay } = this.snapper.snap(this.fromPosition, this.toPosition)
    this.refreshPoints(snapPoint)
    let [topLeftPoint, topRightPoint, bottomRightPoint, bottomLeftPoint] = this.points
    let [topLine, rightLine, bottomLine, leftLine] = this.lines
    topLine.drawStraight(topLeftPoint, topRightPoint)
    rightLine.drawStraight(topRightPoint, bottomRightPoint, snapType)
    bottomLine.drawStraight(bottomRightPoint, bottomLeftPoint)
    leftLine.drawStraight(bottomLeftPoint, topLeftPoint)
    seatsio.PolygonCornerPoint.applyElementAttributes(rightLine.corner, rightLine.toPosition, snapType)
    this.positionGuidesSet.refresh(seatsio.PositionGuidesSupport.prototype.getPositionGuidesForPoint(this.designer, snapPoint, snapType, snapRay, snapSecondRay))
}

seatsio.SectionRectangleDrawingState.prototype.onModifierChange = function () {
    this.refreshRectangle()
}

seatsio.SectionRectangleDrawingState.prototype.onCanvasMouseMove = function (e) {
    this.toPosition = seatsio.Point.fromEvent(e, this.designer)
    this.refreshRectangle()
}

seatsio.SectionRectangleDrawingState.prototype.onCanvasMouseUp = function (e) {
    if (new seatsio.PolygonShape(this.points).isAreaLargeEnoughOnScreen(this.designer.zoomer.zoomLevel)) {
        this.createPolygonShapedObjectAndAddToChart()
    }
    this.designer.setState(new seatsio.SectionRectangleState(this.designer))
}

seatsio.SectionRectangleDrawingState.prototype.createPolygonShapedObjectAndAddToChart = function () {
    let section = seatsio.Section.fromPoints(this.points, 180, this.designer)
    this.designer.activeSubChart().sections.add(section)
    section.draw()
}

seatsio.SectionRectangleDrawingState.prototype.onEscapePressed = function () {
    this.reenter()
}

seatsio.SectionRectangleDrawingState.prototype.onCanvasRightMouseButtonDown = function () {
    this.reenter()
}

seatsio.SectionRectangleDrawingState.prototype.cancel = function () {
    this.designer.uiEvents.toolSelectCursor()
}

seatsio.SectionRectangleDrawingState.prototype.reenter = function () {
    this.designer.setState(new seatsio.SectionRectangleState(this.designer))
}

seatsio.SectionRectangleDrawingState.prototype.exit = function () {
    if (this.positionGuidesSet) {
        this.positionGuidesSet.undraw()
    }
    this.lines.forEach(line => line.undraw())
}

