seatsio.ShapePolygonDrawingState = class ShapePolygonDrawingState extends seatsio.SectionPolygonDrawingState {
    constructor (designer, fromPosition, enableSmoothing = true) {
        super(designer, fromPosition, enableSmoothing)
        this.toolName = 'shape-polygon'
    }

    createPolygonShapedObjectAndAddToChart () {
        if (this.points.length < 3) {
            return
        }
        const polygon = seatsio.ShapedObjects.Polygon.fromPoints(this.designer.activeSubChart(), this.points, this.cutoffAngle)
        let shape = new seatsio.ShapedObject(this.designer.activeSubChart(), polygon)
        this.designer.activeSubChart().shapes.add(shape)
        shape.draw()
        this.designer.setState(new seatsio.ShapePolygonState(this.designer))
    }

    reenter () {
        this.designer.setState(new seatsio.ShapePolygonState(this.designer))
    }
}

