seatsio.LineDrawingState = class LineDrawingState extends seatsio.ShapePolygonDrawingState {
    constructor (designer, fromPosition, enableSmoothing = false) {
        super(designer, fromPosition, enableSmoothing)
        const drawingStyle = { 'stroke-dasharray': this.designer.zoomer.unzoom(4), opacity: 0.75 }
        this.line = new seatsio.PolygonDrawingLine(designer, enableSmoothing, drawingStyle)
        this.snapper = new seatsio.PolygonDrawingSnapper(designer, ['lastCornerPoint'])
        this.toolName = 'line'
        this.toolHint = 'shape-line-hint'
    }

    onEnterPressed () {
        this.createLineShapeObjectAndAddToChart()
    }

    addPoint (e) {
        let { snapPoint } = this.snapper.snap(this.points.last(), seatsio.Point.fromEvent(e, this.designer), this.points)
        if (this.points.last().equals(snapPoint)) {
            this.createLineShapeObjectAndAddToChart()
        } else {
            this.points.push(snapPoint)
            this.pointsAnchors.push(seatsio.PolygonCornerPoint.drawCorner(snapPoint, this.designer))
            this.extendTempSectionShape()
            this.refreshLinePosition()
        }
    }

    getStrokeWidth () {
        return this.designer.getToolProperty('Line.strokeWidth')
    }

    createLineShapeObjectAndAddToChart () {
        if (this.points.length < 2) {
            return
        }

        const line = new seatsio.ShapedObjects.Line(this.designer.activeSubChart(), this.points)
        let shape = new seatsio.ShapedObject(this.designer.activeSubChart(), line)
        shape.setStrokeColor(seatsio.ColorPalettes.palettes.platinum.colors.light[1])
        shape.setStrokeWidth(this.getStrokeWidth())
        this.designer.activeSubChart().shapes.add(shape)
        this.designer.setState(new seatsio.ShapeLineState(this.designer))
    }

    toDrawingState (e) {
        this.designer.setState(new seatsio.LineDrawingState(this.designer, this.snap(seatsio.Point.fromEvent(e, this.designer)).snapPoint))
    }

    reenter () {
        this.designer.setState(new seatsio.ShapeLineState(this.designer))
    }
}

