Dialogs.FloatingDialogs.CategoriesInfo = class CategoriesInfo extends Dialogs.FloatingDialog {
    constructor(props) {
        super(props);
        this.state = {
            activeTab: this.isEditingDisabled() ? 'keys' : 'categories'
        };
    }

    title() {
        return d('categories');
    }

    className() {
        return 'CategoriesInfo';
    }

    isEditingEnabled() {
        return seatsio.designer.features.isEnabled(seatsio.Features.Type.CATEGORY_LIST);
    }

    isEditingDisabled() {
        return seatsio.designer.features.isReadOnly(seatsio.Features.Type.CATEGORY_LIST) || this.isApplyingDisabled();
    }

    isApplyingDisabled() {
        return seatsio.designer.features.isDisabled(seatsio.Features.Type.CATEGORY_LIST);
    }

    getCategoriesDetails() {
        if (this.state.activeTab === 'keys') {
            return React.createElement(
                'div',
                { className: 'list', key: 'list-categories' },
                this.props.document.categories.map(category => {
                    return React.createElement(
                        'div',
                        { className: 'item', key: category.key },
                        React.createElement(
                            'div',
                            { className: 'caption' },
                            React.createElement(
                                'div',
                                { className: 'color', style: { backgroundColor: category.color } },
                                category.accessible && React.createElement('div', { className: 'icon-accessible-new' })
                            ),
                            React.createElement(
                                'span',
                                { className: 'categoryLabel', title: d('category') },
                                category.label
                            )
                        ),
                        React.createElement(
                            'div',
                            { className: 'rightValue horizontal-flex' },
                            this.state.editingKey === category.key ? React.createElement(
                                'span',
                                { className: 'horizontal-flex' },
                                React.createElement(TextInput, {
                                    value: category.key,
                                    onChangeFinal: newKey => this.commitKeyEdit(category.key, newKey),
                                    autoFocus: true,
                                    onEditEnd: this.endKeyEdit.bind(this),
                                    escCancelsEdit: true
                                }),
                                React.createElement('span', { className: 'action icon icon-check' })
                            ) : React.createElement(
                                React.Fragment,
                                null,
                                React.createElement(
                                    'span',
                                    { className: 'fixed-width multiline' },
                                    React.createElement(
                                        'span',
                                        { className: 'unit' },
                                        d('key')
                                    ),
                                    '\xA0',
                                    React.createElement(
                                        'span',
                                        { className: 'selectable' },
                                        typeof category.key === 'string' ? React.createElement(
                                            React.Fragment,
                                            null,
                                            React.createElement(
                                                'span',
                                                { className: 'soft' },
                                                '"'
                                            ),
                                            category.key,
                                            React.createElement(
                                                'span',
                                                { className: 'soft' },
                                                '"'
                                            )
                                        ) : category.key
                                    )
                                ),
                                this.isEditingEnabled() && React.createElement('span', { className: 'action icon icon-edit', onClick: () => this.beginKeyEdit(category.key) })
                            )
                        )
                    );
                })
            );
        } else {
            return React.createElement(
                React.Fragment,
                null,
                React.createElement(CategoryPicker, {
                    categories: this.props.document.categories,
                    disabled: this.isApplyingDisabled(),
                    editingDisabled: this.isEditingDisabled(),
                    onReorderItem: (fromIndex, toIndex) => seatsio.designer.uiEvents.reorderCategory(fromIndex, toIndex)
                })
            );
        }
    }

    componentDidUpdate() {
        if (this.pendingKeyEdit && this.props.designer.ignoredLabelEditingWarnings.includes('categoryKey')) {
            this.setState({ editingKey: this.pendingKeyEdit });
            this.pendingKeyEdit = null;
        }
    }

    beginKeyEdit(key) {
        if (this.props.designer.chartHasEvents && !this.props.designer.ignoredLabelEditingWarnings.includes('categoryKey')) {
            this.pendingKeyEdit = key;
            seatsio.designer.uiEvents.showCategoryKeyEditWarning();
        } else {
            this.setState({ editingKey: key });
        }
    }

    commitKeyEdit(prevKey, newKey) {
        newKey = detectCategoryKeyType(newKey);
        if (!seatsio.designer.uiEvents.changeCategoryKey(prevKey, newKey)) {
            alert(d('category-key-already-exists', { key: typeof newKey === 'string' ? `"${newKey}"` : newKey }));
        }
        this.endKeyEdit();
    }

    endKeyEdit() {
        this.setState({ editingKey: null });
    }

    contents() {
        return React.createElement(
            React.Fragment,
            null,
            React.createElement(
                'div',
                { className: 'tip dragHandle', onMouseDown: this.onMouseDown.bind(this) },
                d('categories-info-description-1')
            ),
            !this.isEditingDisabled() && React.createElement(TabSwitcher, {
                value: this.state.activeTab,
                options: [{
                    label: d('categories'),
                    value: 'categories'
                }, {
                    label: d('keys'),
                    value: 'keys'
                }],
                onChange: value => this.setState({ activeTab: value })
            }),
            this.getCategoriesDetails()
        );
    }
};
