Dialogs.FloatingDialogs.Preview = class Preview extends Dialogs.FloatingDialog {
    constructor(props) {
        super(props);
        this.rerenderPreview = _.debounce(this.rerenderPreview, 750);
    }

    title() {
        return d('preview');
    }

    className() {
        return `Preview ${this.props.document.colorScheme}`;
    }

    componentDidMount() {
        super.componentDidMount();
        this.renderPreview();
    }

    componentDidUpdate(prevProps) {
        super.componentDidUpdate();
        if (!_.isEqual(prevProps.document.chartJsonForPreview, this.props.document.chartJsonForPreview)) {
            this.rerenderPreview();
        }
    }

    rerenderPreview() {
        this.deletePrevChart();
        this.prevChart = this.chart;
        this.renderPreview();
    }

    deletePrevChart() {
        if (this.prevChart) {
            this.prevChart.destroy();
            this.prevChart = null;
        }
    }

    renderPreview() {
        this.chart = new seatingMapJuzai.SeatingChart({
            divId: 'chartPreview',
            workspaceKey: this.props.document.workspaceKey,
            chart: this.props.document.chartKey,
            mode: 'static',
            onChartRendered: this.deletePrevChart.bind(this),
            chartJsonForPreview: this.props.document.chartJsonForPreview,
            fitTo: 'widthAndHeight',
            colorScheme: this.props.document.colorScheme || 'light'
        }).render();
    }

    componentWillUnmount() {
        super.componentWillUnmount();
        this.deletePrevChart();
        this.chart.destroy();
    }

    contents() {
        return React.createElement('div', { id: 'chartPreview' });
    }
};
