class ZonesEditableList extends React.Component {
    onDelete(key) {
        seatsio.designer.uiEvents.deleteZone(key);
    }

    setKey(key, nextKey) {
        seatsio.designer.uiEvents.setZoneKey(key, nextKey);
    }

    setLabel(key, value) {
        seatsio.designer.uiEvents.setZoneLabel(key, value);
    }

    createZone() {
        seatsio.designer.uiEvents.createZone();
        requestAnimationFrame(() => this.wrapperRef.scroll(0, 1000000));
    }

    renderList() {
        return this.props.zones.map(zone => {
            return React.createElement(ZoneListItem, {
                key: zone.key,
                zoneKey: zone.key,
                label: zone.label,
                canBeDeleted: zone.canBeDeleted,
                onKeyChange: nextKey => this.setKey(zone.key, nextKey),
                onLabelChange: value => this.setLabel(zone.key, value),
                onDelete: () => this.onDelete(zone.key)
            });
        });
    }

    render() {
        return React.createElement(
            'div',
            { className: 'ZonesEditableList', ref: node => this.wrapperRef = node },
            !this.props.disabled && !this.props.editingDisabled && React.createElement(
                'div',
                { className: 'ZoneListItem create', onClick: () => this.createZone() },
                React.createElement('div', { className: 'icon icon-plus-bold' }),
                React.createElement(
                    'div',
                    { className: 'label' },
                    d('create-new-zone')
                )
            ),
            this.renderList()
        );
    }
}

