                preset: 'caption-icon',
                disabled: !this.canGoNextSlide(),
                type: hasNextSlide ? 'arrow-light-right' : null,
                color: 'link',
                caption: d(hasNextSlide ? 'next' : 'done'),
                onClick: () => this.nextSlide(),
