        this.SCANNING_INTRODUCTION_SLIDE = 0;
        this.SCANNING_SLIDE = 1;
        this.LAST_SLIDE = this.SCANNING_SLIDE;

        this.SCANNING_SLIDE_STEP_ONE = 1;
