    selectTypeOption(value) {
        let selectedOption = Inspector.Sheets.Misc.tableTypeOptions[value];
        seatsio.designer.uiEvents.setSelectionBookAsAWhole(selectedOption.bookAsAWhole);
        seatsio.designer.uiEvents.setSelectionVariableOccupancy(selectedOption.variableOccupancy);
    }
